/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210930-4","meetingId":"r03-c-settlement","date":"2021年9月30日","dateIso":"2021-09-30","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を129件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"小芝副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和２年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"おはようあります。私は、まず初めに決算全体について伺っていきたいと考えています。そこで、まず伺いたいのが、結果として普通会計の実質収支は約３５億円の黒字になりましたということで、健全財政が維持されているということであります。補正は７回ぐらい組んでいるけれども、この１年間の苦労をどのように考えて、どういうふうに対応してきたのかというのをお聞きしたい。","respondent":"黒田財政課長","answer":"しながわ活力応援給付金の財源につきましては、財政調整基金などを活用しまして、これまで培った財政力を活かして事業を行ったですので、全体では、先ほどご説明しましたが、基金全体で約１４９億円ほど減っておりますが、これは。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、もうやらなくていいのではないかとか、やらないほうが楽というような声があったり、我々が統制している町会長や高齢者クラブの方々というのは、これは１年会わないと、やけに年を取ったと感じたりもする。ですから、その辺の部分の意気込みと、こういうときだからこそ、そういうこともやっていく。そういうことを、来年度予算に向けて、地域をもう一回活性化していくのだ。よろしくお願いします。","respondent":"濱野区長","answer":"これが大切なことだと思います。そして、その地域の力と区議会の力とが相まって、品川区の発展、そして品川区民の幸せが築かれると考えています。そのように、また区も努力していきたいと思います。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、保健所関連で２つ、お伺いします。９０ページ、感染症予防費に関連しまして、ＨＰＶワクチンについてというところで、まずお聞きします。福内健康推進部長がいろいろお話しされているのも拝見させていただきましたけれども、やはりコロナ患者を受け入れるためのベッドというものを増床するように、品川区独自で、これは品川区内の病院で、強い要請をするべきだと思うのですが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"平成３０年からの推移を見てみますと、同じような計算で、平成３０年０.５２％、令和元年１.０４％、令和２年が３.９％、今年、令和３年ですが、８月末までの接種した人数を今年度に合わせますと、今年は新中学１年生。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"妻は慎重にすべきだと。その後の、いわゆる副反応的なものも出なかったということであるのですが、１つお伺いしたいのは、９月ということで、ぎりぎりだったわけです。現在、そのことについて、コロナで怖くて外に出たくないという方について、今はいろいろなワクチン接種についても、期限については柔軟に対応していると伺っているのですが、それについて、ＨＰＶワクチンはどうなのかというところ。","respondent":"鷹箸保健予防課長","answer":"ですので、その件については、これまでのところ、お申し出があった方について個別の医療機関で対応していただく旨、医師会にお願いしているところですが、個別の通知や積極的な広報に努めているという部分は確かにございませんので、そのことについては。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"もう一つ言うと、昨年高校１年生だった子、去年の今頃に打たなかった子は、打つ機会も失っているのです。この対象についてはどのようにお考えなのか教えてください。","respondent":"鷹箸保健予防課長","answer":"対象になるということも含めて、周知を考えていきたいと思います。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"意見","question":"本日は、決算書９６ページ、新型コロナウイルスワクチン接種体制確保事業費補助金に関連して、品川区の新型コロナウイルスワクチンの接種体制についてお尋ねしてまいります。そして、新型コロナウイルスワクチン接種を迅速に進めるために、様々な接種方法が採用されてきました。現在に至る新型コロナウイルスワクチン接種体制とその進行状況、今後の見通しについて簡単にご説明をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後は接種終了に向けて、集団接種会場を閉鎖・縮小してまいりまして、一部の医療機関で引き続き接種ができるような体制を取る予定です。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"重ねてご質問させていただきたいと思うのですが、実際、６か月未満の早期の乳児および新生児に関してはいかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"６か月未満の陽性者は、４８名中、１９名で、そのうち、重症化されたお子さんは幸いにもいませんでした。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"小児は７０％が、今、課長からご説明がありましたように、家庭内の感染と言われておりますが、小さな赤ちゃんはほとんどが家庭内の感染で、しかも保護者が感染したとしても隔離することはできません。ただ、現在は状況が全く違います。以上のような見解から、現在、個別接種の対象に乳児の親というのが含まれておりませんが、この点に関して、区のお考え、ご見解はいかがでしょうか。伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"妊婦については、集団接種会場にて優先枠を設置いたしまして対応してまいりました。しかしながら、赤ちゃんのご両親への接種については、委員ご指摘の内容を踏まえまして、今後、区として検討してまいりたいと考えております。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"集団接種が、ワクチンの個数の関係で、だんだん縮小、それから廃止の方向に向かっているということをお伺いしました。したがって、集団接種と個別接種の両輪で、ワクチンの接種を今後もしっかりと進めていただきたいということを要望しまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから第６波を起こさないための対策、同時に第６波が起きた場合の備えを行うことが必要だと思います。区としてこれまでの対応についてどう検証されているのかについて、まず伺いたいと思います。職場を１か月以上休まざるを得ないということは、親にとっては本当に大変なことです。こうした状況を再び起こさないために、改善すべき対策について、区としてどう考えているのか、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"ＰＣＲ検査につきましては、第５波の感染者が非常に増えましたときに、迅速な対応が感染者の方に対して難しくなったところから、やむなく９月１日から９月１９日の間に限りまして。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本来であれば、検査をもっと拡大してやるべきところ、濃厚接触者でさえ検査を行わないということは、感染者の把握ができないこと、それから陽性と陰性では対応が全く変わってくると私は思うのです。それから、濃厚接触者に対してＰＣＲ検査を行わなかったというのは、新型コロナウイルス感染症の感染者の把握や家族感染などということを考えると、問題とは捉えないのか、このことについて伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"その方法を親御さんが自分のお子さんに対して実施していただければ検査の実施は可能ですので、そういった方法も踏まえて、必要な対象には、今後は確実に検査をしていきたいと考えております。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"やはり私は、今も課長が言われたように、これから第６波も懸念されているところですけれども、ぜひ検査は、濃厚接触者だけでなく、さらに拡大して行うようにしていただきたいと思いますし、濃厚接触者ということであれば確実に行うということで、ぜひ求めておきたいと思います。さらに、高齢者施設のように定期的なＰＣＲ検査を求めたいと思いますが、いかがでしょうか。","respondent":"鷹箸保健予防課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"保健所の対応も遅れますので、まずはＰＣＲ検査を確実に実施していただくことを品川区内では考えていきたいと、現時点では思っているところです。区では、集団接種会場の余り分のワクチンを使いまして、リストを作って、集団接種会場開設時から接種を行ってまいりました。今後の検討課題とさせていただければと考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高齢者施設についても、特別養護老人ホームなど、東京都の補助を使ってやっているところ、それから区がやっている部分というのはかなり件数としては少ないわけなのですけれども、そういうところも実際に何件検査をやって、どれぐらいの感染者が発見されたのか。そして、それがどのように高齢者の施設の中での感染を抑える役割を果たしているのか、その辺の検証というのはされているのか、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"高齢者施設については、高齢者部門の所管課が、検査の実施数等については把握しているものと考えておりますが、そこで１例でも陽性が出ましたら、その日のうちに保健所に連絡が入りまして、周りの濃厚接触者について対応しております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢者施設のところもしっかりと保健所のほうでも検証していただいて、これを参考にして、今度は子どもの感染というのがかなり問題になってくるわけですから、ここでもぜひＰＣＲ検査を行っていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、９３ページの生活保護適正化事業、９５ページ、児童センター運営費、９７ページ、予防接種費、１２３ページ、こころの健康づくり事業について、順不同で伺います。最初に、１２３ページの、こころの健康づくり事業を伺います。昨年の第４回定例会の生活者ネットワークの一般質問で、新型コロナウイルス感染症の影響もあって自死が増加していることに対しての対策を求めて質問をいたしました。","respondent":"鷹箸保健予防課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"例えばネットカフェにいらっしゃる方や、漫画喫茶で寝泊まりされている方々などに、地元の商店街等と連携して、どのように情報を届けることができるかということを、連携会議などを通しまして、方法などを入念に検討して。ご指摘のようなケースがあった場合は、コールセンターからエスカレーションが上がってまいりまして、区の職員が対応するという流れになっております。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"ありがとうございました。先ほど予防接種のほうで、商店街との連携などもありましたけれども、とにかくどこに連絡してもいいから、困ったことがあったら、この電話に連絡してほしいというのを、ピンポイントで知らせていただきたいと思います。何か見解がありましたら伺いたいと思います。次に行きます。昨年の決算特別委員会の質問でもお伺いしたのですけれども、２０１９年度はモデル事業ということでした。","respondent":"櫻木生活福祉課長","answer":"モデル実施から継続して支援を受けられている方につきましては、今まで未治療だった方が、特定保健の指導対象者として継続して受診が確認できている方や、あとは、複数の病院に通院していた方が薬局を１か所にまとめることで医療費の削減につながった方など。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"医療費については、使わなくて済むものであれば、やはり健康で過ごすのが一番ですので、そちらの事業を進めていただきたいと思います。それから、そうではあるけれども、やはりどうしても医療が必要な方には適正に保護をしていただきたいと思います。やはり相談に来られる方が増えていると思いますので、その辺について、ぜひ改訂をお願いしたいのですけれども、見解を伺います。","respondent":"櫻木生活福祉課長","answer":"そのほかの部分につきましても、ご指摘等を踏まえまして、適宜見直しは図ってまいりたいと考えています。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、相談が増えていると思いますので、少しでも多くの方に、まず、権利なのだからどうぞ相談してくださいというほうを前に持ってきていただきたいと思います。お二人とも、がんです。それで、今後の生活のため、家賃の安い住まいに移ることも含めて支援制度を求めて、暮らし・しごと応援センターに相談に行きました。３月に相談に行っているのです。この対応について適切なのか、見解を伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"いずれにせよ、適切に案内するように、こちらは今後も職員にも指導してまいります。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"この方はたまたまいろいろなところで仲間もいて、フードパントリーのことを知り、子ども食堂を知り、私たちのほうにもご相談が来て、結局、別の所管で何か使える施策はないだろうかということで、使えるかどうかは別として、取りあえずこういう制度に申請してみたらどうですかというアドバイスをほかの所管で得ることができました。これは、どういう方針によるものであったのか、見解を伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"４月から６月までの対応なのですけれども、その当時、学校が休校に入っておりまして、児童センターに来てしまうと、各クラス、各学年も、各学校も混ざってしまうということがありましたので、学校休校期間に家庭で接触を避けるというような状況に、児童センターを開いてしまうと。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"それについて、６月２０日以降は再開していて、短い時間ですけれども、当事者のお子さんたちは大変喜んでいるというご意見は聞いていますけれども、なぜ中・高生だけが、今年の６月２０日ぐらいまでは一切駄目だったのか、見解を伺ったのですけれども、いかがでしょう。","respondent":"廣田子ども育成課長","answer":"中・高生につきましては、児童センターの中に関しては、ソーシャルディスタンスや飲食の禁止など、その中では感染予防対策を取れるのですが、中・高生はそのまま帰りに、コンビニなどに寄り道をするのではないかというところで、学校生活を大事にするということで。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問・要望","question":"接種の予約についてですけれども、これまで月曜日を中心に、予約受付開始となっておりましたけれども、我が会派が緊急要望した受付開催曜日の変更について、先日、ファイザー製ワクチン接種の受付開始が９月１９日日曜日に設定されたことは大変評価いたします。その点を伺いたいと思います。もう一つ、１２歳から１６歳の接種状況についても併せてお聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ちなみに、高齢者１回目、９０.４％、２回目は８８.６％まで来ております。１２歳から１６歳の接種率ですが、こちらは昨日の数字で、現在、１回目が３８.３％、２回目は２０.２％ということで推移しております。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"現状をありがとうあります。そうすると、予約が、枠をつくって、すぐに空白がないようにお知らせしてくださっているというところで、ご準備してくださっていることはよく分かりました。その辺の予約の埋まり方について、希望する区民の方の接種の進み具合、その辺はどんなふうに捉えていますでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"なので、引き続き、区としましては、会場はもちろん縮小はしてまいりますけれども、皆様が打てる会場を確保しながら、これからも会場を、少しずつ数は減りますが、設置して、打てる状態をつくっていくというところで、現在進めているところです。","id":"exchange-023"},{"speaker":"こんの委員","kind":"確認","question":"ご準備をしていただきながら、ためらっている方や、まだ未接種の方への対応が確認されました。もう一つは、未接種者への対応として、今、会場は縮小になるけれども用意しておくということですが、あえて、ためらっている人、あるいはしたくてもできない人への対応といったことは、どのように取り組まれていますでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１２歳から１６歳、保護者同伴の方の接種の促進ですが、確かに同伴を必要としておりますので、お仕事をされているとなかなか、平日のお昼の時間帯というのは難しいということも、こちらでは認識しております。","id":"exchange-024"},{"speaker":"こんの委員","kind":"質問・要望","question":"今ご答弁いただいた取組を、引き続きよろしくお願いいたします。次に参ります。１５７ページの生活保護費弁償金を伺いたいと思います。この弁償金というのは、多分、生活保護法の第６３条に基づく収入申告漏れの返還金のことと理解しているわけですが、区における第６３条の適用された返還、主な理由、件数を、まず昨年の状況を教えていただきたいと思います。","respondent":"櫻木生活福祉課長","answer":"生活保護法における第６３条、いわゆる不正受給ではない返還金に当たるものですが、大きな要因としましては、各種年金の遡及受給、または扶助費の算定誤り等という要因です。","id":"exchange-025"},{"speaker":"こんの委員","kind":"質問","question":"あわせて件数も伺ったのですが、次に聞くことと一緒に件数をお願いします。主な理由、要因として、各種年金の遡及受給というところがありました。これは特に、私も何人か、このご相談を実は受けてきたわけなのですが、特に高齢者の方です。どうしても、これは報告しなければいけない。こうしたことで、こういう返還金の発生が解消できるのではないかと思われますけれども、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"とはいえ、事後的に返還を求めるのは様々なトラブルになる場合もありますことから、区としましても、改めて収入申告の義務について受給者の方にご理解を頂くよう説明を徹底するとともに、トラブル等を踏まえまして、保護開始時に。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問・要望","question":"なぜか返還金という、いわゆる借金を抱えるようなもので、これはいかがなものなのかという、本末転倒ではないかと思われます。ぜひその期間をできるだけ短く、手当が出ている人、年齢的にも、これまで働いてきた中での申告を、受給されたときの話から見て、そうした受給者の負担を、あえてこういうところで起こさせない努力をしていただきたいと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問","question":"決算書のページで１１２ページ、都支出金の新型コロナウイルス感染症対応地方創生臨時交付金の中で、充当項目は数多くあるのですが、まず健康または保健の観点で１点、最初に伺って、その後、高齢者の関係、中小企業支援、商店街、あと地域スポーツと、この辺で伺えればと思っています。感染症に対応する疾患の併発や、過去の病に対する対応、そしてワクチン接種の対応等があります。","respondent":"鷹箸保健予防課長","answer":"そこに関しましては、罹患された方はもちろん、また罹患された方のご家族も含めて、非常に大きな影響が起きていることは十分認識しておりますので、その方々に対しても、保健所といたしましては、様々な情報提供などを通して。","id":"exchange-028"},{"speaker":"渡辺委員","kind":"質問","question":"保健所の見解でまさに間違いないと思っています。これを前提に各充当事業を伺えればと思いますので、今、必要性を伺いました。そうしたら、主な事業の内訳、充当事業でいう高齢者福祉施設支援事業のところ、そして中小企業支援の中の販路拡大支援事業、それともう一点、地域スポーツ施設開放、ここはそれぞれ金額もありますが、主なもので構いませんので、事業の内訳を教えてください。","respondent":"宮尾高齢者福祉課長、中元スポーツ推進課長、遠藤商業・ものづくり課長","answer":"高齢者福祉の部分ですが、こちらは、こちらの交付金を活用させていただいて、昨年度、５月の補正予算を組ませていただきまして。地域スポーツ施設開放のところですが、こちらは、顔認証付体温測定器、サーマルカメラというものを。私からは、区の販路拡大支援事業についてお答えいたします。","id":"exchange-029"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それぞれありがとうございました。高齢者のところで伺います。どうしても金額的なものに行きがちなのですが、そのほかの効果、あるいは施策の事例などを伺えればと思います。現場の要望はどのようなものだったのか、あるいは対応をどうしたのか、主な点で構わないので教えてください。ところが、これが、５分の４ですか、行政のかなり高い助成率で、ここはまさに公の公共サービスの役割の真骨頂だと思います。","respondent":"宮尾高齢者福祉課長、中元スポーツ推進課長、遠藤商業・ものづくり課長","answer":"それから最後に、やはり昨年は、国、東京都の制度が、１年間の中で本当に目まぐるしく、日々状況が変わる中で。おかげさまで、体育館におきましてもプールにおきましても、クラスター等は発生せずに終わっているところです。やはり一番多かったのが、換気や空気清浄機、それからアクリル板の設置などの関係で、６００件強という形になっております。","id":"exchange-030"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それぞれありがとうあります。この辺は、コロナだからもあるし、だからこそという、今こそやはり、コロナ禍だからこそ支えるべきという視点から、どのようになっているか教えてください。もう一点、スポーツのところは、本当にいい関係というのですか、行政と利用団体のコミュニケーション力がすごく上がったように捉えています。１０億円余ですか、３０％で、この款、この項目にもあります。","respondent":"宮尾高齢者福祉課長、遠藤商業・ものづくり課長","answer":"私からは、介護職員の住居支援に関するお尋ねについてお答えをします。やはり介護は、何といっても最終的には、人が頼りになるところです。しっかりと、これからも確保策、それから定着策を進めていきたいと思っています。共通商品券普及促進事業についてお答えいたします。","id":"exchange-031"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後、今の高齢者のところ。外国人の方への家賃助成など、スタートだと思います。一遍には無理かと思いますが、段階的に、今携わっている方々への拡充も含めて、これは要望にしたいのと、商品券のところ。これは分かっていて聞いた部分もありますが、本当にうまく回っている。こんな表現の一つで誇れる事業だと思いますので、ぜひそんなご活用も頂ければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"社会生活というものをきちっと回していく、維持していくということのためには、医療逼迫というのはやはり避けなくてはいけないという認識の下で質問させていただきたいのですけれども、まず区として陽性者が発生した場合に、まず入院すべきか、宿泊療養か、また自宅療養なのかといった判断というのは、どのようになっているのかということを、確認の意味でお聞きいたします。","respondent":"鷹箸保健予防課長","answer":"ただ、家族で、例えば小さいお子さんがいて、介護であったり、またはお子さんのお世話であったりということで、すぐには宿泊療養所に行けないという、様々なご事情がありますけれども、それらも含めて、基本は入院あるいは宿泊療養。","id":"exchange-033"},{"speaker":"塚本委員","kind":"意見","question":"ありがとうございました。ここにしっかりと、重症化予防のための治療をしっかり提供していくということで、そこがポイントになってくると思っていますけれども、１つ、抗体カクテル療法というのが、今、非常に取りざたされている。この抗体カクテル療法の対象者というのはどういうもので、どういった場面で処方されるのか。","respondent":"鷹箸保健予防課長","answer":"今私どもは少し余裕ができましたので、今後ホームページを分かりやすいものに変えていく予定にしている中では、先ほどの委員のご質問にはご答弁したのですが、少しでも症状がありましたら、区民の方には早めに検査を受けていただいて、陽性であれば。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"ありがとうございました。もっと言うと、いわゆるワクチン予約システムなどの記録システム、通称、ＶＲＳといわれている、こちらのほうでは、マイナンバーカードもデータとして持っていて、マイナンバーでの管理みたいなこともＶＲＳの中ではやっていると思うのですけれども、このマイナンバーカードを使用したワクチン予約システムというものは、検討できないのかというところで、お伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"これは、特に我々がマイナンバーを使うときは、全自治体から転入された方がどういう接種履歴を持っていたかということを、ご本人の同意の下に使っているということのみで、今現在マイナンバーを使っておりまして、区民の方に関しましては、宛名番号といいまして。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問","question":"そういった意味で、マイナンバーというものを活用したシステムというのは、こういった全国一律のワクチン接種等には非常に有効なインフラみたいなものだと思いますので、ぜひその辺の検討をお願いしたいのと、あと、こういったものを普及していくには、マイナンバーカードの普及というのがまず大事な視点かと思いますけれども、この普及ということについて、最後に、時間がないのですけれども。","respondent":"宮澤情報推進課長、渡部委員長","answer":"マイナンバーは、デジタル社会を実現していくために、基盤として大切なものです。区民の皆様が、１人でも多く入手できるように、普及を進めていくところです。保健整備担当部長はご退席いただいて結構です。第二委員会室の品川区保健所および健康課の関係理事者の方々も、ご退席ください。ありがとうございました。進めます。次に、藤原委員。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"７８ページ、区民住宅についてお伺いしますけれども、区民住宅は前回の予算特別委員会でも伺いましたが、区民住宅が全部、入居していたならば、今の現状を踏まえてどのぐらいの金額がマイナスになっているか、教えてください。最後に１３６ページは、都知事選挙費に絡んで選挙についてお伺いしますが、選挙に関しては公費助成がありますが、なぜ公費助成するのか、お伺いいたします。","respondent":"黒田財政課長、遠藤商業・ものづくり課長、竹田住宅課長、森木密整備推進課長、齋藤選挙管理委員会事務局長","answer":"交通安全対策特別交付金につきまして、こちらの交付金の中身ですが、交通反則金等の収入から、通告書等の経費等の差額について。創業支援施設につきまして、お答えします。こちらは業務の性格上、なかなか満室ということは難しい状態ですが、今現在、６２室空きがございまして、それを家賃に直しますと、月額８２０万円余。引き続き、不燃領域率７０％を目指して進めていきたいと考えております。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"都議会議員と区議会議員なのですけれども、同じ選挙区ですから、３４７か所の掲示板、同じなのです。次に木密なのですけれども、改めてここもお伺いするのですけれども、パンフレットには令和７年度までとなっています。そうすると、令和７年ということは、令和８年３月３１日まで適用となるのですけれども、例えばこの公費助成は、極論で言って、令和８年３月３１日に申請しても出てくるのですか。","respondent":"齋藤選挙管理委員会事務局長、遠藤商業・ものづくり課長、森木密整備推進課長、竹田住宅課長、川口交通安全担当課長","answer":"この理由ですが、旧自治省からは、参議院選挙であれば１７日間、選挙運動期間があって、ポスターを少し上質なもの。西大井創業支援センターは、これまで個別ブースが１０個と、オフィススペースが５室あるところでございまして。不燃化特区支援制度の令和７年度時点での扱いですけれども、令和２年度に一旦、不燃化１０年プロジェクトが終了した際には、ご案内といたしましては。本会議で同旨のご質問がありましたが、その際の答弁に沿って適宜適切に対応していきたいと考えております。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"駅前。木密なのですけれども、木密も、目標というのは、一軒一軒「どうですか」と、私はもっとやっていただきたいと考えています。なぜかというと、民間のハウスメーカーのほうが、区のパンフレットより、よほど入っています。それしかないわけですから、せっかくこんなすばらしい施策があるのだから、木密に指定されている地域の方にはどんどん利用していただきたいと思うのですが、いかがでしょうか。","respondent":"森木密整備推進課長","answer":"委員ご指摘のように、しっかりと広報することが大事だと考えております。本年度も、新たに特区に追加いたしました３地区について戸別訪問を予定しておりまして、来年度以降も分かりやすい説明を踏まえて、しっかりと周知していきたいと考えております。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"木密整備推進課長、前の職が住宅課長ではないですか。やはり、林を見て、森を見て、木を見ていかないといけないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問","question":"最初に、５２ページの特別区税、５２１億７,９７０万円からの質問をいたします。特別区税には、特別区民税、それから軽自動車税、特別区たばこ税の３種類があります。特別区たばこ税は、自販機や現金渡しのために未納はありませんけれども、特別区民税と軽自動車税、今、未納が生じています。その額は、区側も徴収を諦めた金額と思っていいのかどうか、お答えください。","respondent":"提坂税務課長","answer":"そのケースに沿った形で、執行停止、３年後に資力が回復しなければ不納欠損ということで落としているケースもあります。","id":"exchange-041"},{"speaker":"木村委員","kind":"意見","question":"区民との関係は、難しい関係もありますけれども、お金を徴収する対処法ですけれども、どのように処理されているのか。なかなか区民から、ないものを取り立てるというのも大変でしょうし、納めるというのも大変だと思いますが、その点、納めている人たちとの、ほかの区民とのバランスなどもあろうかと思いますけれども、その点をお答えください。","respondent":"提坂税務課長","answer":"直接区役所に来ていただいて、お話を伺った上で、一括納付が難しければ分割納付のご相談にも応じますし、あとご本人の生活状況をよく聞きまして、先ほど申し上げた執行停止などという手段も考えてあります。","id":"exchange-042"},{"speaker":"木村委員","kind":"意見","question":"いろいろと事情もあろうかと思いますけれども、臨機応変にお願いしたいと思います。次に、特別区たばこ税なのですけれども、約９６０万円弱、増えています。予想を超える売上げとなっておりますけれども、この原因は人口増が関係しているのでしょうけれども、それとも、少し考え過ぎかもしれませんが、コロナ禍で自宅待機者が増えたことなども大きく影響しているのかどうか、お聞かせください。","respondent":"提坂税務課長","answer":"コロナ禍が続いている中で、やはり喫煙所が減っているとか、あとテレワークの影響が、喫煙率を伸ばすものなのか、禁煙率を伸ばすものなのか、分析がなかなか難しいところではありますけれども、実は明日からまた税率が引上げになります。","id":"exchange-043"},{"speaker":"木村委員","kind":"質問・要望","question":"どうもありがとうございました。こちらの間違いでありました。次に、６０ページの中ほどにありますけれども、交通安全対策特別交付金ですが、当初予算ですと３,０００万円組まれておりましたが、調定額では３４８万円余が増えております。このプラスになったところ、３４８万円余はどのようなところで増えたのか、教えていただきたいと思います。","respondent":"提坂税務課長、黒田財政課長、川口交通安全担当課長","answer":"先ほど、特別区たばこ税の減収を約３０億円と申し上げてしまったのですが、約３億円の誤りでございました。失礼いたしました。交通安全対策特別交付金ですが、交通違反の取締りの状況から言いますと、違反ケースがやや増えているというところで、少し増えているような状況です。東京都内におきましても、これが７５万１,４５０件で、プラス２万８,７３３件という状況です。","id":"exchange-044"},{"speaker":"木村委員","kind":"質問","question":"次の質問に移ります。次は、７４ページの一番上にあります、高齢者等住宅使用料なのですけれども、収入未済額が約３６３万円余とありますけれども、個々の事情もあろうかと思いますが、大きな原因はどこにあるとお思いでしょうか。そして、高齢者ということですけれども、コロナ禍の時期のことも関係していると思いますが、ご本人からでは難しいと思いますが、ご親戚等からの徴収は難しいのでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"委員ご質問の、この未納の原因ということなのですけれども、分割納付により支払ってもらっているケースもありますが、やはり死亡による退去者の割合が多く、遺産相続人の特定が困難なケースなどが大きく影響していると考えているところです。","id":"exchange-045"},{"speaker":"木村委員","kind":"意見","question":"その下に今度ありますけれども、幼稚園保育料からですが、金額は１,０００円となっていますが、これについてご説明ください。そして、調定額が５２万６,２００円、収入済額が１万６,４００円、収入未済額は５０万９,８００円でありますけれども、ご説明をお願いいたします。","respondent":"立木保育課長","answer":"ただし、過年度分の収入未済額がある関係で、還付措置のための１,０００円です。それから、滞納の分ですけれども、５０万９,８００円。こちらは５６件ほど残っておりまして、そういった金額になってあります。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問","question":"私からは、８０ページ、総務手数料について、１３６ページ、都知事選挙費について伺います。都支出金の都知事選挙費について伺いたいのですけれども、今回の決算では２０２０年ですけれども、前回、２０１６年の都知事選挙の選挙費の都支出金の額、また、今回の支出金の内訳について、ご説明をお願いいたします。","respondent":"齋藤選挙管理委員会事務局長","answer":"委託金の内訳ですが、投票所の運営、開票所の運営経費、そしてポスター掲示場の整備費、コロナ関連経費というものがあります。それぞれ内訳で大きいものは、投票所の経費が３,８００万円、開票所が６００万円、ポスター掲示場が１,３００万円余となっております。","id":"exchange-047"},{"speaker":"松本委員","kind":"意見","question":"これまではずっと、都からのお金で全部賄えていたということなのですけれども、今回というか、昨年の都知事選挙については、ある意味、区との関係では赤字になっているという状況かと思います。今、内訳の中で、コロナ対策の部分が入っていましたけれども、コロナ対策の部分は幾らだったのか、もう一度お願いいたします。","respondent":"齋藤選挙管理委員会事務局長","answer":"コロナ対策経費ですが、各投票所に１名、派遣の職員を増員したり、スプレーその他、消毒液ということで、４５７万円余です。","id":"exchange-048"},{"speaker":"松本委員","kind":"意見","question":"実際のところ、先ほどご説明もあったように、実際にかかったお金と入ってきたお金の間には差があって、それが、歳入と歳出を両方見ると、１,０００万円ぐらいだということではないかと思います。ここの部分がなぜこういうことになったのかというところのご説明をお願いいたします。","respondent":"齋藤選挙管理委員会事務局長","answer":"今回、都が予定していた予算より、各２３区、多摩の市区町村から要求があった金額が超過してしまいました。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問・要望","question":"やはり、これも本来は都からの支出金ということなので、都できちんと、しっかりと調整というか算定していただいた上で、区の持ち出しがないようにしていただくことが大事かと思っているのですけれども、この辺り、今回の都議会議員選挙およびこれからの衆議院選挙に関して、都との調整で、きちんと支出金、当区にもきちんと１００％になるようにということで、どういったご要望をされたのか。","respondent":"齋藤選挙管理委員会事務局長","answer":"都議会議員選挙につきましては、今、実績の報告を出しておりまして、年度の末ぐらいに交付額が決まりますので、今のところ、１００％頂けるかどうか、見通しがありません。","id":"exchange-050"},{"speaker":"松本委員","kind":"質問・要望","question":"都知事選挙の都支出金については以上とします。それで、戸籍証明についてお伺いしたいのですけれども、１月から３月まで、１２月も少し含まれているようですけれども、短期間で１,００４通がコンビニ交付されています。今年度を含めて隔月の推移を伺えますでしょうか。これは新しく今年の１月から始まった制度ですので、この周知がどのようになされたのか、お願いいたします。","respondent":"木村戸籍住民課長","answer":"４月から８月末までですけれども、２,４８２件という形です。周知につきましては、ホームページでのご案内ですとか、マイナンバーカードを交付する際に、こういうことでお使いいただけますというようなご案内を進めているところです。","id":"exchange-051"},{"speaker":"松本委員","kind":"質問・要望","question":"１月から３月までの３か月と、今年度というところで、かなり数が増えているというふうに伺いました。ただ、他自治体においては、土曜日なども、そうはいっても職員の方を配置してというふうな対応もされているようなところもあると聞いておりますが、この辺り、今後変えていく見込みがあるのか、むしろ変えていただきたいなというところで、ご要望を含めてお願いいたします。","respondent":"木村戸籍住民課長","answer":"コンビニが開いている時間イコールという形で交付ができるような形は、今、研究を重ねておりまして、ぜひ実現に向けて進めていきたいとは考えておりますが、需要その他、動向を見据えながら、検討を続けてまいりたいと思います。","id":"exchange-052"},{"speaker":"松本委員","kind":"質問","question":"やはり人件費との関係などもいろいろあると伺っているので、何とかお願いできればと思いましたので、ほかにもまだお伺いしたいことがあったのですが、それぞれまた別のところで伺いたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"おくの委員","kind":"質問・要望","question":"私は、８９ページ、生活困窮者自立支援事業ほか２事業に関わって、フードパントリーについて伺います。一般質問の答弁で、フードパントリーについて周知方法を工夫すると答弁されました。そうであるなら、チラシを作成して、誰もが手の届く、目につく場所に置いて周知していただきたいと思いますが、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"フードパントリーの周知方法についてです。ホームページのほか、ＳＮＳ等、工夫してまいりたいと考えています。チラシについても検討してまいりたいと考えています。","id":"exchange-054"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひそうしていただきたいと思います。これは本当に、生活の厳しい区民から求められている支援です。大幅に増えていると。アップして、さらに活用して、ホームページでも目立つ形にして、宣伝するというか周知する方法を工夫していただきたいと思うのですけれども、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"周知方法につきましては、適宜適切に、状況に応じて方法を検討してまいりたいと考えています。","id":"exchange-055"},{"speaker":"おくの委員","kind":"質問","question":"ぜひとも、チラシを作るとおっしゃってくれたので、ホームページでも、ぜひともよろしくお願いしたいと思います。もう一点です。それで、これは一体どういう場合に、暮らし・しごと応援センターで受け取れるのか。実際に、暮らし・しごと応援センターで受け取れた実績があるのか、何件あるのか、この点をお伺いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターでのご相談において、食料の支援が自立につながると判断された方で、例えば体力的な課題を抱えられていらっしゃる方や、足がお悪いなどの状況で、浅草橋まで取りに行くのは難しいと判断される方につきましては、ご希望によって。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問・要望","question":"それ自体はいいことではあるのですけれども、私がここで求めておりますのは、遠距離の外出が難しい方だけの配慮ではなくて、生活に困って食料の支援を求めておられるような方全体への配慮をお願いしたいということなのです。それも悪いことではないですけれども。せっかくですから、品川区役所でも常に受け取れるような制度へと発展させていただきたいと思うのですけれども、その点はいかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"先ほども申し上げましたが、こちらの制度につきましては、ご相談を承りまして、その上で食料が自立につながると判断される方について、一定期間、食料の支援をするというものです。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"先ほどの、フードパントリーを利用している方が品川区でも実際の数字として表れてきているというデータ。これは、暮らし・しごと応援センターのデータですけども、ありました。実際に増えているという実態はあるとは思われないのですか。その点はいかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"ご相談を頂く中で、食料支援をご案内するケースは、今年度に入って若干増えているところは事実です。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問・要望","question":"やはり、その点まで認められるのなら、しかも客観的なデータに裏づけられているわけですから、やはり、それに対応する品川区の政策、ここまでもう来ているわけですから、私としては、もう一歩、前に踏み出していただきたいと思います。それが、最も雄弁なシティプロモーションにもなると思うのです。予算も非常に安上がりですし、ぜひとも踏み出していただきたいと強く求めて、終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは、１２０ページ、新型コロナウイルス感染症緊急包括支援事業補助金についてお聞きします。こちらは、充当事業のところが、児童センター運営費ほかとなっておりますが、このうち公立保育園に対する補助金はどれくらいの金額なのか、分かる範囲で教えていただきたいのが１点目。これは、令和２年度から準備し始めて、順次始めていたと記憶しています。２点お願いします。","respondent":"初貝保育教育運営担当課長","answer":"今ご質問いただきました件ですが、まず公立保育園での、都からの感染対策に対する補助金に関しましては、新型コロナウイルス感染症緊急包括支援事業補助金といたしまして、２,３５０万円が令和２年度の金額になっております。","id":"exchange-060"},{"speaker":"せお委員","kind":"質問・要望","question":"予算を理解いたしました。ありがたいです。そこで、令和２年度から行っている、コロナ禍においても保育職員の負担を軽減できるような支援などを、主なもので結構ですのでお聞かせください。それで、保育園、幼稚園から小学校へスムーズにつなげられる、感染症に対する教育といった観点では、どのように区ではお考えか、お聞かせください。","respondent":"初貝保育教育運営担当課長","answer":"今後、新型コロナウイルスの状況に変化が見られた場合には、ほかの対応策等も併せて検討してまいりたいと思います。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問・要望","question":"私からの要望としましては、園に対しての感染症対策費というのは、園児に対して行うものに加えて、現場の職員たちの負担が減るようなことにも使用していただきたいと考えています。そして、園児のご家族が感染症対策を行っていただくことが、子どもを守ることになると思いますが、感染症対策を理解されていない場合もあります。この３点の準備や検討はいかがでしょうか。見解をお聞かせください。","respondent":"初貝保育教育運営担当課長","answer":"感染症の対策に関する情報を保護者の方にきちんと認識していただくように、日頃から接している保育士からの周知というところは引き続き呼びかけながらも、例えば園の掲示板を使ったりといったところを今後検討していきたいと思います。","id":"exchange-062"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、１５４ページ、私道工事費収入について、条例のあり方について触れながら質問させていただきたいと思います。決算書では、予算現額３０万円に対して、収入済額はゼロとなっておりますが、これは対象となる私道整備助成の依頼がなかったということになるのでしょうか。","respondent":"長尾建築課長","answer":"令和２年度の実績の中では、全て道幅が２.５ｍ以上の私道を整備したため、歳入で見込んでいた予算３０万円は発生せず、申請者の負担なく整備している状況です。執行率の状況ですけれども、予算の執行率といたしましては、当初予算に対して約５０％程度となっております。","id":"exchange-063"},{"speaker":"湯澤委員","kind":"意見","question":"ここで少し、条例の定義について触れたいのですけれども、品川区では条例を誰のためにどういった目的で制定しているのか、また条例改正を行っていく理由と、規則、要綱は、誰がどのような目的でつくっているのかをお答えいただければと思います。","respondent":"古巻総務課長","answer":"条例制定の、区における、誰のためとか目的といった一般的なご質問ですので、総務課でお答えしますが、品川区におきましてというよりは、自治体において条例を制定する目的ですけれども、個々の条例に関しましては。","id":"exchange-064"},{"speaker":"湯澤委員","kind":"質問","question":"自治体の憲法とも言われております条例ですが、やはり自治体と、そこに住む住民のためのものでなければならないと考えています。同時に、条例は区民にとって、権利とともに義務や制限も与えるので、知らなかったでは済まされないことも多々あるかと思います。この件につきまして、助成の対象なのか、それはまた条例のどこから読み取れるのか、教えていただければと思います。","respondent":"長尾建築課長","answer":"私道整備事業の中で、下水道管の改修工事につきましては、対象の工事となっております。条例の中で私道整備工事として定義されている条項がありますが、その中で、排水設備という書き方をしていますが、排水設備の改修工事というところが記載されております。","id":"exchange-065"},{"speaker":"湯澤委員","kind":"質問","question":"対象となることが分かりましたけれども、やはり条件についてもケース・バイ・ケースということであるがゆえに、担当の方の解釈によって判断が違ってしまうということはあってはならないことだと思います。担当によって解釈や対応が違うということがないような取組があれば、教えていただければと思います。","respondent":"長尾建築課長","answer":"お話を伺った内容と現地確認の結果を踏まえて、複数の目でチェックしております。担当だけではなく私のほうでも併せてチェックしております。","id":"exchange-066"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ、利用者が、担当者のさじ加減によって決定が左右されると思われないような取組をお願いしたいと思います。工事着手まで２年程度との記載もあるのですけれども、これは大変長いと感じますので、もっと早められないかと。処理基準となる要綱を定めるなどして、部署でも共通認識を持てるようにするのはいかがかと思いますが、この３点をお願いいたします。","respondent":"長尾建築課長","answer":"工期の件につきましては、平成２５年頃ですけれども、申請件数が非常に多かった時期がございまして、そのときの最長期間となっております。現状は二、三か月ぐらいで、申請があってから工事は完了しておりますので、引き続き、できるだけ早く対応できるように努めてまいります。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問","question":"１５９ページ、生活支援型一時保育、オアシスルームについて伺いたいと思います。平成３０年８月から、２４時間対応のインターネット予約、それからコールセンター、これは月曜日から金曜日の９時から１８時で、受付については前日の午後３時までということでありますけれども、このインターネット予約、それからコールセンターでのそれぞれ予約の比率を教えてください。","respondent":"若生保育支援課長","answer":"令和２年度の実績で申し上げますと、オアシスルームのコールセンターで予約された方の割合が約１.８％程度になっておりまして、残りが全て、ウェブ、インターネットでの予約となってございまして、９８％以上がインターネット予約という状況になってあります。","id":"exchange-068"},{"speaker":"つる委員","kind":"質問・要望","question":"インターネットで予約ができるようになって、非常に予約がしやすく、そもそも施設に電話をしてつながらないということについては解消されていると思うのですけれども、ただ実際、今、コロナ禍にあって、今年だったか昨年か、予算特別委員会か何かでも、なかなか枠が半分なので、すぐ埋まってしまうという、そこはコロナ禍における部分や、そうではないときも含めて。","respondent":"若生保育支援課長","answer":"そういったお声は、私どもにも、まま届いている状況もあります。これは、オアシスルームにつきましては、システムを入れて３年ほど経つのですけれども、かなり課題が見えてきているところですので、今後、システムについては検討を進めてまいりたいと考えています。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問・要望","question":"過日の一般質問でご答弁いただいて、これは来年度の予算にしっかりと反映していただきたいということですので要望になりますけれども、東京都の予算を活用したベビーシッター利用支援事業の中の一時預かり利用支援は、実施に向けた検討をしていくというご答弁を頂きました。子どもを預けないとなかなか対応できないというようなときについて、区に区民から相談があったときには、どういうご案内になるのか。","respondent":"若生保育支援課長","answer":"空白地帯のオアシスルームについても検討を進めているところでありますので、今後とも進めてまいりたいと考えています。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"私からは、東京オリンピック・パラリンピック、これは２０２０年から２０２１年に変わって、ぜひ財政面からの総括をしていただきたいと考えています。関連する事業も加わると、これ以上ということになるのだろうと思いますが、これが一体どうなったのでしょうかということ。でも、それもできなかったということで、この事業１つの経過というかを総括していただきたいと思います。","respondent":"黒田財政課長","answer":"令和３年度につきましては、今年度に入りまして、事業中止や縮小というところで、ただいま精査しておりますので、一般財源負担額というところでは、まだ財政のほうでは詳細にはつかんでいないところです。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"結局は、決算額で言うと４億円ぐらいということなのですけれども、要するに、では使わなかったものについては、どうなってしまっているのですかという話なのです。その辺の全体の動き、そして予算の使い方というのはどうだったのかをお答えください。","respondent":"黒田財政課長","answer":"いわゆる減額補正につきましては、もともと予算として計上していたけれども、実行しなくなったので、予算自体を減らすということですから、流用するということではございませんで、その中で、実際に使った額の残りは不用額となっておりますので、不用額として。","id":"exchange-072"},{"speaker":"西本委員","kind":"質問","question":"それとの兼ね合いで、どういう考え方で品川区は、一般財源を使い、補助金を使い、全体的な効果がどのぐらいあったのでしょうかというところが、全体が見えないのです。その変わり方の考え方です。そうすると、その使わなかったお金は基金に入れるのか、それを積み増ししていくのかという、その辺の財源の使い方というのがよく見えないと思っているのですが、その考え方を教えてください。","respondent":"黒田財政課長","answer":"不用額の考え方ですが、当然、予算計上したときには予定していたけれども、その後の事情変更等で使えなくなった場合に、先ほど申し上げたとおり、予算自体を減額する場合もありますが、執行残という形で残る場合もありますので、その辺は。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"少し視点を変えて質問したいと思います。今回、質問を上げたオリンピック・パラリンピックについて、令和２年度でできなかったこと、２０２１年という形でやったわけですけれども、どういう考え方で、いろいろな事業展開、品川区のオリンピック・パラリンピックに向けての思いや、それをどういうふうに事業として展開して、結局はそれが達成されたのか、達成されなかったのかという総括をお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、延びたところで、今度はスポルの使用期間や、あと海外からの観客はもう来ないということになりまして、会場も変えて、まずは安全面を第一に考えながら、区として盛り上がっていける方法を取っていこうということで、会場も変更し。","id":"exchange-074"},{"speaker":"西村委員","kind":"質問","question":"１２０ページ、とうきょうママパパ応援事業補助金、時間が許せば１１７ページ、すまいるスクール運営費より伺ってまいります。産前産後サポート事業について現状を伺います。コロナ禍において、様々な行政サービスが縮小されました。産後６か月のお母さんからは、同世代の母親と話すことができず、いまだにママ友はいないという声も聞かれました。現在の利用状況をお聞かせください。","respondent":"山下子ども家庭支援センター長","answer":"今年度におきましては、ドゥーラの育成につきまして、資格取得費用の一部助成ということで新たに事業を開始しておりまして、需要と供給、両面から、事業を進めてまいりたいと考えています。","id":"exchange-075"},{"speaker":"西村委員","kind":"質問・要望","question":"おっしゃるとおり、私がご相談を受けた方も、多胎児のご家庭が１件ございました。総務費でも質問しますが、申込み方法の簡素化、ＬＩＮＥでできるようにするなどの検討をぜひともお願いしたいと考えています。保育、調理、清掃など、条件さえ合えば、ドゥーラであればどなたでもいいので助けに来てほしいというニーズもあると思うのですが、いかがでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"ただいま委員から、ＬＩＮＥを活用したというようなご指摘があったのですけれども、ＬＩＮＥにつきましては、一時期、情報管理の点で少し不具合といいますか、不都合が生じたところもありますけれども、一定、そういったところをクリアできてきているところもありますので。","id":"exchange-076"},{"speaker":"西村委員","kind":"質問","question":"以前お願いさせていただいたホームページの記載が少し分かりやすくなっておりまして、感謝申し上げます。次に、今後の方向性について伺ってまいります。ネウボラ電話相談の増加を伺っておりますが、コロナ禍において、子育て世帯の身近な相談相手が特に不足していると感じます。保護者に寄り添うアウトリーチ型の支援が日常的にある必要があると思うのですが、今後の方向性とお考えをお聞かせください。","respondent":"山下子ども家庭支援センター長","answer":"各関係機関の連携につきましては、私どもが要となりまして行っていく必要がありますので、今後とも、保育園、幼稚園、学校、保健センター、児童、民生・児童委員の皆様などと連携を構築しまして、対応に当たっていきたいと考えております。","id":"exchange-077"},{"speaker":"西村委員","kind":"質問・要望","question":"地域を巻き込んでいくということが難しいとは思うのですが、ぜひともお願いしたいと思っておりまして、例えば高齢者ですと安否確認の意味合いも大きいとは思うのですが、町会に高齢者見守りネットワークがあったり、宅配牛乳やヤクルトなどの民間企業と協定も結んでいらっしゃるかと思います。次に、すまいるスクール運営費から伺ってまいりたいと思います。","respondent":"廣田子ども育成課長","answer":"ですので、密にならないように、人数確認のために、ある程度、利用の予定を頂いているのですけれども、当日、登録しているすまいるスクールにお越しになれば、帰してしまうということはなく、お預かりはするような状況になっているところです。","id":"exchange-078"},{"speaker":"西村委員","kind":"意見","question":"緊急事態宣言も明けまして、また少しずつ日常が戻ってくるとは思うのですが、前後して申し訳ないのですけれども、夏休みのすまいるスクールの利用状況や、子どもたちの過ごし方がどうだったのか、所感も含めてお聞かせいただければと思います。","respondent":"廣田子ども育成課長","answer":"食事等に関しては、かなり気を使ったところですので、１年生と、２・３年生と分散してということで、なるべくソーシャルディスタンスを取れる部屋を別途取りまして、同じ方向を向いて黙食という形で、その辺りについては大変不便をかけたところですけれども。","id":"exchange-079"},{"speaker":"西村委員","kind":"確認","question":"有事でもありましたし、大変いろいろなイレギュラーなことが起きましたので、大変だったとは思うのですが、夏休みの間は一旦、申込み用紙を全部参加でひとまず提出しまして、毎日欠席連絡を入れていたというような保護者もいらっしゃいましたし、また、突然出社になって、欠席連絡を入れ忘れてしまったというような方もいらっしゃいまして、今後また感染が拡大したり長期休暇のときに。","respondent":"廣田子ども育成課長","answer":"出席に関しましては、あらかじめ、連絡は必要かというところを、１年生に関してはチェックしていただいて、来る予定であったけれども来ていない場合に連絡が欲しいというチェックがあった方については、保護者の方に、来ていませんというご連絡をするような形にしております。","id":"exchange-080"},{"speaker":"西村委員","kind":"意見","question":"私の子どもも２年生なので、すまっぴは本当にありがたいと思っているのですが、なかなかこの辺り、理解しないままいらっしゃった保護者の方もいたと、お声が届いておりましたので、また次の冬休みや、緊急事態宣言が出たときなどには、子どもが１人でおうちにいるようなことがないように連携を取っていただきながら、お願いできればと考えています。","respondent":"廣田子ども育成課長","answer":"保護者の方のご希望があれば、コロナの関係で、どの子がどの部屋に何時にいたというところで記録も取ってありますので、毎日は困るのですけれども、どんな感じですかとお問合せいただければお答えできるかと思います。","id":"exchange-081"},{"speaker":"大沢委員","kind":"質問","question":"決算を行っているので、決算について１つ。質問に入る前に、先ほど、ＣＯ２を測定する機械を、委員長の許可を頂きまして、ちょっと置かせていただいたのですけれども。しかしながら、先ほど、昼１時過ぎですか、置きました。それで、いろいろと委員会の、これはもう重要な会議ですから、どうのこうのということではないのですけれども、一応そんな数値が出ましたということだけお伝えしたいと思います。","respondent":"黒田財政課長","answer":"品川区予算事務規則の制定が昭和３９年でありまして、そこに予算編成の基本方針というものを掲げておりますので、この年代から基本方針を掲げて通達していると考えているものです。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"先ほど課長の昭和３９年というのは、まだこのような伝達手段が確立されていないので、往々にして行政側に立って、特に興味のある議員しか知ることができなかったわけですけれども、お互いに依命通達を共有しながら、いろいろと議論を重ねていくわけですけれども、ちなみに令和２年度の決算書が出てきていますけれども、このときに行われた依命通達があるわけでして。","respondent":"黒田財政課長","answer":"決算につきましては、その中で、その後、様々な事情変更等がある中で、当然、予算が足りなくて補正予算を編成させていただいたり、不用額として執行できなかったということもありますので、そういった中では、予算と決算の関係で言いますと。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"そうなりますと、決算はおおむね、完璧にはいかないまでも、一番の方向指針であります依命通達どおりに行われて示された数字ということで理解させていただいていいのでしょうか。","respondent":"黒田財政課長","answer":"決算については、当然その後、令和２年度ですと、新型コロナウイルスが年度中に感染拡大して、その対応のために補正予算を編成したということがありますから、依命通達を策定したときと状況が変わっている場合もありますので、その中で。","id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"アトランダムに行かせていただきますけれども、６０ページの交通安全対策なのですけれども、自転車の防犯について、交通安全の部分もありますけれども、駐輪場や、まちにある自転車がたまっているところは、防犯登録が貼られていない自転車が、結構、私がまちを歩いていると見られるのですけれども、私有物ですから、やたら公が手を突っ込むということはなかなか難しいところがあるとは思うのですけれども。","respondent":"川口交通安全担当課長","answer":"撤去後ですが、防犯登録または、フレームのところに打刻してある車体番号を基に、もし引取り手がない場合につきましては、警察等への照会を行いまして、また盗難の手配等があるかないかによって、確認しています。","id":"exchange-085"},{"speaker":"大沢委員","kind":"意見","question":"防犯登録のない自転車が、いとも当たり前のように、私有物のような形で駐輪場に置いてあるものが多いと思うのです。その辺の巡回をして、検査というか、巡回して、そこのところを認識し、事前の対策というのは何かやっていらっしゃいますか。","respondent":"川口交通安全担当課長","answer":"こちらは、自転車の購入時において、当然、防犯登録はしていただくということと、あとあわせて、当然、駐輪場等におきましては、それぞれの場所で、しっかりと自転車の鍵かけというものをやっていただくような中で、アドバイスをしています。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"今、購入時という言葉が出ましたけれども、その購入が、自転車店で購入するのであれば、間違いなく防犯登録の流れになっていきますけれども、昨今の購入形式でインターネット通販になってしまうと、面倒くさい人はそのままにしている。これから、どんどん自転車のインターネット通販は増えていくと思うのです。だから、そこのところをどういうふうに捉えていらっしゃるのか教えてください。","respondent":"川口交通安全担当課長","answer":"したがいまして、今まで区として防犯登録を積極的につけるというような広報啓発等はしておりませんので、今後、警察等と連携しながら、自転車の防犯登録の積極的な対応をできるように検討してまいりたいと考えております。","id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"まさに、明日から緊急事態宣言が解除されます。比較的、人とのつながりが、高齢者の方のみならず、我々も希薄になっております。は私の大好きな団塊の世代なのですけれども、団塊の世代は、シルバー大学でどれぐらいの割合を占めているのか教えてください。","respondent":"篠田文化観光課長","answer":"特に、ふれあいアカデミーに関しましては、３年間で卒業されていくですので、その辺は人の入れ替わりがあるものですから、ある程度、年齢層の高い方もいらっしゃいますけれども、比較的、６０代の方なども、かなり割合としては見られるところです。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問","question":"やはり、国からいろいろな部分で決められた名称ですから、変えることというのは、なかなか困難なところだと思うのですけれども、今後のやはり、いわゆる高齢の方たちの呼び名というのは、もう一回再考する、考え直す必要があると思うのですけれども、その辺り、時代の情勢、高齢者に対する認識、寿命の延び、その辺りのところはどういうふうに捉えていらっしゃいますか。","respondent":"篠田文化観光課長","answer":"ただ一方で、シルバーという言葉の認識というのは、慣れ親しんでいるところでもありますので、その辺は、社会情勢を見ながら、必要であれば、必要な変更等は考えていけばよろしいのかと捉えているところです。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問","question":"１１２ページ、新型コロナウイルス感染症対応地方創生臨時交付金について伺います。それぞれ、業種などの内訳も分かれば伺いたいと思います。あわせて、同じ支援策ということで、コロナで売上が５０％以上減少している中小企業や個人事業主等が受けられる月次支援金、また飲食店の時短等に係る協力金、それぞれ区内でどれだけの件数が受けられていると把握しているのか、伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"家賃支援給付金の件数等についてお答えいたします。昨年度、件数といたしましては３,２０３件で、補助額といたしまして、１億４,３３１万３,０００円です。","id":"exchange-090"},{"speaker":"安藤委員","kind":"質問","question":"家賃支援給付金のほうですけれども、当初の予算額が７億４,５００万円ぐらいだったので、執行が１億４,０００万円ということで、６億円ぐらい残っているということで、かなり使い残されたと。これは、なぜ余ったのか、使われなかった理由について、改めて簡単に伺いたいと思います。あわせて、使われなかった余剰金というのはどこに使われたのか、伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"件数につきましては、対象となるところで、１つは、支給対象となる、売上が５０％減、あるいは３か月で３０％減というところが対象とならなかったところで、そもそも国のほうの対象になっていないのかという部分、同じく、親族関係とか。","id":"exchange-091"},{"speaker":"安藤委員","kind":"質問","question":"だから、私はそこは真面目に検討し、そして今後に活かしていく必要があると思います。それで、使い残された金額というのは、本来、中小企業支援に使うべきものなので、それは中小企業支援に使うべきなのではないでしょうか。伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"残った分について、中小企業の振興に使うべきだですけれども、それぞれの事業につきましては、ほかの部分で十分に予算等を頂いたところでございまして、それぞれの部分につきまして、例えば足りなくなった部分についても流用等で対応して。","id":"exchange-092"},{"speaker":"安藤委員","kind":"質問・要望","question":"本来、６億円が、中小企業支援に使われるべきお金が、中小企業に渡らなかったということになるわけですから、私は、これは今からでも、苦境にあえぐ中小企業の支援のために使ってほしいと要望したいと思います。この目的にある「事業の継続を下支え」というのは、本来ならもっとできたはずなのです。それが、できなかったということなのです。","respondent":"遠藤商業・ものづくり課長","answer":"昨年から継続いたしまして、新型コロナウイルス感染症対応中小企業支援特別助成事業、あるいは基本となる融資などもしっかりやらせていただいているところです。今後につきましても、現況を見ながら、様々な支援をしていきたいと考えております。","id":"exchange-093"},{"speaker":"安藤委員","kind":"質問","question":"例えば月次支援金ですが、国の制度に、都も上乗せしています。この月次支援金というのは、今、実際に支給されています。区が昨年、家賃支援給付金で行ったように、上乗せ実施をやるべきなのではないかと思いますけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"現在のところは、上乗せ助成については考えておりません。","id":"exchange-094"},{"speaker":"たけうち委員","kind":"質問・要望","question":"歳入全般でお聞きします。それから、１６２ページ。それから、また国や都の補助金等が、コロナの影響で削減されるような可能性のあるものが、今のところ見えているのがあるのかどうか、あれば教えてください。それから、１６２ページは諸収入で、クリーンエネルギー自動車導入補助金と、その下の外部給電器導入促進事業助成金。これについて、事業内容と補助の実績を教えていただきたいと思います。","respondent":"黒田財政課長、東野経理課長","answer":"国や都の補助金の動向ですが、現時点のところ、今般あります地方創生交付金につきましては、令和２年度は大型の交付がありましたが、令和３年度につきましては、令和２年度の一部繰越しの部分と。その外部給電器が約１２０万円余の購入でございまして、それに伴う、国の外郭団体、こちらに記載があります一般社団法人次世代自動車振興センター。","id":"exchange-095"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、区の車について言えば、これから電気自動車とか水素とか、いろいろあるのですけれども、そうした電気自動車も、以前、北海道の胆振東部地震があったときに、電源確保という面で、電気自動車をどんどん導入すべきだということも要望させていただいて、今、各地域センターでは全て電気自動車になっているかと思うのですけれども、あと何台か、区の車も入れていただいていると思うのですけれども。","respondent":"黒田財政課長、東野経理課長","answer":"税外収入のところでいいますと、使用料については、利用率の向上とか、ネーミングライツ、ガバメントクラウドファンディング、ふるさと納税、その他、様々な工夫を図って。２０３０年までに買換えが必要というもので考えますと、約８台は買い換えないといけないのかと、今のところ計画していますが、これに伴いまして。","id":"exchange-096"},{"speaker":"たけうち委員","kind":"質問・要望","question":"歳入は、これから国でまた新たな政権ができてくるわけですけれども、また補助金もかなり、コロナ対策で大きな補正を組むというようなお話もあるみたいなので、ぜひそれを率先してスピーディーに使っていただきながら、コロナで苦しんでいる方に役立てていただきたい。それから電気自動車については、８台と言わず、まずは区長の車からぜひ進めていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"高橋（し）委員","kind":"意見","question":"１４４ページ、基金繰入金についてお尋ねします。特に、財政調整基金と減債基金について、今後の財政調整における運用に向けてお尋ねいたします。令和２年度の減債基金の繰入れは４億７,９００万円余であり、当初の予算額と同額です。そこで、この４億７,９０４万１,０００円の繰入金というのは、公債費の決算が今、１２億円余と言いましたが、いつのどのような区債に充当しているのかお尋ねします。","respondent":"黒田財政課長","answer":"令和２年度の予算で計上しております、いわゆる減債基金の繰入れですが、金額で４億７,９００万円余でございまして、こちらは、過去に国等が減税を行った際に減収になる分については、減税補てん債を起債して収入を得るというところで、過去に起債したものです。","id":"exchange-098"},{"speaker":"松澤委員","kind":"質問","question":"私からは、決算書１１１ページ、オリンピック・パラリンピック開催周知事業、これからいろいろと関連させて質問します。私たちに様々な思いを残しました東京オリンピック・パラリンピック。しな助の方たちが大会を振り返る機会、例えばオンラインの意見交換、アンケート、実績や成果、この先どんなボランティアをしていきたいか、そういうレガシーを振り返るような機会を設けたのか、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"最近、ある方に聞いたところですと、やはり実際のときにあまりできなかったので、それも含めて今後のことも、またいろいろみんなで考えたいというようなお話もしておりますので、年度内に振り返り等に努めまして、緊急事態宣言も解けたところですので。","id":"exchange-099"},{"speaker":"松澤委員","kind":"質問・要望","question":"振り返りの機会というのは、とても大切だと思いますので、ぜひやっていただいて、皆様がどう思ったか、それを引き続き、次に活かしていただきたいと思っています。そして、しな助というのは、先ほど課長も、前からご答弁もありましたけれども、オリンピック・パラリンピック終了後は一度解体されます。これをどのように展開しようとしているのか、ご見解をお聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"町会のほうをやる方もいらっしゃるかもしれませんので、適宜、そういう情報提供をしながら、伴走していくといいますか、そういった形でやっていきたいと思っています。","id":"exchange-100"},{"speaker":"松澤委員","kind":"意見","question":"適宜、いろいろありますけれども、ボランティアのつなげ方です。例えば、子どもの見守りをやろうとすると、これは教育委員会なのか、地域活動課なのか。エコフェスティバルに参加したいといっても、では環境課なのか、公園課なのか。こういった窓口が、要は分かりづらいといいますか。そういったことが、品川区の発展、また進化に寄与するものと考えますが、ご見解をお聞かせください。","respondent":"佐藤企画調整課長","answer":"ご質問の、専任の組織を設けるかどうかということと、また一方で、組織の横の連携を強めて、分かりやすい形でボランティアの方々に周知していく。そちらの両面を、様々、多様な観点から、今後も検討を進めていきたいと考えております。","id":"exchange-101"},{"speaker":"松澤委員","kind":"提案","question":"品川区の中でも初めて、町会、当事者、そして自治会、行政でまとまって動くという避難計画が始まっております。先ほど課長からもお話が出ましたけれども、私も少し違った角度でご提案したいのが、要は組織を整理して、団体ではなくて、個人の方も含めた、ＮＰＯボランティア係、ＮＰＯボランティア課といった、明確な窓口をつくるのはどうでしょうか。","respondent":"佐藤企画調整課長","answer":"最終的に、ボランティアを行う上での事業を行っている所管が最初から受けたほうがいいのか、最初、大きな形で受けたほうがいいのか、様々やり方があると思いますので、今後またそういった組織のあり方について検討を進めてまいります。","id":"exchange-102"},{"speaker":"松澤委員","kind":"意見","question":"ボランティアレガシーは大切なものだと思いますけれども、現状、職員の皆様に対するボランティアの研修、また体験学習の機会、ボランティア休暇、休暇制度といったものの普及なども効果的な方法の一つではないかと思いますが、ご所見をお聞かせください。","respondent":"崎村人事課長","answer":"一方で、職員向けの研修となりますと、なかなか意識啓発や促進を図るための研修というのは実施してはいないのですけれども、ただ、区では主任級を対象として、地域事業参加研修というものを実施しておりまして、こちらは、令和２年度・３年度は。","id":"exchange-103"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは非常に好評だったと伺っていますが、実施してみてどういう評価をされているのか教えていただきたいのと、６５ページの集会所使用料については、予算で見ると、かなりの額が流用されていて、当然コロナ禍ということで利用率も非常に下がっていて、質問しようと思っていたのですが、午前中の石田秀男委員の話でも、いろいろなところに補てんされてきているということで理解しました。","respondent":"溝口道路課長、川島地域活動課長、遠藤商業・ものづくり課長","answer":"土日の利用と平日の利用は、全体で見ますと、令和３年度でいいますと、僅かですけれども、やはり土日のほうが多くて、地域センターの場所によって。その関係もありまして、実際に営業ができないような状況があったので、使用料については免除という形にさせていただいた関係で、こちらに記載がないです。","id":"exchange-104"},{"speaker":"大倉委員","kind":"質問・要望","question":"その際には、当時、第四日野小学校に桜を植えた方たちも来て、子どもたちにお話をするなど、桜がすごく地域に根差しているエリアかと思うのですが、そうしたところが、以前のご答弁では、「今後も桜については、町会や地域の声を聞いて植えていきたいと思っています」というようなご答弁があったかと記憶しているのですが、そうしたことも踏まえて、どちらにせよ、こうした桜を植えていくという中では。","respondent":"溝口道路課長、川島地域活動課長","answer":"今後も同じような形で事業展開が図れるところがあれば、同じような形でやっていきたいと思いますが、まずは、既存に植えられている桜を守るのは、私たち道路管理者としての責務としてしっかり取り組んでいきたいところですので。荏原第一区民集会所につきましては、平日よりもかなり土日の利用が多いというようなところで、土曜日の保守点検日という形で設定していたところなのですけれども、多くの利用者の方から、何とかならないかというお声も頂いておりまして。","id":"exchange-105"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、歳入全般についてお聞きしたいと思います。要は、ほかに戻したという件数を、もし総合すれば、品川区内で１,０００件以上あるのではないですか。いつもきちんと、身近にある中小企業を守らなくてはいけない、区内産業を守らなくてはいけない品川区としては、そういうことをやはりしっかり把握して、我々にも報告すべきではないかと思うのですが、その辺についてご見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"廃業の部分は、なかなか届出がないというところがございまして、把握できないところです。ただ廃業につきましては、どちらかというと、コロナ禍というところで拡大はしていますが、そもそも後継者がいないとか、そういう部分の影響が大きいと聞いているところです。","id":"exchange-106"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望しますけれども、やはりきちんと私は調べるべきだと思うのです。でも、その前に、製造業でも、ほかの店舗でも、もしこの事業が２年前ぐらいに、まだ営業力があって、そして売上もあれば、私は継続していると思います。そこはもう恐らくご存じだと思うのですが、その辺をやはりしっかり考えていただきたいと私は思います。半年経ってもまだだ。実際、担当としてどうでしょうか、課長。教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"後継者の事業承継の部分につきましては、私どもも、例えば６５歳以上の方が事業主のところに、はがきなどを送って、事業承継をこの後やっていくかというようなアンケートなども取らせていただいているところです。","id":"exchange-107"},{"speaker":"須貝委員","kind":"質問","question":"東京都も動いています。そして実際、今、進もうとしていますが、品川区としては、中小・小規模産業に対してどのような対策を、もう１０月に入ります。もう、そういうものを考えて、すぐに実行するというものがあるのでしょうか。では、今度これだけ下がったら、どうして下がったのですか。そして、みんなとまた品川区の中を謳歌して、そして活動もしてくださいという文面は、１０月１日から変わるのですか。","respondent":"遠藤商業・ものづくり課長","answer":"中小企業の支援の部分についてお答えいたします。明日から緊急事態宣言が終わるというところで、日本銀行の話などですと、強制貯蓄などでは、いわゆる２０兆円ぐらいが、今まで支出しないで止まっているような状況だというのも伺っております。","id":"exchange-108"},{"speaker":"須貝委員","kind":"質問","question":"品川区として、やはり何も対策を立ててきていないのですか。それはおかしいのではないですか。身近にある区です。発表しています。それで、東京都では１２万軒のお店があって、約９万６,０００軒は認証店として認定して、どうぞという営業緩和をしています。品川区は何をしているのですか。そして何をするのですか。それは、１１月を待っているのですか。その辺について、もう一回ご見解をお聞かせください。","respondent":"古巻総務課長","answer":"やはり行動制限がある程度、推奨されておりますので、それにのっとって、施設等が若干、夜間開けたり、定員を、今まで３分の１だったものを２分の１にするといった緩和はしていきますけれども、段階的に緩和をしていくということで、１０月１日をもって。","id":"exchange-109"},{"speaker":"須貝委員","kind":"質問","question":"それで、今これだけ感染者が少なくなって、緩和される。では、きちんとその理由は説明するべきではないですか。やはり区民に、あれだけ厳しいことを言っていたのだから、では、こういうふうに場面が変わったら、どうしてこういうふうに変わったのだ。そうしないと、勝手に言って、勝手に知らない間に終わっているよというのは、私は筋が違うと思うのですが、もう一度お聞かせください。","respondent":"古巻総務課長","answer":"勝手に言っているわけではなくて、東京都のそういった対策に対してのご案内もさせていただきながら、まだまだ、感染が減ってきたとはいえ、例えば昨年の３月とか４月という段階から比べると、すごい数の感染者・陽性者数がいるということでは。","id":"exchange-110"},{"speaker":"須貝委員","kind":"意見","question":"去年の２月・３月。だって、感染しても、ＰＣＲ検査はほとんどできなかったでしょう。数だって全然。それと比較しては駄目でしょう。それで、都はこうです。だけど、やはりそれはきちんと説明するべきだと私は思います。やはり、売上が１０分の１では駄目だし、それぞれの売上、お客さんが来て、そしてそこで収益が上がらない限り、企業というのはもたないと私は思いますけれども、どう思いますか。","respondent":"遠藤商業・ものづくり課長","answer":"今回、明日からはそういう形になりますけれども、いろいろ条件があって、逆に一気に解放して感染が拡大するようになって、元の木阿弥になってもしようがないかという部分もあろうかと思いますので、その辺については、東京都や国などという部分になるかと思います。","id":"exchange-111"},{"speaker":"中塚委員","kind":"質問・要望","question":"１４４ページ、公共施設整備基金繰入金に関わって、新庁舎建設費用を伺いたいと思います。品川区は、新庁舎建設はこの条例の公共施設には当たらないので、新庁舎建設には基金条例の改正が必要との考えでよいのでしょうか。つまり、これまで公共施設整備基金の残高３３５億円余には、新庁舎建設費用の整備資金としては、これまでに積み立ててはきていないということでよいのか、伺いたいと思います。","respondent":"黒田財政課長","answer":"そういった意味では、直接的に整備基金を積み立てていないのかですが、財源の調整の中で、公共施設を整備するところに、公共施設整備基金を活用することによって、一般財源の調整を図るということができますので、そういった意味の財源の工夫の中で。","id":"exchange-112"},{"speaker":"中塚委員","kind":"質問","question":"後半の財源の工夫というのがよく分からなかったのですけれども、改めて、この約３００億円もの公共施設整備基金は、新庁舎建設費用の整備資金としては積み立てていないということでよいのか伺いたいと思います。","respondent":"黒田財政課長","answer":"庁舎の財源として積み立てていないのかですが、これまで公共施設の整備のために積み立ててきたです。","id":"exchange-113"},{"speaker":"中塚委員","kind":"質問","question":"公共施設のために積み立ててきたとはいえ、現状の公共施設には庁舎は当たらないとの説明ですので、よく分からないというのが率直なところです。新庁舎は約４００億円と大規模です。これは問題ではないのか、お伺いしたいと思います。対応できるというのであれば、今まで想定していた公共施設の整備に弊害または影響が起きてくると思うのですが、いかがでしょうか。","respondent":"黒田財政課長","answer":"起債の当たらない部分については、当然、その年度の必要な整備費については財源が必要となりますので、そこのところについては、その年度の一般財源を充てるのか、例えば先ほど申し上げたとおり、様々な。","id":"exchange-114"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかし、この基金を活用して新庁舎の建設費用に充てていく。そうなると、今まで用意していた、予定していた公共施設の整備に、弊害や影響が起きるのではないかと伺いました。改めてお伺いしたいと思います。今までためていた目的と異なるものに使うということは問題ではないかと伺いました。改めてご説明いただきたいと思います。","respondent":"黒田財政課長","answer":"庁舎の整備は、庁舎の老朽化やバリアフリーの課題等々ありまして、建て替えが必要というところで議論しているところでございまして、財源をどのように調達するかというところも１つの課題として考えておりますので、そういった中で。","id":"exchange-115"},{"speaker":"中塚委員","kind":"質問","question":"これまで想定していなかったものに充てるわけだから、これまで想定したものに影響が出るのではないかと伺ったら、影響は出ないとおっしゃいました。ならば、想定している以上に積み増してきたということになると思いますが、その点を伺いたいと思います。","respondent":"黒田財政課長","answer":"いわゆる公共施設整備基金につきましては、公共施設の整備のために積み立ててきたところでございまして、一般的に言うと、例えば財務諸表でいえば、減価償却のところが、財産価値が減っていくところでありまして、そういった部分を、年度を積んでいって。","id":"exchange-116"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、弊害が起きないということは、つまりは今まで想定している以上に積み増してきたということでよいのか、伺います。","respondent":"黒田財政課長","answer":"基金は年度間の財政の調整のために積み立ててきたところでありますので、施設の整備についても、一定程度、施設整備ができるように積み立ててきたです。","id":"exchange-117"},{"speaker":"中塚委員","kind":"質問","question":"しかもコロナ禍の下で、住民や事業所への支援の強化が急がれているときに、こうした庁舎の建設費用を捻出するために、これまでため込んできたものを、しかも目的まで条例で変えようとして、さらにコロナ禍で約４００億円もの庁舎建設を進めるというのは、何重にも間違っていると思います。こうした基金の創設や変更は行うべきではないと思いますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"新庁舎の整備は必要というところで検討を進めてきているところですので、その事業費をどのように調達するかというところは、今後またさらに検討していきたいと考えております。","id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"質問","question":"５４ページ、特別区たばこ税、７１ページ、八潮北公園スケートボード場、１０１ページ、帰宅困難者対策経費についてお伺いいたします。明日から緊急事態宣言が解除され、そして、たばこの価格も上がるということで、愛煙家にとっては、すごく厳しい増税で、すごく大変なことだと思うのですけれども、まず１点お伺いしたいところが、今、庁舎内にある喫煙所、まだ閉鎖されています。","respondent":"東野経理課長、森田生活安全担当課長","answer":"コロナ禍で、皆さん、いろいろなお考えはあると思うのですけれども、新型コロナウイルス感染症の終息に向けて、きちんと開設する時期を検討していきたいと考えています。すぐにというわけではございません。なので、今、閉鎖している場所は２点ありますが、ここにつきましては露天型の灰皿となっておりましたため、通行される方からも非常に苦情のあったところでありますので、まずはこの２か所について。","id":"exchange-119"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そんな中、スケートボードをやられている愛好者の人たちからすると、区で造っていただいた競技場はすばらしいのだけど、やはり利用者の方、プロを目指している方だと、いろいろここが物足りない、手直しをしてくれなどという声も多分あると思うのですけれども、そこのところはどういうふうに、今お考えというか、これから新たに取り組んでいくのかというところを教えていただきたいと思います。","respondent":"中元スポーツ推進課長、高梨公園課長","answer":"７月が、昨年度の３５５回が今年は３０１回、８月は６１０回、昨年度はあったのですが、今年の８月は３９２回、９月も、昨年度の４２８回が、今年３６２回ということで、もしかしたら皆さん。このたび、そういった声を受けまして、またスケートボード協会等の方のご意見も聞きながら、少し難易度を落とすような改修工事を今年度中に行う予定ということで考えているところです。","id":"exchange-120"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうしてもやはりスケートボードは地元の路面で楽しむという中で、いろいろ、しながわ中央公園でも、「スケートボード禁止」というコーンが置いてあったりするのですけれども、やはり、何というのか、区有施設の中で、ごく僅かでもいいのですけれども、スケートボード用に、開放できるようなところが何かあればもっと広めていただきたいのですけれども、そこを教えていただきたいと思います。","respondent":"高梨公園課長","answer":"１５０平米ほどと、手狭ではありますけれども、現在、マナーを守って、そのエリアの中でうまく使っていただいているという状況です。","id":"exchange-121"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。ありがとうございました。続きまして、１０１ページ、帰宅困難者対策経費に関連しまして、防災タブレットの活用についてお聞きしたいと思います。駅周辺帰宅困難者対策協議会があります。防災タブレットは、町会長、自治会長に配布されて、活用されている中、まず最初に、防災タブレットの配布目的と、災害時に期待される役割を教えていただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"具体的には、区からの情報伝達はもとより、平常時において、防災区民組織の役員の間、あるいは防災区民組織本部長同士での情報共有など、さらにはウェブ会議の実施などを考えてあります。","id":"exchange-122"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうございました。私のところには、複数の町会長から、この防災タブレットの活用、操作が難しい、使いこなすのが難しいというお声が寄せられています。確かにご高齢の町会長には活用がすごく難しいのかと私も思っているところです。例えば追加で、町会役員に配布するといった考えがあるのかどうか、お聞かせいただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"防災タブレットの使い方等のお尋ねです。令和２年度に、各会長に防災タブレットをお渡しさせていただいた際に、実際のタブレットを使いながら、簡単な説明は併せて行わせていただいたところです。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"１４８ページの過料、歩行喫煙の防止です。財政というか会計的なところを１つお聞きしたいと思います。スマートフォンがない。この辺の、これはどういう状況だったのかというのをお聞きしたいと思います。具体的に、では五反田地区と大崎地区に絞って、どういうポイントで指導したり、それから過料を取られたのですか。この辺が少し具体的に分かれば教えていただきたいと思います。","respondent":"佐藤企画調整課長、森田生活安全担当課長","answer":"委員ご指摘のとおり、組織化したほうがいいのか、もしくは柔軟性を持ったほうがいいのか、ボランティアの方々の個人であったり団体であったり年代、あとどういったボランティアをやりたいかというご希望もありますので。現在、指定喫煙所、９つのうち２つを今、閉鎖しております。五反田地区につきましては、７月２１日から加熱式の喫煙所を設置しましたが、その前につきましては閉鎖状態でありました。これは五反田地区にあります。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"ソフトな部分で、どんどんイベント等の行事に、ある意味で気軽に、行くほうは行ける、そういうボランティアの募集のあり方というのをぜひ進めていただきたいと思います。それで大崎地区は、令和元年度は２７８件から、令和２年度は１,８９６件に増えたということで、確認を１つと、逆に過料のほうは、前年度から少なかったり多かったりしているのですけれども、この辺のお話もお聞かせください。","respondent":"森田生活安全担当課長","answer":"それで、悪質な方々につきましては、その周辺にもいらっしゃいますので、それについては厳しく取締りをしているところではあります。多くの広報……。","id":"exchange-125"},{"speaker":"芹澤委員","kind":"提案","question":"私からは、１４２ページ、ふるさと納税寄附金、１０１ページ、帰宅困難者対策経費について伺います。先にふるさと納税寄附金について伺います。それで、広く区民にというのは、もう私も１００％同意していますので、そのために、マーケティングの視点を返礼品に取り入れてはどうかというようなご提案なのですけれども、まずそこについてご見解をお聞かせください。","respondent":"提坂税務課長","answer":"今後、ほかの自治体の例もよく新聞などに出ていますので、その辺を参考にして研究を重ねてまいりたいと考えています。","id":"exchange-126"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ありがとうございました。今朝、冒頭も区長から、歳入の見通しが非常に厳しいと。例えば、フライトシミュレーターを求めるのが男の子だろうと。例えば小学校６年生の男の子が一番ヒットするのではないかというのを考えると、そうすると、女の子の小学生には、ヒットする商品は品川区の返礼品であるのだろうかというのを考えていって、今、シナモロールが人形としてある。","respondent":"提坂税務課長","answer":"これは対象年齢が、小学生というよりも学齢前の幼児の方が対象になるかと思います。それから、屋形船の方も、すごく経済的に打撃を受けているかと思いますので、屋形船でベイエリアを回っていただいて、その中で食事を楽しんでいただくとか、そういうプランも考えてあります。","id":"exchange-127"},{"speaker":"芹澤委員","kind":"提案","question":"それで、屋形船に関しても私も一般質問で提案しましたし、ぜひ区内産業の支援というのはしていただきたいと思っていますので、屋形船を取り入れるのはぜひ前向きにしていただきたいのですが、その奥にいるターゲットが誰なのかというのを、ふるさと納税に関しては絶対に考えないといけないと思っていて、小学生なら小学生、乳幼児を育てている親に対してだったら、その返礼品を考えていかないと。","respondent":"提坂税務課長","answer":"ターゲットにつきましては、繰り返しになる部分もあるのですけれども、特定の年齢層、性別、国籍などということにこだわらないで、いろいろな方に受け入れられる返礼品ということで、そうなりますと必然的に、いろいろな品目を用意する必要がありますので。","id":"exchange-128"},{"speaker":"芹澤委員","kind":"質問・要望","question":"広く多くの方々に区を知ってもらう、区を実感してもらう。最後、すごく短くなってしまいましたけれども、帰宅困難者対策。それで、防災協定というのは、今、特にコロナ禍の中で感染症対策というのも必要だと思うのですけれども、避難所というか、滞在施設を明け渡してくれる事業者や団体に対して、感染対策経費というのも補助したらどうなのかと思っているのですが、そこのご見解をお聞かせください。","respondent":"山本防災課長","answer":"一時滞在施設につきましては、帰宅困難者の不特定多数の方が集まる可能性がありますので、感染対策というものが必要だと考えています。区といたしましては、感染症の対策の用品の支給など、運営上必要な支援につきまして、今後も検討していきたいと考えています。","id":"exchange-129"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/685794?Template=document&Id=1500#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":121132,"voices":338}},{"id":"r03-20211004-4","meetingId":"r03-c-settlement","date":"2021年10月4日","dateIso":"2021-10-04","committee":"決算特別委員会","time":"午前１０時００分～午後 ４時５７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を144件抜き出しています。","topics":[{"id":"topic-01","title":"◯渡部委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","agenda":"◯渡部委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"私からは、成果報告書、１４ページ、地域振興事業と、決算書の１９１ページ、生活安全推進事業について質問いたします。生活安全推進事業からいきます。これは決算書に記載はありませんが、生活安全協議会経費に入っているということなので、こちらで質問します。こども１１０ばんの家についてです。このこども１１０ばんのシステムは、どういった管理体制になっているのか、ご説明をお願いいたします。","respondent":"森田生活安全担当課長","answer":"こども１１０ばんの家に協力いただいている方々につきましては、委員のお話のとおり、ＰＴＡの協力を得まして、毎年、継続の意思を確認させていただいた上で更新しています。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"ＰＴＡに協力いただいているこども１１０ばんの家の名簿を警察のほうで管理されているということで合っていますでしょうか。今後、このすばらしい取組みに対して、警察とＰＴＡは所管が違いますけれども、住宅街の取組みについて、何か協力を仰ぐようにするにはどうしたらいいかなどアドバイスがあるでしょうか。","respondent":"森田生活安全担当課長","answer":"ご負担をかけるところではありますが、そういった形でご理解をいただきながら進めていきたいと考えています。","id":"exchange-002"},{"speaker":"松澤委員","kind":"提案","question":"見守る。地域のこういったすてきな活動ですから、しっかりと理解していかないと、重大な事件に遭遇したとき、きちんとした対応がとれないと考えています。そういった意味で提案したいのが、まずは、このこども１１０ばんの家の訓練、またはまもるっちを鳴らす訓練において、要するに、警察署との連携が、これはすごい大切なことかと思っています。","respondent":"森田生活安全担当課長","answer":"警察との連携ですが、現在も、警察との連携を進めておりまして、今後、警察と一緒の訓練とかもできたらと考えています。それにつきましては、今後も警察と協力をしながら進めていきたいと考えています。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"実際に使う訓練をしている。私の認識不足でした。ぜひ今後も前向きに対応していただいて、品川区全体で子どもたちを見守る、そういった思いが伝わることを願って次の質問に行きます。次は、地域振興事業です。この５年間の取組みの中で、今年の３月、町会・自治会活動活性化促進調査の中間報告書が出されましたが、改めてこの調査の概要、そして中間報告の内容を簡単にご説明願います。","respondent":"川島地域活動課長","answer":"こちらの調査の目的と、それから中間報告書の概要です。先ほどの条例制定後５年を経過したということで、条例制定の効果、それから、その後の状況の変化等を正確に把握して今後の施策に生かしていくという目的で実施したものです。現状、最終報告書をまとめている最中です。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"私は、この中間報告書を見て気になったことがありまして、条例制定後に新設された、たくさんある助成金の項目に関する質問の中で、補助金や支援をしていても活用しなかったという団体が約６０％ありまして、これをなぜ申請しなかったのかという理由は、制度の対象に当てはまらないというのが７０％でした。","respondent":"川島地域活動課長","answer":"補助制度を知らなかったために申請できなかったということがないよう、毎年、年度当初の町会長会議におきまして、補助制度について丁寧な説明を行っております。引き続き丁寧に補助制度とのマッチングといいましょうか、そちらに努めていきたいと考えております。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問・要望","question":"確かに町会長を呼んで地域センターでお話しする。その補助金について何点か要望させていただきたいのですが、現在、コロナ禍で、多くの町会・自治会などが書面開催となっています。こういった会合等におけるオンライン化は全く進んでいないと思います。しかし、オンラインなら、どの環境でも、整備なら全ての町会を支援、根強く支援することができるかと思いますが、ご見解をお聞かせください。","respondent":"川島地域活動課長","answer":"年々、無線ＬＡＮルータなどの設備は高性能で低価格化が進んでいることもあります。今後、ご指摘も踏まえたような支援、どのようなものが必要かというのは検討させていただきたいと考えています。","id":"exchange-006"},{"speaker":"松澤委員","kind":"意見","question":"すみません、時間がなくなってしまって、あと１つ、町会会館の借地料を聞きたいのですけれども、町会会館はアパート管理をしているところもありますが、ほとんど利益がありません。町会会館がある町会、ない町会とありますけれども、ご意見だけお聞かせください。","respondent":"川島地域活動課長","answer":"現状、委員ご指摘のとおり、補助制度はございません。現在、８０町会が会館をお持ちで、そのうちの２２会館が借地料を払っているというふうに把握しているところですが、こちらをどのように支援していくかというのは、今後の検討課題とさせていただければと思います。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"１６６ページの総務費に関連して、品川区のＳＤＧｓの取組み、これは長期基本計画とか、様々なものに反映をするよう、公明党も様々提案しています。明記していく、目標設定する、これも大事なのですが、その上で一番大事なことは、具体的に取組む、実現していくということが大事かと思いますので、そういう意味で、今、品川区が取組んでいる具体的な事例を一、二教えてください。","respondent":"佐藤（憲）企画調整課長","answer":"ＳＤＧｓに関わる区の取組みについてです。職員向けといたしましては、研修の中でＳＤＧｓと長期基本計画の関係を説明しており、国連のＹｏｕＴｕｂｅ動画を使うなど、分かりやすい形で行っております。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"やはり世界全体で取組んでいる目標、誰一人取り残さないという視点と、誰一人取り残さず実践できるようにしていくということが大事なのかなと。その上で無理なく取組んでいくということも一方で大事かなというふうに思っております。それに関連して、１８１ページの職員被服貸与について伺っていきたいと思うのですが、前提として、いろいろグリーンウォッシュの視点とかがあると思います。","respondent":"崎村人事課長","answer":"今、委員がおっしゃったように、まだできていない部分、例えばスニーカーですとか防寒着などがありますので、そういったものについては、現在、破損時対応ということでやっており、在庫がある限りはそちらから貸与を進めていくことになりますけれども、なくなった際は。","id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"その辺の周知啓発というところでは、いろいろそういった取組みをしている方にご活躍いただいて、講演会等ということも、この間、何度か提案もさせていただいて、これは款が違うところで提案させていただいたのですが、全体の推進の一助というところで、やはり若い世代の方々は、日常の生活の中で身近に感じられる部分が大事なのかなというふうに思いますので、ぜひ、まずは職員のそういう身につけるもの。","respondent":"崎村人事課長","answer":"先ほど企画調整課長からお話がありましたように、区としてもＳＤＧｓの取組みを進めていくという観点で、全職員、そういった環境配慮ですとか、ＳＤＧｓの取組みを進めていくという上で、人事課でできることとして、委員からご紹介がありましたように、被服貸与の面で。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問","question":"私からは、２０７ページ、ふるさと納税事業、２１１ページ、選挙管理委員会費についてお聞きします。選挙管理委員会費ですが、その中で常時啓発費とあります。そこで、これらは令和２年度に全て行われましたでしょうか。そして、啓発活動をしてみて、何か反応など変化があれば教えてください。","respondent":"齋藤選挙管理委員会事務局長","answer":"意見交換会につきましては、コロナの影響がございまして実施できませんでした。ただ、これまでも粘り強く継続的に続けておりまして、特に出前模擬選挙につきましては、全国組織から優良活動賞ということで表彰をいただいたところです。","id":"exchange-011"},{"speaker":"せお委員","kind":"提案","question":"これは私たち議員が、区民の皆さんに興味関心を持っていただけるように活発に議論するべきだと思っています。私からさらに提案するとすれば、例えば、投票済証です。予算はあまりかけなくていいのですけれども、投票済証を、インスタ映えするようなものとかに変えてみてはいかがでしょうか。このように、今後、投票済証を工夫して、特に若年層の投票率を上げるような取組みに関して、見解をお聞かせください。","respondent":"齋藤選挙管理委員会事務局長","answer":"ご提案の投票済証を活用した商店街との連携などにつきましては、選挙管理委員会だけではなかなか判断しかねる部分もありますので、他の課とも連携しながら、少しでも投票率の向上につながるよう取組みを進めていきたいと考えています。","id":"exchange-012"},{"speaker":"せお委員","kind":"提案","question":"ほかにも、やはりＳＮＳに上げてもらうことを考えると、例えば投票所にインスタ映えするような写真を撮れるスポットをつくったりとか、そういったものもあると思いますが、少し予算がかかりますので、これは提案だけします。選挙に関して新たな取組みをやるのによい時期かと思いますので、ぜひ来年度の予算に組み込んでいただいて、まずは区長選ですか、そこに向けて準備していただきたいと要望します。","respondent":"提坂税務課長","answer":"こちらにつきましては、具体的にはふるさと納税をいただいた方に対する返礼品の購入代金、それから返礼品の配送委託料、あと収納に係る決済手数料、その辺が主なところです。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"私は、シナモロールが大好きで、もちろん私だけでなく、２年連続１位になっていますので、当然、皆さん大好きです。よく話題にも上がるのですけれども、これはなぜなのか理由をお聞かせいただきたいのが１点と、さらに大井競馬場のペア指定席券に関しては、コロナの影響で中止していると認識しておりますが、今後どのように取り扱う予定なのか、決まっていることがあれば教えてください。","respondent":"提坂税務課長","answer":"こちらはまた再度発注するということですが、これとは別に、オリンピック・パラリンピックをＰＲするシナモロールの３体セット、こちらがまだ残ってありますので、そちらもぜひ返礼品として指定していただければと考えていますので、単体のほうの発注は今後の研究課題とします。","id":"exchange-014"},{"speaker":"せお委員","kind":"提案","question":"理解いたしました。東京２３区は特別区民税が大きな減収となっていて、ふるさと納税制度の見直しを国に強く要望するのは大切なことなのですが、それはそれで、国の制度が変わるまではこれでやっていかなければならないので、現状をどのように前向きに捉えるかなのかと思います。そこで、細かいことなのですが、提案を２点します。こちらも見解をお伺いします。","respondent":"提坂税務課長","answer":"他区のふるさと納税返礼品につきましても、注目して、参考にして、取り入れたいものについては取り入れるように検討していくところですけれども、協力していただいている企業を特設ページに無償で載せるという提案ですけれども、そちらについても。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"品川区は２３区の中でもすごく恵まれているほうだと私は感じていますので、先ほどちょっとお伝えしましたが、現状は現状で、いかに前向きに捉えて進んでいくかというところをしっかりベースに持っていただいてやっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"１７９ページ、男女共同参画推進事業について、学校への出前講座と、パートナーシップ制度についてお伺いしたいと思います。今回の出前講座ですけれども、品川区の中学校では初めての取組みと伺っており、とても画期的なことだと考えています。どういう経過で今回の実施に至ったのか、その経過を伺いたいと思います。そして、講師はどのような話を中学生に伝えたのか伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"こちらは、今、委員よりご紹介ございました性の多様性だけではなく、デートＤＶにも絡めた講座を、９年生、７年生に実施しておりまして、委託ですので、生徒の反応等々は、学校と委託業者との間でのやり取りになっていたかと思いますが、私ども人権啓発課男女共同参画担当では。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"このデートＤＶをテーマとする出前講座の流れで、学校のほうから話があったということでした。様々な取組みが広がっていることをとてもうれしく思います。それだけに、当事者の悩みや不安を受け止め共感する。この性の多様性講座についてですけれども、今後の出前講座、より多くの中学校でも実施していただきたいと思いますが、今後の展開や、教育委員会との連携について、具体的にお伺いしたいと思います。","respondent":"島袋人権啓発課長","answer":"ただ、今までの経過から見ますと、大学だとか、都立高校等々に出前講座をさせていただきましたが、最近は、大学等におきまして、お聞きするところによりますと、警察のほうから講座の依頼があるので、そちらで対応させていただいたということがございまして。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"職員の理解と併せて、生徒への説明や理解を深める機会を学校でも大きく広げていただきたいと思いますが、第１７期品川区行動計画推進会議について伺いたいと思います。そして、その啓発や支援に関わって、パートナーシップ制度の導入について、品川区でも具体的に進めていただきたいと思いますが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"第１７期品川区行動計画推進会議が間もなく終了いたしまして、今報告書を作成しています。１２月に入りまして、答申という形で皆様方にはお返ししていく予定ですが、この中でも、様々な委員の方々が３つのグループに分かれて提案をしていただいているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"パートナーシップ制度は、品川区として、行政の制度として、例えば同性パートナーも含めて多様な関係性を認めるということですから、多様性のある社会をつくる大きな一歩になると思います。改めていよいよ品川区もパートナーシップ制度の導入に向けて検討を具体化していただきたいと思いますが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"時期がこのような時期に重なりますこと、また、その報告書が、こちらでいただくことによりまして、一層検討を進めてまいりたいと考えているところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、パートナーシップ制度についてきちんと討議をしていきたいと、一層検討していきたいということですので、つまりは、パートナーシップ制度について、導入に向けて検討していきたいというその方向でよいのかどうか、そこだけ確認させていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"今のところ、私どもは、まだ男女共同参画推進を執行するための行政の連絡会の中でも、この報告書の件は上げておりませんので、しかるべき順番を示しまして進めていきたいという流れになるかと思っているところです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"答申がこれからということなので、確かに答申が来ないと、区としては具体化できないという、その流れは理解いたしました。いずれにしても、様々な会派からパートナーシップ制度の実施については求められております。具体化に向けては、ぜひ当事者の方々の意見や不安に応えるものを区としてしっかりと捉えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"くにば委員","kind":"確認","question":"１７１ページ、ホームページ運用、ＳＮＳを活用した情報発信検討経費、同じく１７１ページ、広報紙発行経費、１８５ページ、町会・自治会加入促進支援、時間があれば、１７３ページ、デジタルサイネージ運用経費について、順不同にお伺いします。１７１ページ、ホームページ運用についてです。推奨ブラウザの件についても修正を確認いたしました。現在および今後の運用指針などをお聞かせください。","respondent":"大澤広報広聴課長","answer":"なかなか古いページまではチェックが行き届かずに、まだ残っている可能性がありますので、ご提案いただきました運用ルールなども含めまして、今後も検討してまいりたいと思います。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"続きまして、２点目、トップページにあります新着情報一覧についてです。この仕様は、利用者も不便ですし、区の広報力も低下してしまいます。新着情報についても、これらと同様に遡って全て閲覧できるように、例えば月ごとの新着情報のバックナンバーのページをつくり、リンクを張ってはいかがでしょうか。この点のリニューアルについてご見解をお聞かせください。","respondent":"大澤広報広聴課長","answer":"特に緊急事態宣言の解除等、状況の変化がありますと、お知らせが多発されますので、短い期間でトップページから消えてしまい、周知が行き届かない可能性があるというふうに思っております。システム上、過去の掲載が可能かどうか、確認し対応してまいりたいと考えております。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"最後に、今後の更新予定についてお伺いします。昨年１１月にトップページがリニューアルされ、パソコンでもスマートフォンでもとても見やすく、使い勝手がよいホームページになりました。今後の大きな更新予定や方針についてお聞かせください。","respondent":"大澤広報広聴課長","answer":"平成１１年度にホームページを開設後、平成１９年度と平成２６年度にリニューアルを行ってまいりました。令和２年度にトップページをリニューアルしましたが、今後は、全体的なリニューアルをどのように進めていくべきか検討を始める時期だというふうには認識しています。","id":"exchange-025"},{"speaker":"くにば委員","kind":"意見","question":"品川区のホームページについて、私が議員になったばかりの頃に、かなり手厳しいことを言いましたけれども、今では物すごく使い勝手がよくなり、２３区の中で５本の指に入るぐらいとても見やすいというふうに私も思っておりますので、今後についても大変期待をしております。続きまして、１７１ページ、ＳＮＳを活用した情報発信検討経費についてです。こちらは予算額では３００万円でした。","respondent":"大澤広報広聴課長","answer":"ＳＮＳを活用した情報発信を検討する中で、今後、ＬＩＮＥを活用したサービスを展開していく、力を入れていくということになりまして、ＬＩＮＥの活用について検討し、自治体専用プラットフォーム、オンライン行政サービスを目指すシステムを導入いたしました。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらはＬＩＮＥについてということで、一括りですけれども、ＳＮＳを活用した情報発信検討経費についての内訳は分かりました。品川区のインスタグラムは、平成２９年５月にアカウントを開設して、約４年半運用を続けておりました。新たに１０月１日から別のアカウントで運用を再開しましたけれども、本来のアカウントにアクセスできないのは、どのような状況、経緯なのでしょうか。","respondent":"大澤広報広聴課長","answer":"インスタグラムですが、令和３年７月にＦａｃｅｂｏｏｋ社の仕様変更がありまして、それに伴って原因不明のままアカウントが閉鎖されてしまいました。","id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"原因不明で自治体の公式アカウントにアクセスできないというのは、大変衝撃な事実で、そちらに関しては、今後も粘り強く原因の究明をして、何とか復活させていただきたいと思います。もともとのアカウントを復活させるということもあるのですけれども、現状それが難しければ、どのようにアカウントのフォロワーを伸ばしていく予定なのか、お考えをお聞かせください。","respondent":"大澤広報広聴課長","answer":"以前のアカウントで人気のあったコンテンツですとか、あと、新しいものを取り入れて、地道に努力していくしかないというふうに考えてあります。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問","question":"はい、分かりました。なので、例えばツイッターのプロフィールのところに、インスタグラムのＵＲＬはこちらであるとか、品川区のＳＮＳ一覧はこちらのような形で、ほかのＳＮＳのプロフィールページとか、トップページから流入をしかけていくということも１つ大事なことなのかなというふうに思いますので、その辺もご検討ください。これは何か特段理由があるのでしょうか。","respondent":"大澤広報広聴課長","answer":"リンクがないことに特段理由はございませんので、できるだけ周知に努めるようにしてまいりたいと思います。","id":"exchange-029"},{"speaker":"くにば委員","kind":"意見","question":"トップページ一番下のアイコンの部分では、きちんと品川区公式のＳＮＳとして、ほかのＳＮＳと同等に並べられておりますので、こちらのそれぞれのページについても、インスタのアカウントをぜひともご紹介をお願いしたいと思います。続きまして、１７１ページ、広報紙発行経費より、広報しながわについてです。","respondent":"大澤広報広聴課長","answer":"それと、現在、紙媒体ではなく、ホームページやアプリから広報紙をご覧になっている方が、月１万件を超えている状況です。全戸配布については検討したこともありますが、以上のような状況により、実施は見送ってきているところです。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問","question":"こちらはコストの問題とかももちろんあるので、例えば、年に１回だけ、区への関心を高めるために、当初予算で決まった主な事業とか新規事業をまとめた本年度の品川特集号を発行し、年に１回だけ全戸配布をしてはいかがでしょうか。お聞かせください。","respondent":"大澤広報広聴課長","answer":"いろいろ状況により全戸配布を行う場合もあると考えています。今、新聞購読数がかなり減少してきておりますので、ご提案の趣旨も踏まえまして、今後も広報紙の配布方法については検討していきたいと考えています。","id":"exchange-031"},{"speaker":"くにば委員","kind":"質問","question":"続きまして、１８５ページ、町会・自治会加入促進支援についてです。現在、区では、町会・自治会加入率向上のためにどのような取組みをしているでしょうか。この２年間で加入率が急減してしまった原因について、お分かりであれば、どのような分析をされているかお聞かせください。","respondent":"川島地域活動課長","answer":"品川区では、今ご紹介いただきました条例に基づきまして、様々な町会・自治会支援、助成等を手厚く行ってきているというふうに認識しております。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"様々ご努力をされていることを承知いたしました。これを２年前の調査結果と比較してみると、１位の「どこで何をやるのか分からない」は、３９.９％から４７.８％に大幅増。品川区でも、今現在はありませんけれども、このような町会・自治会の案内のリーフレットを作成し、加入申込書とともに転入手続きの際に窓口でお渡ししてはいかがでしょうか。ご見解をお聞かせください。","respondent":"川島地域活動課長","answer":"すみません、今、町会加入率が下がった理由というところを、私、説明しておりませんでしたが、こちらは、町会・自治会からいただいている助成金の実績報告では、毎年６割前後で推移しているということで、こちらの世論調査の結果につきましては、私どものほうでは。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問・要望","question":"併せまして、先ほどおっしゃっていた各町会ごとのガイドブックについても、平成２１年とか古いものですので、これも最新のものに更新していただき、できればその配布をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこから質問します。最初に、ホームページ等経費から伺います。くにば委員の後でちょっとやりにくいのですけれども、私からは、決算書のホームページ公開について伺います。せっかく区民に対する情報公開を進めたのですから、分かりやすく、２０２０年度決算からで結構ですので、見開きで公開すべきと考えますが、見解を伺います。もう少し分かりやすくしていただきたいと思うのですが、見解を伺います。","respondent":"中山会計管理者、黒田財政課長","answer":"決算のほうですが、確かに入り方として区政情報から２つぐらい置いて、やっと決算書にたどり着くというような状況ですが、今後もせっかく決算書を載せるようにいたしましたので。ホームページで予算から入ると決算のほうに行けないというのは、予算のほうが先に編成される関係で、先にページをつくっていて、その後、決算のページへのリンクがうまくいっていないということだと思いますので。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。決算書は、私も確認しますが、開いたときにというか、私が気づく前に区民の方から、これでは見づらいというお声をいただきましたので、直っているのだったら別に問題ないです。私もこれはちゃんと品川区の姿勢として出すべきではないかと思うのですが、所管が広報広聴課なのか、人権啓発課なのか分かりませんが、しかるべき担当からお答えいただきたいと思います。","respondent":"島袋人権啓発課長","answer":"ワクチンに関しましては、所管が変わりますので、所管のほうからそのようなことが啓発できるようにしていると考えております。人権啓発課のトップページへ入っていただきますと、様々なところにリンクするように張られておりますので、どうぞよろしくお願いいたします。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうふうに探して入っていく人には分かるようになっているのだと思うのですけれども、やっぱり区の姿勢をちゃんとトップページで示すべきではないかということです。そうなると、広報広聴課なのでしょうか。見解を伺います。","respondent":"大澤広報広聴課長","answer":"今後は、ワクチン未接種者への差別的扱いを防止することも加えて、どのような啓発の仕方が一番効果があるのか検討してまいります。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"今年３月の予算特別委員会で、決算書には注記をつけてほしいと要望いたしました。引当金についてです。減価償却費を計上していくということは前から伺っていたのですが、この３つの引当金が計上されたということが、新公会計制度となったことの特徴の１つで、一般の企業会計を見慣れている人にとっては、行政の財政状況を点検しやすくなった点ではないかと私は考えるのですが、その理解でよろしいでしょうか。","respondent":"中山会計管理者","answer":"令和２年度決算につきましても、今準備しておりますので、よりこの財務諸表が分かりやすく皆さんに興味関心を持って手にとっていただけるような形でつくってまいりたいと考えております。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の求める会計情報と、新公会計と、今、両方出されているということで、それが両方ホームページで見られるのですね。その違いによって公会計レポートも遅れるのだということを私は個別に問合せて分かったのですけれども、そのことももうちょっと区民に分かりやすく表示していただきたいのですが、いかがでしょうか。","respondent":"黒田財政課長","answer":"いわゆる統一的な基準につきましては、国に報告する関係で、全国統一の基準でつくっているということなのですが、ベースになる情報は、品川区新公会計制度基本方針、いわゆる東京都方式で行ったデータを組み替えて統一的な財務諸表をつくるというふうな手順になりますので。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときに手間も予算もかけておりますので、ぜひもう少し一般区民もこれが活用できるような情報の出し方をしていただきたいと思います。３月の予算特別委員会のときにも、昨年の事業について伺って、評価も伺いました。コロナ禍の下での開設ということで苦労もされているかと思うのですが、ぜひ今後も拡充する方向を希望しての質問ですが、現時点までの事業の方向性とか成果などを伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"しかし、これは人数に関係なく、やはりこういう場があることで、来ていただいて、気持ちを述べることができる、仲間がいるのだという安心感、そちらを持っていただくということが非常に重要と考えておりますので、今後も引き続き進めてまいりたいと考えているところです。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"予算特別委員会のときに、数でいうとまだ少ないので、数を成果と考えると、だんだん収束する方向にいってしまうのかなということを心配しての質問です。ちょっと時間がないのですけれども、次の人事管理費を伺います。男性職員の育休のことです。質疑があったのが今年ですので、まだあまり進んでいないかと思うのですが、現段階で何か議論とかがあったら教えてください。","respondent":"崎村人事課長","answer":"男性職員の育児休業の取得に向けた取組みで、委員がおっしゃったように、国の法律改正もございました。今年度につきましては、８月現在、取得率４３.５％ということなので、引き続き強化をしていきたいと考えています。","id":"exchange-041"},{"speaker":"木村委員","kind":"質問","question":"１７１ページの上から４行目、広報経費３億５,５５３万円余からですけれども、その２行下に広報発行３９回、広報スタンド等６２か所、１億３,３４９万円余とありますけれども、この広報紙というものは、毎月３回発行し、区内６２か所のスタンドは区内全体に配布をするための集積所ということで認識していますが、それでよろしいでしょうか。","respondent":"大澤広報広聴課長","answer":"そのスタンドが６２か所あります。スタンド以外に１７０を超える配布場所がございまして、例えば郵便局ですとか、コンビニエンスストア等にも広報紙を置いてありますので、そちらへ配布したり、スタンドの清掃を委託したりという金額になってあります。","id":"exchange-042"},{"speaker":"木村委員","kind":"質問","question":"私の考えで、そのようにちょっと低いのではないかなと思ったわけですが、申し訳ございません。人は欲しくなければ、開きもせずにそのままごみ箱に捨ててしまうというのが普通でありますけれども、人を引きつける広報紙とは、また、興味を持っていただける広報紙とは、その広報紙の中に何が必要とお考えでしょうか。","respondent":"大澤広報広聴課長","answer":"区のサービスを知っていただくということで、情報を盛り込むのはもちろんなのですが、見ていただける広報ということで、１面にイラストを入れたりですとか、コロナ禍のときには、皆さんに少し気分を変えていただこうということで、暮らし豊かにという特集を組んで。","id":"exchange-043"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひ皆さんで協力し合いながら、一人でも多くの区民の皆さんにそれを読んでいただく工夫をまたしていただきたいと思います。次に、その下にあります声の広報３５回、３３５万円余とありますけれども、声を使った事業ですから、ラジオを使っての事業だと思っていました。実際は、カセットテープやデイジー版とありますけれども、このデイジー版とは一体どのようなものなのか、教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"デイジー版は、ＣＤ１枚に５０時間以上を録音できるシステムでございまして、専用の再生機がなくても、パソコンで再生が可能です。図書館にもデイジー図書ということで導入していると認識していますので、同じシステムです。","id":"exchange-044"},{"speaker":"木村委員","kind":"質問・要望","question":"１８９ページの区民保養所経費、７,６６６万円余で、品川荘、それから光林荘についてお聞きいたします。区民の憩いの場、品川荘と光林荘は、日頃の疲れを癒す場所として、多くの区民を迎え入れてきましたけれども、コロナ禍で、光林荘は、９月３０日まで休館としていましたけれども、現在は通常営業されているということでしょうか。","respondent":"川島地域活動課長","answer":"静岡県の新型コロナウイルス感染症対策ガイドラインにのっとって、適切に感染対策をしながらやっていくということで、節度を守って保養していただき楽しんでいただく場の機会の提供ということで、区のほうも努めていきたいと考えています。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"本日は、１７９ページ、男女共同参画推進事業、１９３ページ、しながわ活力応援給付金、ちょっと時間が間に合わないかもしれませんけれども、２０７ページの戸籍事務費、住民基本台帳関係費について伺います。いろいろ調べたところ、男女共同参画センターの各種講座、１回当たり２時間のものがほとんどだと思いますが、これは、令和２年度、何回分のものなのでしょうか。お願いします。","respondent":"島袋人権啓発課長","answer":"性の多様性の講座ですが、委託のものと、私どもで分けて実施しているものとございまして、実際のところ、申し訳ございませんが、細かいところの資料が、今、手持ちにはないので、あとで調べて報告させていただきたいと思います。よろしくお願いします。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問","question":"回数もお伺いしたのですけれども、令和２年度で何回分の計上になっているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"計算すると、多分、令和２年度は、コロナもあって回数は相当少なくて、多分、先ほどの出前講座も含めて、これは啓発誌の「マイセルフ」に、大体年間のやっている講座の結果が書かれているのですけれども、多分９回分ぐらいなのです。この辺りについて、どういうふうな対応をされてきたのか伺います。","respondent":"島袋人権啓発課長","answer":"ですので、人数が少ないところは様々なところで冊子を出したり、あるいは出前講座のお知らせをお話しさせていただいたりしながら、様々な形で進めてまいりたいと考えているところです。","id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"これを見ていくと、人数が少ない回は、大体、午後２時から４時とか、お昼の時間です。直近でも９月２８日に講座が行われています。お伺いしたいのですけれども、これもやはりお昼の時間です。これは一応話が出るかなと思ったのですが出なかったのですけれども、オンラインも今年度から取り入れていると思うのですけれども、これの参加者はどの程度だったのかお伺いします。","respondent":"島袋人権啓発課長","answer":"明日ですが、やはり同じ時間帯、日中の２時から４時ですが、男性をターゲットにしたモラルハラスメントではないのですが、言葉の使い方の講座を実施いたします。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問・要望","question":"これは、特別定額給付金と違って、やっぱり品川区独自なので、どこまでちゃんと広報できるのかということが大事だと思うのですが、特別定額給付金のときも、封筒にちゃんと外国語の記載をするのかどうなのかというところが報道されて、私も、実は区民委員会でしっかりと要望すればよかったのですけれども、触れるだけ触れて終わってしまったのですが、このしながわ活力応援給付金の封筒に外国語の記載。","respondent":"川島地域活動課長","answer":"封筒には外国語で記載してございませんが、申請書の右肩のところに、ＱＲコードを設けてご案内に代えさせていただいたと。それから点字は、検討はいたしましたが、結果、音声コード、ユニボイスというものを封筒のところに入れましてご案内をするというふうになったところです。","id":"exchange-050"},{"speaker":"西村委員","kind":"質問・要望","question":"１７１ページ、ＳＮＳを活用した情報発信検討経費、２０７ページ、戸籍住民課の窓口対応について伺ってまいります。感謝申し上げます。今後、保育園の申請時など、各担当課が混み合ってくることが予想される場合には、全庁的に子連れで来庁した方へのアナウンスを要望します。区の情報を必要な人に届ける認知、周知の難しさを解決するために、情報発信について伺います。","respondent":"大澤広報広聴課長","answer":"ホームページのアクセス数ですが、平成３０年度が４８０万件、令和元年度が５８０万件と１００万件の増加ですが、これが令和２年度になりますと７８０万件ということで２００万件の増加になっておりますので。","id":"exchange-051"},{"speaker":"西村委員","kind":"質問","question":"このＳＮＳを活用した情報発信の中に、ＬＩＮＥの運用経費も含まれているということを、先ほど、くにば委員の質問で伺いました。このＬＩＮＥの活用に特化して、残りのお時間、伺ってまいりたいと考えています。今朝調べたところ、品川区の登録者数は９,４００人に増えておりました。","respondent":"大澤広報広聴課長","answer":"過日、区の情報はＬＩＮＥ社に保存せず、国内のサーバに保存されること、また、セキュリティ対策についても確認いたしましたので、今後はＬＩＮＥのサービスについて進めていくために、現在、各所管と調整をしています。","id":"exchange-052"},{"speaker":"西村委員","kind":"提案","question":"ＬＩＮＥの可能性は大変感じております。これに関しましては、予算特別委員会でも質問させていただきたいのですけれども、区民の方にとって分かりやすい広報を強化する運営パートナーとの連携、あとは周知の課題の改善のためにＬＩＮＥ活用、先ほどから区も考えているということですけれども、便利な機能の装備を提案させていただきたいと思います。簡単に申し上げます。","respondent":"大澤広報広聴課長","answer":"ほかには、現在のプラットフォームのままで活用可能な機能としまして、申請・届出、申込み、予約、通知、アンケートなどは既に機能として持ってありますので、これを今後どのように活用していくかということを検討していきたいと考えています。","id":"exchange-053"},{"speaker":"西村委員","kind":"提案","question":"それを実現するために、庁内での運用についてもご提案をさせていただきたいのですが、現状は広報広聴課が庁内の全ての情報を取りまとめて、ＳＮＳも職員の方々が１つ１つやってくださっていると思うのですが、各課からの申請方法は今どのようになっているのか、改めてお聞かせください。","respondent":"大澤広報広聴課長","answer":"ＳＮＳの発信につきましては、広報広聴課で各課からの申請を受けまして、内容を確認した上で発信をしているという形になってあります。","id":"exchange-054"},{"speaker":"西村委員","kind":"提案","question":"どのメディアに掲載してほしいかというのも各担当課の方がお決めになると伺っているのですけれども、区民の方に必要な情報を届けるために、これは提案なのですが、各担当課が持っている情報を全部出すために、部ごとでセグメント配信の権限を持っていただくことはできないのだろうかと考えています。どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、２０９ページ、個人番号カード経費、マイナンバーカードについてということと、２１３ページ、国勢調査、１７１ページ、広報経費、ウェブ会議用バーチャル背景について伺いたいと思います。個人番号カードですけれども、マイナンバーカードの取得促進のため、令和２年度、昨年の９月からマイナポイント事業が実施されています。","respondent":"木村戸籍住民課長","answer":"かなりインセンティブをつけたというところが交付増の要因になっているところであると思います。これからもいろいろな用途と連携してという形で、使えるカードにというような展開もいろいろ出てくると聞いておりますので、引き続き、交付の強化に努めてまいりたいと思います。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"確認","question":"４０.５％ということで、あっという間に物すごい人数が取得をされたと。２０１８年の内閣府の調査で、ちょっと古いですけれども、取得していない方に、「取得していない理由は何ですか」と聞くと、取得する必要性が感じられないからという方が５７.６％だった。これを今度、例えば出張であったりとか、写真を撮ったりとか、こういうようなことを工夫する必要があると思うのですけれども、いかがでしょうか。","respondent":"木村戸籍住民課長","answer":"実際に出張のサポートサービスというのは、今までもちろん行ってきたわけで、このコロナ禍で一旦休止しておりますけれども、また再開するに当たりましては、出張というか、イベント先で、今おっしゃられたような写真を撮影して申請ができるというような形も。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"実は私も町会の役員として就任の要請をいただいたのですが、議員という立場だと、訪問とかというところにやはりちょっと引っかかる、法的な欠格事由ではないのですけれども、ちょっと誤解を招く可能性があるということで辞退をしたのですが、先輩方からもこの件についてはいろいろお話を伺いました。調査書類の配布方法とか、面談方法、こういった調査方法にどういう変化があったのか、簡潔に教えてください。","respondent":"川島地域活動課長","answer":"国勢調査の調査方法ですが、今までは対面が原則というような形で国が指示していたところですが、今回は非接触の調査方法により実施することになりまして、対面ではなく、インターホン越しでの説明を基本とした。それから、配布物も手渡しではなく郵便受けに入れるようにした。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"コロナということで非接触、方法を大分緩和して今回は行ったということですが、今までもコロナに関係なく、訪問したときに、やはり見知らぬ方、町会の中と言っても見知らぬ方ですから、そこで様々なひどい言葉を投げつけられたり、なぜそのようなことを教えなければいけないのだとか、あなたは一体誰なのか、身分証明書を見せろとか、結構いろいろなお声があって、成り手がどんどん減ってきています。","respondent":"川島地域活動課長","answer":"平成２７年の調査と今回の調査の回収率の数字が出ておりまして、平成２７年が郵送とネット回収を合わせまして６７.５％。今回はまだ正式な国勢調査による人口が出ていないので、これも速報値ではありますが、６８.９３％で、１.４ポイントほど上昇する見込みです。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問","question":"オンラインでの回答が増えているということもあると思うのですけれども、これは区としてどこまでできるのか分からないですが、国の方針ですが、区としても、ぜひこういったことを、コロナの感染拡大関係なしに、こういった方法で今後進められないのかどうかというところを伺いたいと思います。","respondent":"川島地域活動課長","answer":"国勢調査が終わりまして、２月に東京都のほうに、こちらのほうから、調査員や区の意見を都を通じて国に言うという場がございましたので、折に触れて、負担軽減をするようにというところをしっかり伝えていきたいというふうに考えてあります。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問","question":"１７１ページの広報経費で、ウェブ会議のバーチャル背景について伺います。昨年の令和２年５月、広報広聴課で、コロナ禍になって、ウェブ会議のバーチャル背景に設定できる区内の風景などの無料配信を始められました。その後すぐに第二弾として、６月からご当地キャラクターなどが追加されています。品川区がこのバーチャル背景を制作し、無料配信をしたその目的を、まず伺いたいと思います。","respondent":"大澤広報広聴課長","answer":"コロナ禍でウェブ会議が増えてきたことに加えまして、区内の風景ですとか公園など、これを機会に皆さんに知っていただきたいという思いもありまして配信を始めたものです。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問","question":"これは私みたいな立場の者には実は区のものが非常に使い勝手がいい。そういった中で、第三弾というように、定期的なバーチャル背景の追加みたいなことを個人的にも非常にお願いしたいと思いますし、ニーズがあるということは、私、個人的にも思っていますので、この辺はいかがでしょうか。","respondent":"大澤広報広聴課長","answer":"ご活用いただいて大変うれしく思っております。シナモロールをはじめとしたご当地キャラクターなども入れまして、今、３０種類以上を配信しておりますが、今後もしながわ百景など、区の魅力を伝えられるようなバーチャル背景をどんどん増やしていきたいと考えております。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"意見","question":"品川区民だけではなく、例えば目黒川沿いの桜がすごくきれいに咲いているようなところとかも使われると、正に品川区のシティプロモーションにもなってくるようなバーチャル背景だと思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"１７１ページ、世論調査に関わって、区の行う品川区世論調査について質問いたします。２年に一度行っているという品川区の世論調査ですけれども、次回の調査項目に、羽田新飛行ルートによる被害について、どのような被害があるかという項目と、羽田新飛行ルートをこのまま継続すべきか否かを尋ねる項目を追加していただきたいのですが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"そのほかの項目につきましては、各課に事前に調査を行い、テーマや質問項目、内容について希望を集約しております。所管から調査のご要望がない項目につきまして、広報広聴課の判断で設問に入れるという形には今はなってございません。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問","question":"今年の１月付けでつくられている最新版の第２４回品川区世論調査を見ますと、例えば生活環境について、騒音や振動についての評価を尋ねています。あるいは、交通事故の危険性についても尋ねています。これらについて尋ねる以上、昨年から実施され、これらの項目より深刻な影響を及ぼしている羽田新飛行ルートについて尋ねるのは、極めて必要なことではないかと思うのですけれども、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"お尋ねの羽田新飛行ルートというテーマですと、区の事業ではなく国の事業であるため、品川区世論調査の設問項目とするのが適当かどうかというのは難しいというふうに考えております。","id":"exchange-065"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう意味で、私は、やはり区の施策に準じるというか、そういう意味で世論調査にぜひ加えるべきことではないか、そういう意味で世論調査に加えていただきたいことですし、逆に、広報広聴課から所管にも伝えていただきたいことだと思います。その点、いかがでしょうか。そのくらい区民の強い関心の的となってきている。この点、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"ご参考までに、騒音や振動については、２年前の調査で騒音について悪いと思っているという回答が３６.９％、令和２年度で３６.１％と微減となっています。","id":"exchange-066"},{"speaker":"おくの委員","kind":"質問","question":"そういう事実や位置づけを踏まえれば、やはり広報広聴課として必要だと思うこの羽田新飛行ルートについての項目を、所管に伝え、質問項目に加えるべきだし、一般論としても、質問項目を新たに加えるということが一切できないということではないと思うのですけれども、やはり広報広聴課として必要だと考えるものは各所管課に相談することもあってしかるべきだと思うのですが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"羽田新飛行ルートにつきましては、区としては、世論調査以外に、区民の声や陳情等でもたくさんのご意見をいただいておりまして、それらにつきましては適切に対応していると認識しています。","id":"exchange-067"},{"speaker":"おくの委員","kind":"質問・要望","question":"この羽田新飛行ルートは、区民投票条例にも表されるように、大きな関心事です。ぜひ調査の機会をつくっていただきたいということを申し上げて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"高橋（伸）委員","kind":"意見","question":"１８３ページ、公金取扱事務費、１８７ページ、区政協力委員会経費、１９１ページ、荏原町安全安心ステーション運営経費、２１２ページ、統計調査費からそれぞれお尋ねしたいと思います。当初予算ですと、口座振替が２８万件の予算でした。それに対して１６万件余。会計管理のほうでは、この件数をどういう捉え方をしているのかお尋ねしたいと思います。","respondent":"中山会計管理者","answer":"この間のペイジー収納の状況を見ていますと、割と一進一退といいますか、伸びていくわけでも下がっていくわけでもなく、その年によって微増だったり微減だったりというような状況で、なかなかこの動向は把握しにくいというのが現状です。","id":"exchange-069"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、１８７ページ、区政協力委員会経費に関連してお尋ねしたいと思います。特に操作に関しては、熟読されていろいろとやっておられる方もいるとは思うのですけれども、例えば、町会長会議とか、町会長と関わりの深い地域センターにおいて、防災タブレットを今後どういうふうに活用していくのかということをお聞きしたいと思います。","respondent":"川島地域活動課長","answer":"今後も防災情報を適時発信したり、それから、定期的な訓練の実施や地域センターからの連絡等にもなるべく使っていくように、積極的に取組んでいきたいと考えています。","id":"exchange-070"},{"speaker":"高橋（伸）委員","kind":"質問","question":"区内の地域センターによって、タブレットを教えるとか、多分、それぞれのセンターの所管によって、やり方等が違うと思うのです。それはある程度一定のやり方の基準を定めて、全地域センターの所長とかに伝えて、もっと分かりやすく、全く操作のできない町会長もいると思うのです。もう少しそこをどういうふうに啓発していくのかということだけお聞きしたいと思います。","respondent":"川島地域活動課長","answer":"現状、各地域の主体的な取組みに任せていたところもありますが、さらに積極的にこちらの防災タブレットをできるだけ使って、ふだん使いしていくようにということを私のほうでも地域センターのほうに伝えていきたいと考えています。","id":"exchange-071"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ活用方法をよろしくお願いいたします。続きまして、１９１ページ、荏原町安全安心ステーション運営経費についてお伺いしたいと思います。こちらには、平日の日中、荏原町安全推進員の方が常駐して今までやってこられたと思うのですけれども、このコロナ禍を踏まえて、今の現状をお知らせいただきたいと思います。","respondent":"森田生活安全担当課長","answer":"コロナ禍におけます荏原町安全安心ステーションの活用の現状をお知らせいたします。緊急事態宣言もありまして、本年は４月の一部を除き完全休業とさせていただきました。しかしながら、緊急事態宣言が解除されまして、本日、１０月４日月曜日から再開しております。","id":"exchange-072"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認ですが、これは推進員の方の経費だと思うのですけれども、それで良いのかが１点と、あと、この約１年半ぐらい開設していなかったと思うのです。その間、二国沿いに交番があります。この緊急事態が発令したときは、電話でボタンを押せば警察官が来てくれるということだと思っているのですけれども、この１年半の間で駆けつけるといった事例があったのかどうかということをお聞きしたいと思います。","respondent":"森田生活安全担当課長","answer":"委員ご説明のとおり、緊急事態宣言に伴い閉鎖をしておりましたので、人件費につきましてはマイナスになっているところです。もう１つ、警察官の駆けつけがございましたかというご質問ですが、今のところ、そのような緊急な事態があったということはございません。","id":"exchange-073"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、２１２ページの統計調査費から国勢調査についてお伺いいたします。先ほど、あくつ委員からもお話がありましたけれども、重ならないように質問をさせていただきたいと思います。品川区の調査員も、多くは町会・自治会の方にお願いをしていると聞いておりますけれども、令和２年度の国勢調査での調査員の内訳と、調査員の負担軽減の対策は何をなされたのか教えていただきたいと思います。","respondent":"川島地域活動課長","answer":"先ほどもあったインターネット回答や、郵送回答の推奨ですとか、非接触の調査を基本とするというような形にもなりまして、調査員の皆様の負担はかなり軽減されたものと考えています。","id":"exchange-074"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"負担軽減の取組みはすごく分かりました。これから先、インターネット回答とかも今まで以上に加速すると思いますので、それも踏まえて今後もやっていただきたいと思います。調査員は、恐らく９割近くが町会・自治会の協力により得られているということであります。調査は完了しておりますけれども、今回の調査で調査員の事故、そしてけがはなかったのかどうか、お聞きしたいと思います。","respondent":"川島地域活動課長","answer":"幸いにも今回大きな事故、それからけが等はなく無事に調査を完了することができたです。","id":"exchange-075"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"事故がなく調査を終了したということで、本当に区としても、いろいろ対応され、どうもありがとうございました。今年の６月には国勢調査の速報値が出されました。区民委員会でも報告されたところですけれども、品川区の令和２年国勢調査の速報値では、人口が４２万２,７９５人、世帯数が２３万７,３９９世帯ということでございました。今のこの数字の分析がございましたら、教えていただきたいと思います。","respondent":"川島地域活動課長","answer":"品川区の過去の国勢調査の結果を見ますと、昭和３５年に４２万７,８５９人だったところが国勢調査の人口のピークということで、今回はそれに次ぐ人口の多さとなっております。","id":"exchange-076"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"世田谷区に次いで品川区が２番目に大きいということであります。住民基本台帳の人口は少し減少傾向だと思うのですけれども、自治体にとって非常に重要なものでありますから、品川区の皆様と私たち区議会とで連携して、いつまでも人口が増え続ける品川区をつくり上げていきたいと要望いたしまして、私の質問を終わらせていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"湯澤委員","kind":"質問・要望","question":"特にコロナ関連の情報は目まぐるしく更新しておりますので、会派からも緊急要望させていただきました区のＰＣＲ検査センターの設置、それからＥＮＪＯＹしながわ屋形船キャンペーンや販路拡大支援助成といった事業者への支援策、それと、しながわ活力応援給付金のような全区民に対するもの、そして、そのほかにも区有施設の利用状況や、オリ・パラのコロナの影響に関する情報については。","respondent":"大澤広報広聴課長","answer":"情報の発信についてですが、ホームページで申し上げると、コロナの情報については、当初作成したページに新たな事業や情報が次々と増えたことから、各所管でつぎ足しをしていって走りながらの対応ということでございましたので。","id":"exchange-078"},{"speaker":"湯澤委員","kind":"質問・要望","question":"これからも重要な情報が多々あると思いますので、今後もぜひ万全な体制で情報を発信していただきたいと思います。それで、１点、気になるところがあって、事前に課長にもお聞きしましたけれども、決算書を見ると、広報発行が３９回に対して声の広報が３５回と４回少ない。穴があいてしまったことに対してどういったフォローをしたのか、３点お伺いしたいと思います。","respondent":"大澤広報広聴課長","answer":"４月１７日の臨時号、４月２１日号、５月１日号、５月１１日号の４号となっています。対象の方には事前にご連絡しまして、ホームページから聞いていただくように周知をいたしました。今後このようなことがないように努めてまいりたいと思います。","id":"exchange-079"},{"speaker":"湯澤委員","kind":"質問・要望","question":"情報システム運営費についてお伺いします。予算書と決算書で２億円余の差が出ていますけれども、ネットワーク・セキュリティ経費だとか、メールセキュリティ強化がかなり予算執行されていないと、区のセキュリティは大丈夫なのかなというふうに感じてしまうところもあるのですけれども、どういった理由なのかと、安全性がどのように担保されているのかをお知らせいただければと思います。","respondent":"宮澤情報推進課長","answer":"不用額の主な理由は３点ございまして、まず１つ目が、住民情報システム運営費のところで毎年住民情報のシステム改修を行っているのですが、こちらに関しましては、予算編成の時点で、税法改正に対応してシステム改修をするのですが。","id":"exchange-080"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最後に、しながわＷｉ－Ｆｉスポット事業についてもお聞きしたいのですけれども、こちらは区として設置を予定していた箇所にはほぼ全て設置をするとお聞きしておりますが、やはりネット社会でありますので、Ｗｉ－Ｆｉの設置を求める声をよく聞きます。そういった区民からのニーズがあったときに、各所管と相談の上、設置の拡充を検討していただきたいと思いますが、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"これまで区内６６か所を整備してまいりまして、観光客の誘客であったり、防災時、災害時の通信手段の確保や、区民の利便性向上を目的としているところです。設置の拡充に関しましては、各所管の考え等もありますので、そこら辺をしっかり連携しながら考えていきます。","id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"ここ３年の不正請求取得の件数と推移、それから被害告知型の本人通知制度導入後の防止効果について、また、不正請求等がいまだゼロになっていないという、こうした現状もありますので、区民のプライバシーと人権を守るためには、さらなる不正請求取得防止の強化が必要であり、団体の方々から毎年継続して求められている登録型本人通知制度の導入も必要であると考えますが。","respondent":"木村戸籍住民課長","answer":"今後も引き続き、現在も職員の意識づけというところで継続してこのようなことを防止していくという姿勢で取組んでおりますので、引き続き、現状の体制で対応してまいりたいと思うのと、引き続き調査は続けてまいりたいというふうに思っております。","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、団体の方々、また、区民の方々が、こうしたことでプライバシーの侵害を受けないように、引き続きよろしくお願いしたいと思います。次に、まいります。整備状況をお聞きしたいのですけれども、整備をされている場所と、それから整備の箇所数、また、整備する際の設置基準などがありましたら、お知らせいただきたいのと、今後の整備の方向性についてなど、お聞かせください。","respondent":"宮澤情報推進課長","answer":"そこら辺で、利用の傾向であったり、ニーズを捉えながら考えていくのと、また、新たにつけようとする施設の所管部署の考え等もありますので、そういったところを考えながら検討していく考えです。","id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"その受信ができる１つの方法として、こうしたＷｉ－Ｆｉも考えられるところですが、具体的には、現在、防災の関係では、広域避難場所の公園等にもついていると理解しているわけですが、そこに限らず、例えば防災公園、あるいは町会の一時避難場所となる公園、また、区内全域の公園、こうしたところにも整備をすることが必要と考えますが。","respondent":"宮澤情報推進課長","answer":"ただ、災害時の情報入手手段の確保ということで、震度５強以上の地震が発生した場合、自動で登録なしで接続できるような状態に切り替わるという機能もあります。そういった災害時の利用も考えながら、所管の部署の考え等もありますので、連携しながら調整していくです。","id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"利用が少ないのが公園だというご答弁でありますが、自動的に切り替わるという今の情報提供の話もありました。要望で終わります。広報紙についてですけれども、広報しながわの戸別郵送についてお聞きしたいと思います。平成２８年度から実施されていると認識しております。３年間の推移など、また事業の検証など、今後、この戸別郵送についてどのように考えていらっしゃるか、まずお聞きしたいと思います。","respondent":"大澤広報広聴課長","answer":"平成２８年度に条件を外しまして、希望する方どなたでも配送をしているところです。平成３０年度が約１,６００件、令和元年度が約２,２００件、令和２年度が約２,５００件で、現在が約２,８００件という数になってあります。","id":"exchange-085"},{"speaker":"こんの委員","kind":"質問","question":"ましてや新聞をとっておりませんし、こうしたものが公共施設に置かれていることもご存じない方がいらっしゃって、高齢者ですと、そこまで取りに行くというのがなかなか難しいところなので、ホームページでご案内をされているのだと思いますが、私はもっと区民の方に広報、周知をして、広報しながわを１人でも多くの方に手に取っていただいて、基本的な情報を知っていただく。","respondent":"大澤広報広聴課長","answer":"まだまだ周知が不足しているですので、今後も広報しながわの周知および戸別配送の周知に努めてまいります。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問","question":"これはどういう考え方でこの金額が出てくるのか、仕組みを教えてください。今回、４２項目です。この選定基準は何なのでしょうか。これは誰が受けているのでしょうかということで、対処方法についてお聞きします。この大型のイベントは、ほとんどコロナ禍で中止になっておりますが、今後、国は、試行で何かいろいろやるようでありますけれども、品川区は、それを待っているのでしょうか。","respondent":"黒田財政課長、古巻総務課長、篠田文化観光課長","answer":"基金の額のお尋ねですが、こちらにつきましては、当初予算編成時に、当然歳出予算に必要な経費を歳入からやりくりして充てるという中で、一定程度。苦情処理ということで、全般的なお話になろうかと思うので私のほうからお答えいたしますけれども、苦情に関しましては。イベントの実施にあたりましては、私どもで所管しているものでいえば、区が主催しているものと、あとは様々な実行委員会が主催していて。","id":"exchange-087"},{"speaker":"西本委員","kind":"提案","question":"だから、どういう考え方で成果を見ていくのかということ。それから、職員のクレーム対応です。なので、１つは専門家が必要ではないかという提案と、それから、そういう職員の方々へのメンタルヘルス、メンタルケアはしっかりやっていただかないと、そういうメンタル的なところを病んでしまって業務に差し支えるというのはよくないことですので、そのフォローはどうされているのかお聞きしたいと思います。","respondent":"黒田財政課長、古巻総務課長","answer":"基金の金額の振り分けというお尋ねですが、基本的に、予算は会計年度独立の原則がありますので、その年度の歳入は、その年度で支出するというのが原則の中で、当然、歳入については固く見ますし、歳出については機動的に。クレーム対応につきましては、区政相談員という専門の方が総務課におり相談を受けているところです。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、１７９ページの人事管理費に関連して、保健所職員の体制等、残業などの勤務状況について伺いたいと思います。時間があれば、１６７ページの指定管理者モニタリング・評価経費について、基本方針とモニタリングについて伺いたいと思います。保健所の体制について伺いたいと思います。現在、病休をとられている方が何人いらっしゃって、育児休職中の方が何人いらっしゃるのかについても伺います。","respondent":"崎村人事課長","answer":"令和３年度増員した保健師の定数というご質問ですが、今年の第１回定例会でもご説明しましたとおり、福祉計画課に１名と保健予防課に４名、合わせて５名の定数増を図ったところです。今年度、令和３年４月１日の採用者数としては、６名採用したところです。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回のコロナ対応の体制ですが、対応した最大の体制を一般質問でも伺ったのですが、保健師、看護師は、最大の体制、８月だと思うのですけれども、７１名ということで答弁があったのですが、その常勤職員、会計年度任用職員、派遣、それぞれの人数も教えていただきたいと思います。","respondent":"崎村人事課長","answer":"今回のコロナ対応の体制というところですけれども、やはり８月にかなり感染が急激に拡大いたしまして、先ほど委員の説明の中で７１名とあったかと思うのですけれども、これは恐らく事務等も含めた数かと思うのですが、保健師、看護師につきましては。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一般質問の答弁では、保健師、看護師が常勤換算で７１名、事務職が２７名、合わせて９８名という答弁だったのです。多分、今年度は８月の残業が一番多かったのではないかと思うのですけれども、今年最も残業が多かった月、８月の最も多い保健師の残業時間数を教えていただきたいのと、今年度４月から８月までの月平均の残業時間がどれくらいあったのか伺いたいと思います。","respondent":"崎村人事課長","answer":"感染症関係で８０時間を超える残業をした保健師が何人いたかというご質問かと思うのですけれども、この８月で、先ほど会計年度任用職員数、常勤職員数を回答いたしましたが、１４名おりまして、内訳としては、常勤職員７名と、会計年度任用職員７名となっていたところです。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１００時間を超えた方が分かったら教えていただきたいと思います。今伺って、１か月の残業が２００時間を超えるというのが、どのような働き方なのかというのはちょっとイメージがつかないですけれども、どのような働き方だったのかということを教えていただけたらと思います。これをどう総括して今後に生かしていくかという点についても伺いたいと思います。","respondent":"崎村人事課長","answer":"今後のコロナの状況によって、どのような体制がいいのかというのは今後また検討していく必要があると思うのですけれども、これまで体制をとってきた中では、機動的に動けるところで応援職員の活用ですとか、人材派遣の活用というところを行ってきたところです。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に今回のコロナで、日本全体ですけれども、医療や公衆衛生の脆弱性が浮き彫りになったと思います。その上、この品川区は保健師の定数がもともと２３区で最低というところでのコロナの対応となったため、より大変だったのではないかというふうに思います。ドクターも２人しかいないというのが大きな負担になっていると思うので、これも強化することが必要ではないかと思いますが、いかがでしょうか。","respondent":"崎村人事課長","answer":"先ほどの繰り返しになるかもしれませんが、コロナの状況に応じた体制というのは、今後、検討していく必要があるとは考えております。保健師の数につきましては、コロナ禍以前より、議会の予算特別委員会ですとか決算特別委員会で様々な意見をいただいているところです。","id":"exchange-093"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、１８５ページ、地域振興経費、これは障害者の地域活動について、２つ目、１７１ページ、シティプロモーション推進経費、１７３ページ、デジタルサイネージ運用経費、一般質問でお伺いした壁面ビジョン等をお伺いしたいと思います。障害者の地域活動ということで、防災の視点からいろいろお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"芹澤委員","kind":"提案","question":"福祉の話になると、どうしても福祉部の話になってしまうということですが、オリ・パラが終わって、レガシーだと思いますけれども、障害者の方々が、障害者だけでやっている地域活動ではなくて、いわゆるみんながやっている、町会だけではなくて、地域活動に参画できる幅を地域活動課のほうでぜひ広げていただきたいなという思いがあって、例えば、これは提案ですけれども。","respondent":"川島地域活動課長","answer":"今、委員のご提案のような障害者の方の参加を促すというようなところですが、私のほうとしても、町会側、町の方のほうからの要望等というのは今初めてお聞きしたようなところですので、例えばどのような支援が必要なのか、それから。","id":"exchange-095"},{"speaker":"芹澤委員","kind":"質問","question":"障害者の方々だけではなくて、地域活動に積極的に参加したいという思いはあれど、なかなか参加できていないというような課題もあるかと思いますので、ぜひご研究いただければと思います。シティプロモーションについてお伺いします。一般質問でも伺いましたけれども、庁舎、あとは施設の外での情報発信ということで、例えば、一般質問でお伺いした大崎駅前では情報発信をしていると思います。","respondent":"大澤広報広聴課長","answer":"デジタルサイネージにつきましては、これまで屋内にのみ設置をしています。現在は、機能や形状がレベルアップしていると聞いておりますので、それを踏まえて、今後、屋外への設置も含め検討していきたいと考えています。","id":"exchange-096"},{"speaker":"芹澤委員","kind":"質問","question":"どれだけの件数があるかということで、今お話があった、大崎駅前以外には、そういったデジタルサイネージとか、区の情報発信をしている場所はないということでよろしいでしょうか。","respondent":"大澤広報広聴課長","answer":"屋外へのデジタルサイネージの設置はございません。","id":"exchange-097"},{"speaker":"芹澤委員","kind":"質問・要望","question":"屋外での情報発信をぜひしていただきたいという視点でお伺いしていきたいと思います。今後の町会掲示板の在り方、ふれあい掲示板とかの在り方にもつながるのですが、今は紙でペタペタ貼っていらっしゃると思うのです。これも再開発に合わせて、デジタルサイネージに変えていくということも考えなのかなというふうに思っていますけれども、そこのご見解をお聞かせください。","respondent":"大澤広報広聴課長","answer":"リース期間が切れるものが令和４年度から出てきますので、新しい機器の研究もした上で、今後の展開は検討したいと考えておりますが、まずは区の施設の外に設置して、その効果を検証した上で、そのほかの設置場所については検討していきたいと考えています。","id":"exchange-098"},{"speaker":"芹澤委員","kind":"質問","question":"最後に、あわせて情報発信ということで、トランスというのですか、道路に置かれている変電機器といいますか、あそこでの情報発信ということもお伺いしたいと思います。あわせてデジタルサイネージを区の施設外にというようなお話も先ほどあったと思いますが、そういった場合には、企業の広告を入れていくということも手かと思うのですが、そのおつもりでお考えなのかお聞かせください。","respondent":"大澤広報広聴課長","answer":"デジタルサイネージにつきましては、これまで広告についても検討したことがありますが、屋内にあることから、見る方が限られているということで、広告主がつかないという判断のもと、今までやってきませんでしたが、今後、屋外に設置するということであれば。","id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問","question":"１７１ページ、ホームページ等経費、それから１８１ページ、庁舎管理費、電話料、１８９ページの国際交流推進事業をお聞きします。「Language」というところです。」と。それから電話料については、令和２年度予算が１,８００万円、決算が２,１００万円余と増えているのですが、恐らくコロナとかいろいろなことで増えたのだと思うのですけれども、なぜ増えたのか理由を教えてください。","respondent":"大澤広報広聴課長、東野経理課長、古巻総務課長","answer":"自動翻訳につきましては、自動翻訳の機能に限度がありますので、自動翻訳機能をつけているところは。これは、委員がおっしゃるように、新型コロナウイルス感染症対応等によります固定電話の通話時間、また通話回数が大幅に増えたことが原因です。大使館との交流ということで、特にミャンマー大使館ですけれども、区として、特段、ミャンマー大使館に特化して何か交流をということは現在ございませんで。","id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問","question":"その増やした回線は、今、コロナの感染者数は少なくなってきたかもしれませんけれども、また第６波とかがあるので、そのまま残していく必要があるのだとは思うのですけれども、これがある程度見えてきたときに、これはどのようになっていくのか、レンタルではないように聞いているのですけれども、この分は使わなくても基本料金を取られるのか。","respondent":"大澤広報広聴課長、東野経理課長、古巻総務課長","answer":"ホームページの自動翻訳の機能につきましては、もう少し優しい表現になるように工夫してまいります。新型コロナウイルス感染症収束後ですが、こういった状況を鑑みまして、全体を精査した上で、休止という措置をとっていきたいと考えております。今、委員からご紹介がありました青稜中学校・高等学校のＳＤＧｓ部による募金活動についてですが。","id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。ホームページはよろしくお願いします。そして今、ミャンマーのほうは、ぜひこういう動きを、どのような形で伝えるのかというのがありますけれども、やっぱりせっかくこういう動きがあるので、区内に大使館があるわけですから、そういう中でいろいろ話題にしながら、さらに深まるようなことを、待ちではなく一歩踏み出していただければと、お願いしたいと思います。","respondent":"東野経理課長","answer":"委員からお話がありました費用の調査ですけれども、災害時の拠点であることなどを考慮して、安定した通信機能の確保に努めてまいりたいと思います。","id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１６９ページ、財務書類作成委託、１８３ページ、新公会計運用経費、２１２ページ、監査委員費、時間があれば、前後してしまいますけれども、１８３ページ、庁舎機能検討経費です。これは要望です。それから３点目として、職員研修の重要性についてというようなことが挙げられております。ほかにもあるのですが、この３つに関して、具体的にどのような成果があったのかご説明いただきたいと思います。","respondent":"中山会計管理者、佐藤（聡）計画担当課長","answer":"当初の予定では、財務会計を入れると自動的に仕訳ができて、その仕訳をすることで、全て事業別もできるようなイメージでおったわけなのですが、実際には財産を各課ごとに分けて、その各課ごとに分けた財産を。行政評価における部分ですが、現在、総合実施計画を策定しておりまして、その中で成果指標等を設定することに加えまして。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"新公会計についてはまた別の機会にお尋ねしたいと思います。この監査基準が決定されるまでの経緯と、それから、この法的というか、どのような位置づけで協議決定されたのか、条例とか要綱でもないのですが、どのような位置づけになっているのでしょうか。お尋ねします。","respondent":"今井監査委員事務局長","answer":"こちらは、地方自治法の改正がございまして、監査委員制度の強化などの基準が変わりましたときに、令和２年４月から、各監査事務局については、監査基準を設けて、その監査基準に従って監査を実施することという定めがございましたので、地方自治法の改正に基づいて、私ども。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"意見","question":"これまで品川区監査委員事務運営要綱というものがあったと思うのですが、そちらとの関係性もお尋ねします。お願いします。","respondent":"今井監査委員事務局長","answer":"初めに監査基準ですけれども、こちらについては、令和２年３月２５日に、監査委員協議会の中で最終的に決定しております。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"今ご説明いただいたような形で基準が決められたと。監査については様々なものが出されていて、ホームページに、このところ、きちんとアップされていることで、非常に分かりやすくなっていると思います。次の質問は、議会選出監査委員についてなのですが、議会選出監査委員が決算特別委員会に出席して、説明や質疑応答を行うということに関しては、監査委員のいろいろな規定から問題が生じるものでしょうか。","respondent":"今井監査委員事務局長","answer":"決算特別委員会の審議の内容については、決算のそれぞれの項目によって行っておりますが、一方、監査委員におきましては、決算審査のヒアリングという形で、別途意見書なども出していますので、やはり監査委員としての役割と。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"提案","question":"いろいろ議論があるところですが、岐阜県可児市では、予算決算委員会にて、議会選出監査委員の方が監査の報告と現状や結果について説明し、それで報告して質問を受けていると。これがどうということではなくて、それぞれ議会の考え方もありますけれども、そういったことがあるということで、今後、検討、また私も勉強して提案していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は、決算書２０７ページ、ふるさと納税事業から伺います。決算が２４２万円余と出ています。これはもう本当に都市部の悩みであり、東京の大きな課題であり、国への要望は本当に強くやっていかなければいけないと思います。この辺の金額は、どのような理由で増えているのか、併せて伺えればと思います。その辺のところ、単に概要説明ではなくて、思いが示されているものなのかも併せて教えてください。","respondent":"提坂税務課長","answer":"区の思いということですけれども、２３区で足並みをそろえまして、過当な返礼品競争には乗らないで、区としては地場産品もなかなか見つけにくい部分がありまして、その代わりに体験型返礼品をいろいろ企画するということと、あとサンリオのご協力をいただいて。","id":"exchange-108"},{"speaker":"渡辺委員","kind":"質問","question":"その中の方法論のところで、主要施策の成果報告書のところ、違う冊子に、主要施策として取り上げられている。ここで単純に入と出を比較するのではなくて、やはり大切な税がどう区民に還元されるか、そのようなところで、数値目標が内部的にも含めてあるのかどうか教えてください。やはり出が現実にはある中で、どれだけやると合格点と見据えられるのか、まず、その辺の所管の見解を教えてください。","respondent":"提坂税務課長","answer":"現状といたしましては、正直なところ、明確な件数とか目標は設定してございませんが、とにかくより魅力的な体験型の返礼品を追加するですとか、使い道を限定した寄附とか、その辺を様々企画して、少しでも件数、金額を上乗せしていきたいと考えているところです。","id":"exchange-109"},{"speaker":"渡辺委員","kind":"質問","question":"後の話にも絡んでくるのですが、数値目標はあっていいのかなと。それは所管だけではないことがあると思います。８月３日の東京新聞の記事で、「都民返礼品なくてもコロナ禍支援」というタイトルで、自分自身が住まわれているところにふるさと納税を行うことが、増加しているという記事がありました。これは品川区でも同趣旨のことを取組まれたと考えています。主な取組事業を教えてください。","respondent":"提坂税務課長","answer":"主な取組事例といたしましては、やはり昨今の新型コロナに関する寄附をお受けするということと、水辺への桜の植栽といったところを今まで実践してきたところです。","id":"exchange-110"},{"speaker":"渡辺委員","kind":"質問","question":"この記事だけではなく、各区もいろいろ知恵を出しているなど、競争ではないのですが、多分、それぞれのらしさ、ここで伺いたいのは、品川らしさをキーワードに取組んでほしいという願いを込めて言います。コロナ禍における対処法が一番分かりやすかったのですが、これからコロナが収まった場合も想定しながら、あるいは通常の品川区の事業にどう役立てられるかという点で、３つに分けて伺います。","respondent":"提坂税務課長","answer":"オール品川ですけれども、それも今申し上げたものと重なりますけれども、各所管課の考えですとか、あと、区民の皆様の要望、その辺を整理して考えていきたいと考えています。","id":"exchange-111"},{"speaker":"渡辺委員","kind":"提案","question":"そこでちょっと提案します。金銭だけではなく、今一番の行政課題は、区民の皆さん、１人でも多くの方に関心を持っていただくこと、多くの人が参加されることに意義があるという仕組みは、ふるさと納税は打ってつけだと思います。そしてもちろん税額の課題もありますが、その点、今、何点か提案も含めて言わせていただきましたが、方向性とともに意欲のほどを教えていただければと思います。","respondent":"提坂税務課長","answer":"今委員のご指摘にあったように、１人でも多くの区民の方に参加していただく、あと課題を共有していただくために、１つのきっかけとして、今、文化・スポーツですとか、防犯、ＳＤＧｓ、障害福祉というお話がありましたけれども、そういうそれぞれの分野で。","id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"１９１ページの歩行喫煙防止推進経費に関して伺います。残念ながら、令和２年度の決算額が６,０００万円余というところで、執行率が６２％弱ということでございました。ここの改善について、何かその後というか、また今後も含めて、どういうふうに取組まれるのか、２点お伺いいたします。","respondent":"森田生活安全担当課長","answer":"大崎駅西口バスターミナルにつきましては、反対側にも加熱式型専用の喫煙所を設けまして分散をしています。設置当初は、加熱式の場所にも紙巻きたばこを吸う方がいらっしゃいましたが、今は、ほぼ１００％、加熱式を吸う方になっているということで認識しております。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、これまでコンテナ型喫煙所につきましては、いわゆる感染防止のための新しい技術、こういうものに着目して、慎重に計画を進めるというご答弁を昨年度から何回かお聞きしているところですが、何かそういう新技術の進展があったとか、そこら辺についてのお話を伺いたいと思います。ほかの７か所、８か所との違いとしては、こういう地理的な特徴がある場所だと。","respondent":"森田生活安全担当課長","answer":"しかしながら、中の煙を外に出さないような浄化作用のある機器を設置したりして、他区のほうではやっているところです。そういったものも参考にしながら、私どものほうでもコンテナ型については検討を進めていきたいと考えています。","id":"exchange-114"},{"speaker":"若林委員","kind":"確認","question":"積み残しになっているコンテナ型喫煙所については検討する、また、大崎駅西口のバスターミナルについても検討の俎上に上がるということで理解してよろしいですか。確認させてください。","respondent":"森田生活安全担当課長","answer":"大崎駅西口につきましても、他の場所につきましても、受動喫煙防止の観点から、必要なことを考えながら進めていきたいと考えています。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"令和４年度、来年度の予算に向けて、改めて強く要望しますので、よろしくお願いいたします。ということで、生活安全パトロール隊等のいわゆる過料を取るところ、それから、要するに、あそこはパーテーションの外に出て、いわゆる喫煙をする方が、常に、ある意味でいえば、いつもいらっしゃる。見るたびに枠の外で喫煙をしている。いわゆるモラルハザードが当たり前になっている地域です。","respondent":"森田生活安全担当課長","answer":"喫煙の取締りも含めまして、地域の安全のために尽力してまいりたいと考えています。","id":"exchange-116"},{"speaker":"藤原委員","kind":"質問","question":"それと、具体的な成果を教えてください。次に、１７９ページの会計年度任用職員給与費についてお伺いしたいと思うのですけれども、これは、いわゆる非常勤職員のことだと思うのですけれども、これこそ同一労働同一賃金が大前提だと思うのですが、品川区において、その辺はどういうふうに活用されているか教えてください。それと最後に１８１ページ、働き方改革推進事業の具体的な成果を教えてください。","respondent":"森田生活安全担当課長、崎村人事課長","answer":"私も、６月、しながわ花街道に行きまして、わんわんパトロールの登録者募集を出前型で実施しましたところ、８名の方に登録いただきましたので、このような、地道ではありますが。品川区の特徴といったところでございましたけれども、共通的に我々管理職が６０歳で降任をするといったところで、今後の課題といたしましては、やはり管理職への昇任意欲の醸成ですとか。","id":"exchange-117"},{"speaker":"藤原委員","kind":"質問・要望","question":"人事はよく分かりました。継続してやっていっていただきたいと思います。それで、生活安全担当課長、なぜ自動販売機を伺ったかというと、この条例の第５条３項に、「自動販売機の設置または管理を行う事業者は、回収容器を設置し、これを適正に管理する」と書いてあるのです。なぜかというと、私も目視しています。では、どこに持っていくのですか。ほかのところです。自動販売機について答弁ください。","respondent":"森田生活安全担当課長","answer":"個数につきましては、私も把握しておりませんでしたので、自動販売機協会にも、昨年度、協力の呼びかけをしたところでありますが、そこに確認をしてみたいと考えています。その上で、どのような形で対応できるかということについても検討した上で対応を図りたいと思います。","id":"exchange-118"},{"speaker":"安藤委員","kind":"質問","question":"１８７ページ、地域センター等管理運営費、区民集会所のフリーＷｉ－Ｆｉについて、１７８ページ、人事管理費に関わって障害者雇用、１８３ページ、庁舎機能検討費に関わって新庁舎検討について伺います。現在、区民集会所のＷｉ－Ｆｉは、１時間で一度切れる仕様になっているのですけれども、なぜ１時間で切れるようになっているのか理由を伺います。","respondent":"宮澤情報推進課長","answer":"お知らせに関しましては、しながわフリーＷｉ－Ｆｉの設置場所、施設等を、区のホームページでお知らせするとともに、６０分の制限時間等々の注意点をお知らせしています。","id":"exchange-119"},{"speaker":"安藤委員","kind":"質問","question":"ですから、不親切だなと思って、そこを改善してもらいたいと言いたいと思います。でも、１時間でＷｉ－Ｆｉは切れてしまうので、例えばＺｏｏｍで報告会とか会議等を行うということがコロナで増えました。これからも増えていくと思います。少なくとも、貸出ししている時間内は、切れないようにするべきだと思うのですけれども、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"１回の利用時間が６０分という理由は先ほど申し上げたとおりです。連続して利用することは可能ですが、例えば区民集会所だけ利用の時間数を変えるというのは、今のしながわフリーＷｉ－Ｆｉの技術上の観点から、困難という状況です。","id":"exchange-120"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望です。次に、障害者雇用ですが、言うまでもなく、共生社会を築く上で、自治体自身が率先して障害者雇用を促進していくというのは、もちろん大変大切なことだと思うのです。伺いますけれども、法定雇用率は、今、２.６％だったと思うのですけれども、法定雇用率に対して現在の品川区の障害者の雇用率は何％でしょうか。それぞれの障害種別ごとの雇用人数と雇用率も伺いたいと思います。","respondent":"崎村人事課長","answer":"といいますのも、こちらは平成３０年度までについては、身体障害者を対象とした採用試験を行っていたのですけれども、令和元年度からは、知的障害者、精神障害者に拡大いたしまして、採用選考を特別区で実施しています。","id":"exchange-121"},{"speaker":"安藤委員","kind":"意見","question":"身体障害以外に、例えば知的障害、精神障害、発達障害、視覚障害、聴覚障害とありますけれども、身体障害者以外の方の雇用は、今現在、品川区では実績があるのか、何人いらっしゃるのか、答弁できる範囲でぜひお知らせください。","respondent":"崎村人事課長","answer":"発達障害につきましては精神障害者のところに含まれておりまして、視覚障害、聴覚障害につきましては身体障害者としてカウントされているところです。","id":"exchange-122"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。視覚障害者の方の雇用は現在あるのかないのか、そこも伺いたいと思いますし、あと、法定雇用率から今大きく離れているということで、これはもう早急な改善が必要だと思いますが、それは当然のこと、全ての障害種別ごとに雇用率の目標を定めて推進するべきではないかと思うのですけれども、そちらも併せて伺いたいと思います。","respondent":"崎村人事課長","answer":"障害種別ごとの目標数値というご質問ですけれども、こちらは特別区の採用選考上、やはりどの種別を何人採用するかということではなく、障害者選考として何名採用するか、こちらも筆記試験で能力実証を行った上での採用になりますので。","id":"exchange-123"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点お伺いしたいのですが、総務部長から、去年の決算特別委員会の中で、チャレンジ雇用という話も答弁がありまして、区の中で雇用をして一般企業の就職につなげるとか、そういう方向性ができないかどうか検討していきたいというご答弁があったのですが、現在どのような検討状況になっているのかというのを、まず１点伺いたいのと、あと。","respondent":"崎村人事課長","answer":"区の業務といたしましては、やはり窓口ですとか電話等の対人業務が大半を占めておりますし、パソコン操作も、住民情報システムですとか、文書管理、財務会計等の操作が主となってきますので、そういったチャレンジ雇用に向く業務があるのかないのかというところは。","id":"exchange-124"},{"speaker":"安藤委員","kind":"質問・要望","question":"チャレンジ雇用については、まだ検討が続いているということですが、ぜひ早く検討の上、具体化していただきたいと思いますし、社会福祉法人については、やはり把握することが必要なのではないかというふうに思っています。以上２点を求めたいと思いますけれども、いかがでしょうか。","respondent":"崎村人事課長","answer":"区としてというところでは、人事課としてお答えはなかなかできないのですけれども、やはり人事課としては、区内の事業所である区役所の中の法定雇用率については、もちろん把握をして、それの改善に向けて取組んでいく必要はあるというふうに考えております。","id":"exchange-125"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に新庁舎ですが、本会議の続きにもなるのですが、３６億円かけて現庁舎の耐震補強工事を行って、あと１５年もつのだという指摘に対して、総務部長が一度耐震はしておりますけれども、それで万全だという形にはならないような状況も今後考えられますと、ちょっと意味深な答弁があったのですけれども、これはどういう意味なのでしょうか。伺いたいと思います。","respondent":"東野経理課長","answer":"庁舎は耐震の措置はしてありますが、設備的なところでかなり老朽化が進んでいるものです。そういった意味で、庁舎自体が万全かと言われれば、そうではないという意味でお答えしたものです。","id":"exchange-126"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私は、しっかりと一度立ち止まって、住民に計画を知らせて、一からしっかり検討するべきだというふうに思っております。これはコロナの前から変わりません。なぜ景観計画では実施した説明会を新庁舎整備基本構想（素案）のパブコメではやらないのでしょうか。違いは何なのでしょうか。伺いたいと思います。今回も景観計画と同様、説明会を複数箇所で実施すべきではないのでしょうか、伺います。","respondent":"東野経理課長","answer":"というのは、まず、町会に対してチラシをつくりました。デジタルデバイドへの対応としてデジタルに不慣れな方に対してもきちんとお知らせをするという方向で、約１万枚のチラシをつくりまして、今月、町会のほうへお配りしています。回覧という形でお願いしているものです。","id":"exchange-127"},{"speaker":"安藤委員","kind":"質問","question":"住民の前に出向いていって、膝を突き合わせて対面で説明するということをなぜやらないのでしょうか。今言ったのは、全部、一方通行だと思います。それは区民の前へ出たくないということなのかなと思います。私はそういうふうに理解しましたけれども、コロナが明けたら、パブコメに伴って説明会をやることはあり得ると、やるのだということでよろしいのか伺います。","respondent":"東野経理課長","answer":"私からは、コロナ禍ということでご説明させていただきました。こういう社会情勢でないことを踏まえまして、区民への周知につきましては、あらゆる手段が考えられると考えています。","id":"exchange-128"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区新庁舎整備基本構想・基本計画策定委員会の中で、和氣副区長が、ぜひ多くの意見をいただきたいと、パブコメについて述べておりました。しかし、多くの意見を得るためには、多くの区民から意見をいただく内容について、まずは区民によく知ってもらわなければなりません。ぜひそうした説明会の実施、今からでも行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"大沢委員","kind":"質問","question":"１６９ページ、依命通達について、それと１８１ページ、働き方改革推進事業、１８５ページ、地域振興事業、順不同で伺わせていただきます。蛇足ですけれども、その前に私の先祖のお店があったという、これだけ一応お話しますが、これは私事ですので関係ありません。今、現状起こっている縦のつながり、マンションになってしまったところと地元町会、どのような問題、課題が起きているのか教えてください。","respondent":"川島地域活動課長","answer":"当初、マンション１棟でまとめて、建設のときに町会に加入という話がまとまって、町会費、何年かは納入される、１棟まとめて納入されるのですけれども、数年経過して、管理会社のほうからその見直しを求められて、支払いが止まるというような事例が、ここ数年。","id":"exchange-130"},{"speaker":"大沢委員","kind":"確認","question":"もう一度確認させて、今そういう事例は、区内あるいは都内でも起きているというような認識でよろしいか。","respondent":"川島地域活動課長","answer":"こちらは区内に限った話ではないということですけれども、私が詳しく把握している事例だと、区内でも、５件ぐらいはもうお話を聞いておりますので、区内、都内全域、都市部の問題なのかもしれません。","id":"exchange-131"},{"speaker":"大沢委員","kind":"質問","question":"都市部であるがゆえに、品川区においては、私の地元である武蔵小山、今後このような課題の下に町会活動を進めていかなければいけなくなるというところですけれども、こういった場合、地元町会は、今、課長がおっしゃった問題に、どのように対応し、また区はどのようなサポートをしていただくのか、教えてください。","respondent":"川島地域活動課長","answer":"こちらも踏まえまして、どのように条例をしっかり周知していくかとともに、町会活動に参加するメリットを何らかの形で紹介できるような対策を検討していきたいと考えております。","id":"exchange-132"},{"speaker":"大沢委員","kind":"質問","question":"支援ということで、具体的に何をどうしようというところは見えないということでいいわけですよね。その具体的なものを行う以前の根拠として、条例、今おっしゃっていた地元町会に協力しなければいけないという大きな看板の下、前提の下にそれを行っていく、そのような考え方でいいのでしょうか。","respondent":"川島地域活動課長","answer":"委員のご指摘のとおり、条例にそういったことが明記されているので、その理念をしっかり伝えていく必要があるというふうに考えております。","id":"exchange-133"},{"speaker":"大沢委員","kind":"質問・要望","question":"次に移ります。依命通達とただ漠然としたもので質問してしまい大変申し訳なかったのですけれども、依命通達には予算執行と予算編成の２つがあるということであります。今伺いたいのは、予算執行のほうですけれども、令和３年度と令和２年度の予算執行に関する依命通達を比べて、どのようなポイント、どのようなところに違いがあるのか教えてください。","respondent":"黒田財政課長","answer":"令和２年度と令和３年度を比べて、予算執行の依命通達の点で大きく違うというところはなく、社会情勢に合わせて執行すべきというところを通達しています。","id":"exchange-134"},{"speaker":"大沢委員","kind":"意見","question":"今お話しいただきまして、大きな違いはないということでした。事務事業評価等を行っていますけれども、いわゆる所管する役職の課長、あるいは部長として、今年度の達成状況について、１００点満点のうちどれぐらいだということを、これはお感じになるしか、実際に数値を出すことは困難ですけれども、イメージで構いませんので、それを揚げ足取ったりしませんから、イメージでいいからちょっと言ってください。","respondent":"黒田財政課長","answer":"財政課の立場で申し上げれば、健全財政を維持して事業を行っているというところですので、１００点満点と言いたいところではありますが、１００点を目指して近いところで頑張っているのではないかというふうに認識しています。","id":"exchange-135"},{"speaker":"大沢委員","kind":"質問・要望","question":"分かりました。限りなく１００点、２００点に近くなる、健全財政を維持されているということですから、十分なお働き、予算執行の状況だと考えますので、今後ともよろしくお願いいたします。それと、すみません、市町村交流のところになりますけれども、今年度から総務課のほうに市町村交流が移りましたけれども、この理由と課題について教えていただきたい。","respondent":"古巻総務課長","answer":"総務課に所管が移ったということは、全庁的にしっかり市町村交流を進めていくべきだという考えのもとに総務課のほうへ移ったというふうに認識しておりますので、総務課がコーディネートをしながら、全庁各所管で様々な市町村交流が進むよう、今後。","id":"exchange-136"},{"speaker":"大沢委員","kind":"質問","question":"こういう時期だからこそ、積極的な市町村交流、コロナ禍におけるアフターコロナでしょうか、コロナと付き合いながら活性化した、あるいは活発な市町村交流、一ひねりも、二ひねりもアイデアを絞ってお願いしたいと考えていますので、よろしくお願いいたします。それと、オンライン会議について、どのように活用されていくのか、その２点をお願いします。","respondent":"崎村人事課長","answer":"オンライン会議につきましては、ウェブ会議室を区役所の中に２か所設けておりまして、人事課の横にも置いてありますけれども、非常によく使われているところです。こちらもテレワークと併せて、今後、引き続き検討していくべきものというふうに考えているところです。","id":"exchange-137"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１７３ページ、情報システム運営費、デジタル化の推進ということについて伺いたいと思います。それに関連して、１８３ページの庁舎機能検討経費のほうに関わる質問もさせていただければと思いますので、よろしくお願いいたします。","respondent":"宮澤情報推進課長","answer":"デジタル化の取組みは、先端技術の活用など多岐にわたりますが、そういった中で情報戦略担当は、区のデジタルトランスフォーメーションを推進していく中で、司令塔として各部署と連携していく大切な役割という形です。","id":"exchange-138"},{"speaker":"塚本委員","kind":"質問","question":"ちょっと質問がうまく伝わらなかったのか、いわゆる全庁的な業務の見直し的なことは、この情報戦略担当が、ワンストップ窓口とかということをやっていく上で、関わっていく部分があるのか、ないのか、その辺についてお伺いしたいと思います。","respondent":"宮澤情報推進課長","answer":"そこら辺を全庁的に、デジタル化の取組みは全庁的に関わってまいりますので、そういう業務改善を含めて、情報戦略担当で行っていくです。","id":"exchange-139"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういったことも情報戦略担当の所管としてやっていっていただきたいというふうに思いますし、そこら辺の私の認識として、区としてどうなのかということでお伺いしたいと思います。","respondent":"宮澤情報推進課長","answer":"デジタルトランスフォーメーションを進めていく中で、国の自治体ＤＸ推進計画でも取組むべき項目としてデジタルデバイド対策があります。","id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"説明ありがとうございました。私は両課長の参加があってもいいのではなかったのかというふうに思っているのですけれども、こういった新庁舎のデジタル化推進に当たっての検討がこれからどんどん進んでいく中で、品川区の情報部門は、どのように関わっていくのかお聞かせいただきたいと思います。","respondent":"東野経理課長","answer":"その整備方針の中に、デジタルデバイドの方への対策としまして、情報格差がないよう十分に配慮しますという記載があります。これらを受けまして、今後、基本計画の中でデジタルデバイドの対応、それからＤＸの推進に向けての考え方をまとめていくものです。","id":"exchange-141"},{"speaker":"塚本委員","kind":"質問・要望","question":"今ご答弁があったとおり、庁内におきましても、あと委員会の中の専門家の方々ともよく連携しながら、ぜひ目指すべきデジタル推進、デジタルトランスフォーメーションといったものを新庁舎に向けてまた進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"内容は分かったのですが、私は別の視点からお話を伺いたいと考えています。ここら辺のところも、やはりこれは今、すごく求められてくるのだろうと思っておりまして、そこら辺の考え方、両面で必ず必要になってくるけれども、そこら辺は、やはり１つ１つやっていくなら、採用の部分から、外部人材、そういうことから入っていくことも必要だと思っているので、そこら辺の考え方を教えていただきたいと思います。","respondent":"崎村人事課長","answer":"例えば、分野に応じてそういった人材を配置して、その方がさらにその分野の職員を育成するといったことも考えられるのかと考えていますので、今後の検討課題とさせていただければと考えています。","id":"exchange-143"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１つ、これは要望だけにとめます。１９９ページ、歴史館運営費でありますけれども、私は、今回の一般質問で、大規模特養の整備促進とか、グループホームの整備について質問いたしました。私も品川歴史館の改修については、大森貝塚との連携や、レストランだけでも集客できるとして改修を要望してきたという事実もあります。考え方だけを皆さんにお伝えしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/685794?Template=document&Id=1502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":107496,"voices":333}},{"id":"r03-20211005-4","meetingId":"r03-c-settlement","date":"2021年10月5日","dateIso":"2021-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村委員","kind":"質問","question":"決算書２５１ページ、家庭相談事業等から養育費確保支援。２６１ページ、区内私立保育園経費。２６７ページ、私立幼稚園費。時間が許せば、２４３ページのすまいるスクール運営費について順不同で伺ってまいります。養育費確保支援について伺います。区は、令和３年度養育費相談支援事業として、公正証書の作成費用および養育費立替保証契約の初回保証料の補助を始めています。","respondent":"伊東子育て応援課長","answer":"公正証書の作成経費の補助に関しましては、現在１件の実績があります。それと、養育費立替保証契約の初回保証料の補助につきましては、現時点ではまだ０件という段階です。ただ、継続して相談している方は何名かいらっしゃるというような状況になってあります。","id":"exchange-001"},{"speaker":"西村委員","kind":"提案","question":"他区の養育費確保支援事業の状況を少し伺ってまいりました。保証料の補助に関しては１件の利用もないという区がやはり幾つかございまして、力を入れておられる兵庫県明石市でも実績は大変少ないと伺っております。ですので、サービスの拡充を提案します。サービス拡充と、正しい情報を幅広く提供するため、セミナーの開催を提案させていただきたいと思いますが、ご見解をお聞かせください。","respondent":"伊東子育て応援課長","answer":"はこの公正証書や保証料の関係で、養育費の相談の支援事業を普及・強化していきたいと考えています。もう少しこの状況を見極めまして、その次のステップ、一般に情報提供するような機会だと思いますけれども、そういうところに広げていければと思っているところです。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"裁判を重ねて借金が残る場合もありますし、社会問題になっている背景がありますので、ぜひとも普及と、そしてご検討をお願いしたいと思います。今後のサービス拡充に関しましては、要望とします。次に、区内私立保育園経費から伺ってまいります。都内では、小規模保育事業を中心に０歳児の定員割れが始まっています。品川区の状況をお聞かせください。","respondent":"若生保育支援課長","answer":"小規模保育事業の定員割れの状況ですが、令和３年４月の入園状況で申し上げますと、２１園中１４園が定員割れをしているという状況です。","id":"exchange-003"},{"speaker":"西村委員","kind":"意見","question":"２１園中１４園ということで、半分以上かと思います。この原因、要因をどのようにお考えか、お聞かせください。","respondent":"若生保育支援課長","answer":"一方で小規模保育事業の特に０歳児にちょっと影響が出てきているというところは捉えております。それと、今年度４月の入園状況で申し上げますと、入園申込みがやや減少しているという状況もございまして、そういった状況なども要因としてあるのではないかと分析しています。","id":"exchange-004"},{"speaker":"西村委員","kind":"確認","question":"全国的には一時的に保育園の利用を控えるというコロナ禍の状況もあったかと思いますけれども、母親の就業率が高まりますと保育園の申込みが増えるという相関関係があるとも伺っておりますので、今後点数が低いフリーランスの方ですとか、起業している母親の方、様々な働き方の方、そして就業訓練で学んでいる方なども預けられるようになってほしいと考えています。","respondent":"若生保育支援課長","answer":"今後、こういった全体的な待機児童対策は進めつつも、この私立保育園関係の事業者への手当をどのような形でしていくかというところは、区として検討していきたいと考えています。閉園が出ているかどうかというところでは、令和２年度から３年度にかけては出てございません。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問","question":"他区では続々と閉園が続いているという記事を見ておりましたので、品川区は閉園せず頑張ってくださっているということで大変驚きました。コロナ禍の各園での個別対応も保育園は本当に大変だったと思います。まだまだ引き続き感染対策も必要かと思いますが、どうぞよろしくお願いいたします。次に、認可保育園の特別支援について伺います。強化した保育士の支援体制についてお伺いさせてください。","respondent":"初貝保育教育運営担当課長","answer":"特別支援保育に対する支援に関しましては巡回相談を増やしておりまして、具体的に申しますと、臨床心理士であったり、その辺りを増やしておりまして、特別支援児の実績も年々増えているという状況も背景にございまして、強化をしています。","id":"exchange-006"},{"speaker":"西村委員","kind":"意見","question":"懸念しておりますのは、相談件数が増えて、臨床心理士の方が不足してしまって、なかなか巡回依頼をしても訪問していただくのに数か月かかってしまうというようなことを懸念しております。保護者に対しまして、訪問後どのようなフォローをする体制になっているのか、併せて２点お聞かせください。","respondent":"初貝保育教育運営担当課長","answer":"区立保育園の中では、各園に対して巡回相談というところで、一義的には保育士に対して、どういった保育をするべきかということで巡回相談を順次しておるところです。その保育士を通じて、保護者の方にもどういう対応をするべきかというアドバイスを差し上げているところです。","id":"exchange-007"},{"speaker":"西村委員","kind":"質問・要望","question":"引き続きよろしくお願いいたします。次に、私立幼稚園費について伺ってまいります。保育現場では、より処遇のよい職場へと人材が流れまして、幼稚園教諭から保育従事者へと職種転換をする方も増えた結果、今度は幼稚園も人材不足が進んでいると伺っております。私立保育園で伸びている宿舎借上支援事業ですとか、家賃支援を幼稚園教諭にもご検討いただきたいと考えています。お考えをお聞かせください。","respondent":"若生保育支援課長","answer":"区としましては、資格や職務内容、勤務条件などは幼稚園と保育士で若干異なる部分もございまして、単純な比較はできない部分もありますが、まずは給与水準とかにどのぐらい差があるのかですとか、職員確保がどれだけ困難なのか等々。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問","question":"幼稚園でこの数年大きく変わってきたのが、幼稚園にも働く母親が増えた結果、幼稚園での預かり保育が増えているという現状かと思います。幼稚園を途中で辞めて保育園に移るご家庭も毎年いらっしゃると伺いました。幼稚園の在り方、預け方は今後ますます課題になっていくと感じております。幼稚園における預かり保育の現状をお伺いさせてください。","respondent":"若生保育支援課長","answer":"実施数ですけれども、私立幼稚園１８園中、１７園が預かり保育を実施しております。","id":"exchange-009"},{"speaker":"西村委員","kind":"提案","question":"預かり保育が増えるほど、また預かり保育の人材不足になっていくというループに今後なっていくことが想定されます。以前シニア人材の活用についてご提案をさせていただいたことがありました。保育士、幼稚園教諭は子育て中の方も多くいる職場ですので、働く方たちも家庭と仕事を両立できますよう、労働時間の見直しや働き方の改革が進んでいきますよう、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"２３８ページ、児童福祉費、在宅子育て支援について伺います。２６０ページ、保育支援費については、保育所関連処理の押印見直し、またメール提出について。２６９ページ、地域子育て支援拠点事業については、オアシスルームの予約の改善。２４３ページのすまいるスクール運営費、長期休業中の配食サービス活用について伺っていきたいと思います。","respondent":"若生保育支援課長","answer":"ベビーシッターの一時預かり利用支援事業、それから地域型保育事業への支援、巡回相談の充実等々です。こちらは現在具体的な検討等を進めているところでございまして、実施に向けて具体的に今後詰めていきたいと考えています。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"それから先ほどの質疑の中でそうしたニーズをしっかりと受け止めていただく大切な場所としても、支援をしていく必要性というのはあるだろうと思いますので、引き続きよろしくお願いしたいと思います。新たな機関を作るというよりも、まさに横串にしていくというような位置づけであるわけでありますけれども、区としてのその後のこの辺りの検討状況があれば教えてください。","respondent":"廣田子ども育成課長","answer":"在宅子育て支援についてのご質問です。今、就労家庭であっても育児休業を取る方もたくさんいらっしゃいますので、０歳から２歳の乳幼児を持つご家庭につきましては、非常に支援が必要だと考えております。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"当時も子育て支援のサービスが４課、また幾つかの係に分かれています。支援を川上で何とか防ぐのか、川下まで行ってぎりぎりで何とかするのかというよりも、しっかりとその体制を充実させていただきたいと思います。縦軸の行政として都でやってもらわなければ区もできないとか、いろいろなものがあるかと思うのですが、そのあたりの押印の見直しだとか、メール提出の可否について、現状を教えてください。","respondent":"若生保育支援課長","answer":"押印については会計事務規則のほうに規定されており、統一的な取扱いとなっておりますので、この見直しについては今後全庁的な検討が必要と考えています。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"次は、歳入でも確認させていただきましたけれども、オアシスルームの予約についてでありますが、これはネットが９８.２％でコールセンターが１.８％の予約受付状況というところで、一定の予約の在り方の改善についてはご答弁いただいたところでありますが、これは決算書を確認すると、インターネット予約システム経費が６６０万円、コールセンター経費が６１０万円とほぼ同じような金額で。","respondent":"若生保育支援課長","answer":"オアシスルームは現在コロナ禍で利用を制限していますけれども、今後、コロナ後を見据えてまた利用が伸びてくることも見込んですので、施設の開設等の検討と併せまして、システムの検討も進めてまいりたいと考えています。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"産後家事育児支援で産後ドゥーラの養成、資格取得費用助成を提案させていただきまして、今年度からやっていただきました。２０万円の助成かと思います。まだこれは資格取得した後に、後ほど申請していただいて、助成金を受け取っていただく流れかと思いますが、今この辺りの相談だとか、実際に取得をされて助成された方がいるのかどうか、その辺りの数字的なこと、現状を教えてください。","respondent":"山下子ども家庭支援センター長","answer":"お問合せ等々につきましても、ドゥーラ協会等から一部頂いているところはありますが、まだ直接、区民で産後ドゥーラ資格を取られた方からのご照会は頂いていないところですので、今後とも周知・啓発に努めてまいりたいと考えています。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に、すまいるスクール運営費でありますが、長期休業中の配食サービスの活用、これはずっと言い続けております。今年も特にまたコロナ禍にあって、様々各ご家庭では工夫をされてお子様の夏を過ごしていただきましたけれども、改めて伺いますが、このすまいるスクールでの長期休業中の配食サービスの活用について、品川区のお考えを教えてください。","respondent":"廣田子ども育成課長","answer":"しかしながら、就業などで忙しいと感じて、何らかの手立てをしてほしいというお声があることは承知をしているところです。仕出し弁当という提案等も頂いているのですけれども、命に関わるアレルギーの対応ができるかというところが最も大切なことだと思われます。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２６０ページ、保育支援費、感染拡大防止対策物品購入経費補助などから、保育所における感染予防についてお尋ねしたいと思います。はじめに、保育所における感染症対策についてお伺いいたします。今まで積み上げられてきた保育所における感染症対策で、今回のＣＯＶＩＤ－１９流行によって大きく変わった点と、変わらなかった点について、まずご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"今後も感染症対策に注意を払いつつ、乳幼児期だからこそ必要な触れ合いや体験等のバランスを取りながら、保育の工夫を重ねていくことが重要かと考えております。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２０２０年１０月に保育現場のための新型コロナウイルス感染症対応ガイドブック第２版が、全国保育園保健師看護師連絡会学術委員会から公表されましたが、保育所こそ、子どもと保育者の三密、スキンシップが最も必要とされる場だと考えますが、ガイドブックの詳細な感染症対応はその真逆であり、このバランスというか、今後どのような方向性を区は目指されているのか、改めてご説明をお願いします。","respondent":"初貝保育教育運営担当課長","answer":"保育所におきましては、委員ご指摘のとおり、子どもと保育者との密接な関わりが重要と認識しております。現状の感染症対策につきましても、感染症の状況を注視しながら、改善が見られる場合は対策を徐々に緩めていくような検討も今後必要かと考えております。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今回のデルタ変異株流行では、区内の保育所でも職員や園児に多くの検査陽性者が出たと報告されています。保育所における検査陽性者数はいかがでしたか。今回の特にデルタ変異株流行に対して、品川区の保育所におけるＣＯＶＩＤ－１９に対する感染症対策について、ご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"デルタ株流行に対する区内保育園の感染症対策ですが、デルタ株は従来型に比べると感染力が強く、これまで感染しにくいとされた乳幼児も感染しやすいという特徴があることから、感染者が発生した際は迅速に濃厚接触者を特定し、感染者や濃厚接触者の広がりが多い場合は。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"「保健所の助言を踏まえ」ですね。今回のデルタ株流行では、特に私立保育所では陽性者が出たというお知らせと、濃厚接触者か濃厚接触者ではないかという情報しか提供されなかったケースもあり、保護者の不安が広がったようです。個人情報とのバランスは大切だと思われますが、保護者の不安を解消するために、区として何かお考えはあるのでしょうか。","respondent":"若生保育支援課長","answer":"しかしながら、先般保護者への情報提供について、過度に情報を制限するといったような事例があったということで、今後保護者の不安な気持ちを受け止めまして、明らかにできる事実関係についてはきちんと隠さずに伝えるということで、個人情報とのバランスもあるとは思うのですが。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"意見","question":"保護者の方に余計な負担がかからないように、きめの細かいご指導をよろしくお願いしたいと思います。次に、コロナ禍の品川区の病児保育の現状についてお尋ねいたします。この間の品川区の病児保育施設の各施設での預かり数の推移、および利用率をご報告ください。","respondent":"初貝保育教育運営担当課長","answer":"令和３年度４月から８月までの病児保育の実績ですが、利用者の延べ人数および定員に対する利用率は、チャイルドサンタでは１３７名、約１７％になってあります。ひだまりでは４３３名で約５４％。森のおうちでは４０５名、約５８％。こころキッズケアでは７５名で約１３％です。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"意見","question":"チャイルドサンタとひだまりと森のおうちというのは医療機関併設型の病児保育施設で、こころキッズケアというのは保育所併設型の病児保育施設だということも追加でコメントします。この間の各病児保育施設における、新型コロナウイルス感染症の発生件数について、ご報告をお願いします。","respondent":"初貝保育教育運営担当課長","answer":"病児保育施設での新型コロナウイルス感染症の発生に関しましては、現在報告は届いていないという状況です。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"意見","question":"新型コロナウイルス感染症第５波の流行の主要な病原ウイルスであるデルタ変異株は、子どもの間にも容易に感染し、軽症で経過すると報告されています。特に病児保育所は軽症の有症状児を預かる施設のため、新型コロナウイルス感染症のリスクは非常に高いと危惧します。病児保育施設の新型コロナウイルス感染症に対する感染予防対策について、区の把握している範囲で結構ですので、ご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"病児保育施設における新型コロナウイルス感染症の対策に関しましては、まず受け入れの際に、全国病児保育協議会の病児保育施設受入基準等も参考にしながら、最終的にはそれぞれの医師が各自で判断して対応しているというところで、受入れをその後実施していると聞いております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほどのご報告で、品川区の病児保育の預かり数は、保育所併設型を除き、医療機関併設型ではほぼ例年並みだと伺いました。品川区の預かり人数が減らなかったということに関しまして、区としてはどのようにこの事態を捉えているのか、ご見解をお示しください。","respondent":"初貝保育教育運営担当課長","answer":"今後社会情勢の変化等々も踏まえまして改めて検証し、そういった理由等々を確認してまいりたいと考えております。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"確認","question":"これによれば、ア、預かり希望の保護者の１週間の発熱の有無を確認する。もしも保護者に発熱があれば、ＰＣＲ検査または抗原検査が陰性であることを確認して、それから病児の預かりを行う。確認できるまでは病児の預かりはしない。イ、病児が通園している園の流行状況の情報を自治体に請求し、状況を把握する。品川区では病児保育施設に対する情報提供をどのように行われているのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"品川区では現在、病児保育施設に対して、区における新型コロナウイルスの感染状況などの情報の提供は行っておりませんが、今後、病児保育施設より要望が出てきた際は、個人情報保護の視点も踏まえながら、慎重に対応を検討してまいりたいと考えております。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の新型コロナウイルス感染症流行下における病児保育は、一定の役割を果たしたと区はお考えでしょうか。今後、今回のような新興感染症が発生したときの病児保育の役割について、区としては今回の経験を踏まえてどのような役割を期待し、どのように対応されていくとお考えでしょうか。ご説明お願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"今後同様の新たな感染症が発生した場合に関しましても、関係機関と連携を取りながら適切な対応を行い、受入れ態勢を継続できるような形で検討を重ねてまいりたいと考えております。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ありがとうございました。病児保育は必要な施設ですので、これは就労している家庭の施設ではなくて、要するに大事な子育て支援の施設として位置づけて、今後も積極的な活用をお願いしたいと思います。次に、病後児保育について伺います。病後児保育施設は縮小・廃止の方向にあると先日から伺っておりますが、現在もまだ存続しておりますが、今後の病後児保育施設の方向性を再度お伺いしたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"今は新型コロナウイルスの影響がありますので、その辺りの影響、今後の利用者の推移、利用者のニーズ・傾向などを総合的に判断しまして、今後の病後児保育の適切な量の提供でしたり、体制でありましたり、その辺りを見極めてまいりたいと考えております。","id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"基本的に病後児施設はもう歴史的な役割が終わったと思いますので、できれば病児保育に転換できるような積極的な施策をお願いしたいと思いまして、これは要望とします。次の質問を行います。区立保育園の保育士への新型コロナウイルスワクチンの接種はほぼ希望者に完了したとお聞きしましたが、私立の保育所の保育士に対する接種状況はいかがでしょうか。","respondent":"若生保育支援課長","answer":"ただし、現在未接種で、今後接種を希望している職員の方がどれだけいるかというところは、区として把握する必要があると考えてございまして、現在調査をしていますが、若干名はまだ未接種で希望されている方がいると認識しています。","id":"exchange-028"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ぜひ区立保育園、私立保育園を問わず、子どもの保育にあたる保育職員が新型コロナウイルスワクチンをしっかりと接種することで子どもを守るという視点は非常に大切なことだと思いますので、その視点で今後積極的なご検討をよろしくお願いしたいと思います。先ほど何回か議題に上ったと思うのですが、待機児童の現状について、最後に簡単にご説明をお願いしたいと思います。","respondent":"若生保育支援課長","answer":"コロナ禍による保育需要への影響は否定できませんが、先行きは不透明であり、今後も需要の減少が続くのか、あるいは回復するのかを注視しつつ、適切な保育の供給を今後も行ってまいりたいと考えております。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"２３７ページの西大井三丁目グループホーム整備について。２１９ページの避難行動要支援者個別計画作成に係わって、大地震や風水害などの障害がある方の避難と避難生活を支援する個別計画についてお伺いしたいと思います。敷地の購入費は幾らなのか、伺いたいと思います。同じく例えば社会福祉法人の場合、国および東京都からの土地購入費補助制度は何かあるのか伺います。","respondent":"松山障害者福祉課長","answer":"５億１,８４０万３,６４２円です。決算書に記載のとおりです。次に、西大井の土地の取得に関して、国や都からの補助金があるかないかというご質問です。こちらは自治体あるいは社会福祉法人ともに、土地の取得に関して国や都からの補助金というのはございません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、ご説明があったとおり、補助制度がないのですね。それだけ東京の土地が高いのは周知の事実です。品川区として、国、東京都に障害者グループホームの整備にあたっての土地購入費への補助制度創設を求めていただきたいと思いますが、いかがでしょうか。区独自に社会福祉法人の新規整備にあたり、土地購入費への補助制度を創設していただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"今後また区独自ということであれば、適地があるかないかというのもありますので、またそのときに検討していきたいと考えております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"それを理由に、品川区が国や都に求める考えがないというのもあまりにひどい話だと思います。遅れている障害者グループホームの整備へ、国や都に補助制度を作ることを求めていただきたい。そして区としても独自の補助制度の創設を強く求めたいと思います。例えばふれあい祭りのような交流の場面を作れるように進めていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"西大井三丁目に予定のグループホームにつきましては、確かに地域から要望がございました多目的室等、またグループホームの利用者が一緒に交流できるようなことを考えておりますので、将来的には地域になじみのあるグループホームとして。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害時の個別計画を伺いたいと思います。災害時、障害がある方や介護が必要な方などの避難や避難所、または自宅での避難生活の支援について、個別計画の作成を繰り返し求めてまいりました。ここでは特に障害がある方について伺いたいと思いますが、この個別計画の内容は、避難が必要になった際の避難行動への支援と、避難所または在宅での避難生活への支援ということでよいのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"避難と、それから避難所での生活についても、相談員が作成していく中でともに考えていく予定となっております。","id":"exchange-033"},{"speaker":"中塚委員","kind":"確認","question":"今、フォーマットができたということで、避難と避難所とのご説明がありましたが、在宅避難生活への支援もそこに含まれているのか、この点を確認させてください。","respondent":"松山障害者福祉課長","answer":"家庭内の安全対策や家庭内の備蓄等の充実につきまして、日頃の備えにつきましてもともにその中で考えていただくよう促してまいります。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"避難と、あと避難所での生活と、在宅での避難生活ということで、ぜひ一つひとつ進めていただきたいという思いで質問させていただきたいと思います。風水害では、品川区より定められた地域に避難指示が出されます。改めて個別計画の作成にあたり、どのような場合に避難が必要なのか、自宅を安全にすることがなぜ必要なのか、障害がある方やご家族に丁寧な説明が必要だと思いますけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"相談支援員がキーになると考えておりますので、相談支援員の連絡会にて、安全な家庭、いわゆる家具転倒防止等の知識や周知をきちんとし、相談支援員向けに、１１月にしながわ防災学校の中で防災知識の習得およびスキルアップの研修の実施を予定しております。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"併せて、障害によってその対応が変わってくるのは当然です。障害のある方や家族や地域の方に、個別計画の作成と併せて、こうした事前の予防策が大事だということ、被害の発生そのものをなくす、減らすことの対策なくして個別計画の実効性の担保は取れないと思いますので、ぜひ障害者団体を含め、当事者への説明を改めて丁寧に進めていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"その中では震災だけでなく、風水害等も含めた予防策というところでいろいろご意見を頂戴しています。今後とも引き続き障害者団体とも理解を深め、丁寧な説明を図っていきたいと考えております。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"家具だけでなく、具体的にどういう取組みが必要なのか、障害の種別に応じて具体化していくことが求められると思います。災害が発生したときにこういう対応が必要だという理解そのものが地域に必要だと思いますので、様々積み上げられたマニュアルとでもいうのでしょうか、そうしたものを地域で共有できるように、公開ができるように進めていただきたいと思いますが、最後にいかがでしょうか。","respondent":"松山障害者福祉課長","answer":"障害特性別の避難の在り方、あるいは安全対策については、団体と丁寧にまずは意見交換を積み重ねていきたいと考えております。","id":"exchange-037"},{"speaker":"くにば委員","kind":"提案","question":"２４５ページ、産後家事育児支援、産後ドゥーラに関してです。２７１ページ、ホームレス緊急保護事業。時間があれば、２６９ページ、オアシスルーム・ポップンルームの運営等、２５３ページ、保育室等記録機器モデル導入経費等です。産後ドゥーラに関して幾つかご提案がありますので、じっくりやっていきたいと思います。この点についてお伺いいたします。","respondent":"山下子ども家庭支援センター長","answer":"下期につきましては、今おおよそ内々にお伺いしているところでは２桁にわたる方が受講を予定されていると耳にしておりますので、受講を終えて、２月ないし３月ぐらいから従事いただけるものと考えているところです。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問・要望","question":"それで今回、１０月に一斉に登録がされましたら、ぜひともこれをＳＮＳで広報していただきたいという旨をお伝え申し上げます。やはりまず登録をされても、ホームページを逐一更新していないとどうしてもその新規登録が分からないといったシステムになっておりますので、このＳＮＳでの広報についてご見解をお聞かせください。","respondent":"山下子ども家庭支援センター長","answer":"今の委員のご指摘につきましては、新たにドゥーラに登録された機会を通じてというタイミングかと思いますので、そちらについては今後考えてまいりたいと存じます。","id":"exchange-039"},{"speaker":"くにば委員","kind":"提案","question":"今ちょっとご提案申し上げたのは一斉登録ということで、恐らく１桁台後半が登録されるということで、そのタイミングで一回一斉にＳＮＳでそのお知らせをしていただきたいというところで、今申し上げた随時登録があった際にお知らせが行くような形で、例えばその申込み、新着のお知らせをメールで受け取れるような仕組みを作っていただければ、本日新たに１名の方が提携事業者として登録しました。","respondent":"山下子ども家庭支援センター長","answer":"ご指摘のような一旦集約した形での情報提供というのができるかというところに課題はありますけれども、新着のお知らせをプッシュ式の形でお送りするというところについては、考えてまいりたいと存じます。","id":"exchange-040"},{"speaker":"くにば委員","kind":"質問・要望","question":"結局それが絵に描いた餅のように、せっかく時間を拡大したのに、対象の申込者がいなかったら、事業者がいなかったら、もうこれはある意味区の責任というか、そこまで見込めていなかったという部分になりますので、そこの責任という意味合いも含めまして、例えば１歳に到達するまでに使えなかった方に対して、時限的な特例措置として、例えば半年程度、１歳までなのですが１歳半までに繰越しというか。","respondent":"山下子ども家庭支援センター長","answer":"ただいま委員よりご提案のございました時限的に対象期間を延ばすというところにつきましては、このドゥーラ、産後家事育児支援という事業が産後間もないお母様方の手助けをしていきたい、守っていきたいというところの趣旨からしますと、少し難しいかなと考えるところです。","id":"exchange-041"},{"speaker":"くにば委員","kind":"提案","question":"その縛りはもちろん設けまして、そうでないと、登録をして１０万円をもらって終わりみたいな形になってしまいますので、そこに関してはそういう縛りの下、例えば登録だけではなく、初年度の利用時間、サービス提供時間が１００時間を超えたら、１００時間を超えた段階で１０万円分を提供するなど、そういった形のインセンティブを与える施策について、今ご提案申し上げたところについて。","respondent":"山下子ども家庭支援センター長","answer":"ドゥーラ協会等々と連携しまして、対応にあたってまいりたいと存じます。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう一点、今、利用助成はあくまで利用者に対して上限３,０００円の助成ですけれども、例えば品川区在住の方にサービス提供した事業者に１時間当たり１,０００円の上乗せをするであるとか、そういったインセンティブを与えて、実際に品川区の利用者に対して、サービスを提供する方を掘り起こすということが、やはり何かしらの施策で必要だと考えていますので。","respondent":"櫻木生活福祉課長","answer":"こちらで把握させていただいているホームレスの数です。日によってというところと、あと夏と冬でも変わるところではあるのですが、おおむね平成３０年から令和２年にかけては１２名から１３名という形で推移してきているところです。","id":"exchange-043"},{"speaker":"くにば委員","kind":"意見","question":"以前に比べるとやはり大分減ったという印象ですけれども、ちなみにそれらの方々を含めまして以前品川区にホームレスとしていらした方々、品川区内は例えば特定の公園もしくは河川敷等で大量にホームレスがたまっているところとかはあまりないと思うのですけれども、そういったホームレスの方々がたまっていたところ、こういったところにホームレスがいたという事例をお教えください。","respondent":"櫻木生活福祉課長","answer":"区内において一定数以上たまっているような場所というのはないのですが、現状ですと、いわゆる道路の高架下であったりガード下であったり、もしくは品川、荏原、大井、八潮地区の公園等に散在しているという状況です。","id":"exchange-044"},{"speaker":"くにば委員","kind":"質問","question":"１点質問があります。国民健康保険に加入していないホームレスの方、ホームレスの方で多くそのケースはあると思うのですけれども、いわゆる品川区内で行き倒れになっている方、住所不定だけれども、品川区の管轄内で、保険に入っていない、けれども医療費はもちろんお金がないといった方が保護された場合、品川区としてその医療費に関して、どういった対処をなさっているのか、お聞かせください。","respondent":"櫻木生活福祉課長","answer":"行き倒れになられている方に関しては、救急搬送された後に、意識があるような状況ですと生活保護のほうで費用をみるということもありますし、あとは行旅医療という制度がございまして、行旅のほうで費用を出すということも可能性としては考えられると考えています。","id":"exchange-045"},{"speaker":"くにば委員","kind":"意見","question":"分かりました。ホームレスの方もやはりそれぞれの事情があって、生活保護を受けたくないという方もいらっしゃいますし、ではそういった方々の医療費を医療機関からの借金という形にしているのか様々問題はあると思いますので、そこに対してご相談があれば、生活保護以外の選択肢もご検討してみてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"２４１ページ、児童センター事業費。２４５ページ、子ども・若者応援事業。２４３ページ、すまいるスクール運営費。２５５ページ、のびしなプロフェッショナルスクール。２６３ページ、保育士等キャリアアップ補助金、遊技場提供支援事業、園庭等整備費助成。順不同で伺います。特別児童扶養手当について伺います。生活困窮家庭の診断書費用負担について、支援策を求めたいのですが、見解を伺います。","respondent":"伊東子育て応援課長","answer":"この手当の申請に関しましても、一時的ということにはなりますけれども、自己負担ということで、金額的にも５,０００円から１万円というような範囲かと思われますので、それは個人での対応ということでお願いをしたいと考えています。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"診断書の出費については仕方ないと思っているのです。ぜひ前向きによろしくお願いします。次に、すまいるスクールについて伺います。すまいるスクールの事故報告書を区へ求めたところ、データとして整理されておらず、担当課で積み上がっている状態とのことで、情報公開ができませんでした。事故報告書は項目ごとに分類し、今後の施策に活かせるよう確認ができるように改善すべきですが、見解を伺います。","respondent":"廣田子ども育成課長","answer":"保護者から声が上がってきた場合には区民の声と同様に扱いますけれども、保護者の方と意見交換をいたしまして、その内容、子どもの状況、学校との意見交換をしながら、一つひとつ丁寧に対応をしているという状況です。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"事故報告書についてです。ですので、こういう項目で事故報告書をくださいと言ったら、すぐ出せるようにきちんと項目を分けてやっていただきたいと思います。このようにすまいるスクール職員から子どもへの体罰について相談があったときには、体罰があったとされるすまいるスクールだけでなく、すべてのすまいるスクールに注意を促すことが必要だと考えますが、区の見解を伺います。","respondent":"廣田子ども育成課長","answer":"いじめ等の通報はどこから来たとしても、匿名で来たとしても、ある程度分かる情報がありましたらあたりをつけて調査を、どこかわからなければ全すまいるスクールにこのような事案がなかったかという問い合わせをするなど、一つひとつ洗い出しをしていますので。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"すまいるスクールの委託事業者との契約書、仕様書を確認しました。体罰やいじめがあった場合の報告書の作成も仕様書で求めるべきと考えますが、見解を伺います。仕様書では、区が業務員の業務遂行上、言葉遣い等不適切な児童指導や保護者対応などに問題があると認めた場合には、受託者に業務員の改善の措置を求めることができるとあります。ここでの区とは誰のことを指すのでしょうか。","respondent":"廣田子ども育成課長","answer":"仕様書にあるように、言葉遣いであるとかそういう場合については、先ほどより申し上げているとおり、１件１件その場でリアルタイムで対応する、また月ごとの月次報告の中で報告書と対面で行う必要があれば。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"本当にそのとおりだと思います。すまいるスクール内で解決した事案だとしても、再発防止や施行向上のため報告書を作成し、区へ報告させるべきと考えますが、こちらについて見解を伺います。各学校のすまいるスクールの様子や、ヒヤリハットや事故などの情報共有を行い、児童の健全育成の向上につなげられるよう、すまいるスクール同士で意見交換ができる機会が必須だと思いますが、見解を伺います。","respondent":"廣田子ども育成課長","answer":"現場の日々の行いについては、報告書が日報という形でも上がってきます。学校までも全部回しています。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"保育園事業について伺います。その公定価格について、区の認識を伺います。しかし、都のキャリアアップ補助金を受けるときに、区や都が事業者に求めている財務情報の保育従事職員給与支出を情報開示して調べたところ、区内認可保育園の保育従事職員の平均年額は、３３０万円程度でした。区は私立園各園で、公定価格から研修時の保育士補填がされているのかどうかの確認をどのように行っているのか伺います。","respondent":"若生保育支援課長","answer":"それに対して、先ほどご指摘いただいたのは国の公定価格上の運営に要する費用という通知です。こちらは、令和３年度の通知で、年度の乖離がありますので、ここで比較するのはちょっと違うのかなと認識しています。","id":"exchange-052"},{"speaker":"木村委員","kind":"質問","question":"私からは２２５ページの高齢者社会参加促進事業、１,３３１万円余からです。このコロナ禍、外出自粛のため、中止の事業もあると思いますけれども、その中で高齢者作品展は、高齢者の得意としている作品を競い合うということではなく、多くの人々に見ていただくことを目的にしていることと思いますし、また高齢者の励みにもなると、そういう事業だと思いますけれども、本来の目的は何でしょうか。","respondent":"菅野高齢者地域支援課長","answer":"高齢者作品展についてのご質問に答えします。高齢者が制作した作品を展示し、生きがいづくりに役立てることを目的としております。","id":"exchange-053"},{"speaker":"木村委員","kind":"質問","question":"簡単な答弁で。確かに高齢者の生きがいですよね。私も何か一つ生きがいを持たなければと思いますけれど、そういう才能がありませんので、持てませんけれども。聞くところでは１００を超える、多分１１１チームあるとお聞きしましたけれども、本区にはそんなに多くのチームが参加できるような大会があるのかどうか、またそれはどのようにして参加するのか、それをお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"実際に昨年度の９月に、西大井広場公園でグラウンドゴルフ大会が行われたのですが、やはりコロナ禍で密を避けるということも考えまして、通常ですと約２００名の参加者でやっている大会ですが、このときに関しては半分の９６名という参加者で実施させていただきました。","id":"exchange-054"},{"speaker":"木村委員","kind":"質問・要望","question":"ご丁寧にありがとうございました。５０幾つかのチームしか参加できないということですか、先ほど何とおっしゃったか分からなかったのですけれど、参加できないチームというのは、地域だけで、自分たちだけでゲームを楽しむという集まりになりますけれども、全ての参加ができないわけであります。","respondent":"菅野高齢者地域支援課長","answer":"グラウンドゴルフ大会についてのご質問です。こちらの参加チームは、昨年度は１６チームということで、かなり限定された方たちの参加となっているのが実情です。各地区におきましても、グラウンドゴルフ大会は行われています。","id":"exchange-055"},{"speaker":"木村委員","kind":"質問・要望","question":"そして毎日を健康に過ごすということは大変大事なことだと思いますので、ぜひ頑張っていただきたいと思います。次にいきいき健康マージャン広場も、大変人気があると思いますけれど、このコロナ禍でも実際に行っている事業なのでしょうか。４人がマージャン台を囲み、数時間ゲームを楽しむ。ウイルスを遮断、または除菌する方法、マージャンゲーム独特の何か方法というものがあるのでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"いきいき健康マージャン広場についてのご質問です。やはり三密を避けることが難しいこと、民間施設がコロナ禍で閉店や移転となってしまったことなどから、なかなか登録者数分の会場を確保することが難しい状況が続いておりまして、令和２年３月より事業を休止している状態です。","id":"exchange-056"},{"speaker":"松本委員","kind":"質問","question":"よろしくお願いします。私からは２４７ページ、奨学金貸付事業、間に合えば、２１７ページ、成年後見制度経費について伺います。奨学金貸付事業についてですけれども、今回の決算書によると、執行率が６５％程度と低調です。令和元年度も約４６％、平成３０年度も６６％と低調ですが、この原因について、区の分析をお伺いいたします。","respondent":"伊東子育て応援課長","answer":"奨学金の執行率ですけれども、件数的には、令和２年度に関しては在学応援資金の関係で２０件ということで、令和元年度は１４件ということで、実質的には伸びている状況にあります。","id":"exchange-057"},{"speaker":"松本委員","kind":"確認","question":"平成３０年度から経年で見ていくと、そういう分析になるのかなというところで、どういうことかというと、毎年の予算のほうを確認しますと、事業だと事務費なども含まれるので、貸付金を抜き出して予算を見ていくと、平成３０年度は在学応援資金が始まった年ですけれど、貸付金の予算が８４８万円、平成３１年度が１,４１８万円、ここまでは伸びているのですけれども、令和２年度は１,１００万円。","respondent":"伊東子育て応援課長","answer":"区としては、着実にといいますか、例年どおりの貸付ということで推移していると思っています。なおかつ、微増傾向にあるのかなという分析をしています。","id":"exchange-058"},{"speaker":"松本委員","kind":"質問","question":"予算額が減っている中でそれをおっしゃるのはおかしいと思うのですけれど、もう一度お願いしてよろしいでしょうか。","respondent":"伊東子育て応援課長","answer":"今、私のほうで話したのは、貸付額としての執行に関しては微増傾向にあるということで、事務費関係も含まれておりますので、その辺で増減、昨年でいいますと、事務費の中でシステム改修など時々ありますので、その辺で執行率が変わってくるということはありますけれども。","id":"exchange-059"},{"speaker":"松本委員","kind":"意見","question":"貸付額も下がっているのですね。下がっている額は数万円程度ですけれども、決して伸びているわけではないということで、それで予算を組まれているので。貸付金の予算を組んで、でも執行率が６割とか４割ということで、少なくとも見通しとしては貸付の需要が低いという認識でないと、この下がり方というのはどうなのかなと思うのですが、もう一度お願いします。","respondent":"伊東子育て応援課長","answer":"貸付額として考えましても、平成３０年度が３４５万円余、令和元年度が５７１万円、令和２年度が５６８万円です。今年度に関しましては、上半期の部分で３９０万円の貸付をしています。ですので、奨学金の貸付という中では、増加傾向にあるというふうに認識しているところです。","id":"exchange-060"},{"speaker":"松本委員","kind":"質問","question":"でも、それは貸付と予算との関係で、実際に執行できていないわけです。では執行率がこの低さ、貸付金との関係でも執行率が低い理由というのは、何なのでしょうか。事業全体のシステムの関係とかではなく、貸付金だけ見ても予算との執行率で見ると、かなり低調になっているわけです。この原因の分析を、もう一度お願いいたします。","respondent":"伊東子育て応援課長","answer":"貸付額の予算ですけれども、１,０００万円ほど予算を取っているという状況です。ここ数年、トータル金額的には変わっていないような状況になります。","id":"exchange-061"},{"speaker":"松本委員","kind":"意見","question":"やはり今の答弁はちょっと正確ではないと思います。先ほど申し上げたように、初年度の貸付金の予算は８００万円余で、そこから平成３１年度は一回上がって１,４００万円余になって、その後、令和２年度は１,１００万円、令和３年度は１,０００万円と下がっているのです。下がっているということは、下げている原因があるはずなので、そこの部分をもう一度お願いいたします。","respondent":"伊東子育て応援課長","answer":"失礼しました。一定程度、前年度の実績を基に多少の減額があった中ですけれども、それに対しまして、確かに貸付金額としては低かったというのが、実態です。","id":"exchange-062"},{"speaker":"松本委員","kind":"質問","question":"原因なのです。なぜなのかというところを伺っているのです。予算を立ててそれが執行できていないというところは、申込件数なり、申込額なりが少ない、それは結局、需要があるのか、ないのかというところと関わってくると思うのですが、その原因のところをもう一度お願いいたします。","respondent":"伊東子育て応援課長","answer":"需要という部分でいいますと、それぞれ学校経由で募集をかけているところでございまして、現実的に応募のあった方は、ここ二、三年に関しては、全ての方に貸付を行っているという状況です。","id":"exchange-063"},{"speaker":"松本委員","kind":"意見","question":"分かりました。調べたところ、これは大学のものですけれど、全国高等学校ＰＴＡ連合会とリクルートマーケティングパートナーズが、２０１９年に行った調査によると、日本学生支援機構以外に、各自治体や大学独自の奨学金があることを知っている人というのが、すごく低い。高校生だと４０％程度で、保護者でも６０％程度なのですね。なので、今、どういうふうな周知を行われているのか、お願いいたします。","respondent":"伊東子育て応援課長","answer":"ＰＲに関しましては、広報ですとかホームページに載せることはもちろんですが、学校を経由しまして各生徒にパンフレットを、中学校の段階でお配りしています。","id":"exchange-064"},{"speaker":"松本委員","kind":"質問・要望","question":"ホームページを拝見しますと、申請書類は子育て応援課に来てくださいと、窓口ということになっているのですけれども、例えば高校生が、保護者はそんなに塾のお金とかを出したくないけれど、自分は行きたい、自分で何とか申請書類とかを集めて親を説得したいというときに、平日窓口に行くというのはなかなか大変だと思うのですけれど、郵便等の対応はされているのか、お伺いいたします。","respondent":"伊東子育て応援課長","answer":"ＰＲの時期ですけれども、中学３年生の段階で、入学準備金の関係もありますので、そのタイミングに合わせてＰＲしています。郵便対応もしているところです。","id":"exchange-065"},{"speaker":"湯澤委員","kind":"質問","question":"私からは２２５ページ、高齢者社会参加促進事業、２７１ページ、生活保護費、２７５ページ、生活困窮者自立支援事業について、お伺いします。コロナ禍で様々な事業やイベントが延期、中止となりました。高齢者外出習慣化事業においてもどうであったか、こちらも判断基準などと共にお知らせください。","respondent":"菅野高齢者地域支援課長","answer":"高齢者社会参加促進事業の中の、健康づくり・生きがい活動事業の実施の可否などについてお答えします。こちらは今、５つの事業が記載されておりますが、上から、高齢者作品展、グラウンドゴルフ大会、高齢者輪投げ大会については、昨年度実施しています。","id":"exchange-066"},{"speaker":"湯澤委員","kind":"質問","question":"活動が制限されてしまっている現状において、高齢者が健康を維持しながら、生きがいを持って活動していただくためには、これまで行ってきた取組みの継続も大切ですけれども、今話したように、練習場所がなくなってしまうことがないような支援など、新たな取組みや、安全を確保した上で開催を可能にする基準の見直しなども必要になってくるかと思いますが、いかがでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"私どもとしましては、感染症対策を講じなから実施できるイベント等は、今までも実施してきましたし、今後も工夫したいと考えています。その中で、少しでも高齢者の方たちが、コロナが明けたときに元気でまた活躍してくれることを願っております。","id":"exchange-067"},{"speaker":"湯澤委員","kind":"質問","question":"実際に、８月１日号を見て今も実践されているという方がいらっしゃいます。ぜひ、そういったところも研究していただければと思います。厚生労働省の調査によりますと、コロナの影響で失業率が上がって、６４歳以下の現役世代の生活保護者の増加もあって、申請者数は今年６月時点で、前年同月比の１３.３％増加ということでありますが、品川区における状況はいかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"自立支援につきましては、就労支援員が生活保護になられた方に対して就労指導を行っていくというメニューを、実施しています。","id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そのときに、自立したいという受給者の後押しをしっかりできるような体制を、引き続き図っていただきたいと思います。去年と一昨年の予算書を比べても、年々事業費が下がっているように思います。これはどういった理由なのか、対象者が減っているのか、ほかで補填をされているのか、理由をお知らせください。相談窓口への相談件数が、ここ数年どういった動向なのかも、併せてお知らせください。","respondent":"櫻木生活福祉課長","answer":"相談件数につきましては、自立支援に関しましては暮らし・しごと応援センターで、住居確保給付金の関係の相談数が非常に増えておりまして、令和元年度３,０００件程度であったものが、令和２年度につきましては１万何千件という形で、非常に増えている状況です。","id":"exchange-069"},{"speaker":"湯澤委員","kind":"質問・要望","question":"相談も大変増えているということであります。特にコロナ禍で、とてもお困りの方がたくさんいらっしゃる、そういった不安を抱えている区民はもっとたくさんいるのかもしれない、そういった心積もりで、さらなる周知を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問","question":"私からは２５１ページ、ひとり親家庭支援事業で、離婚の相談について、同じく２５１ページ、しあわせ食卓事業について、時間があれば２３７ページ、障害児者総合支援施設運営費について、伺います。公正証書の作成費用については実績が１件であったと、保証契約については０件だったとお聞きしましたが、お伺いしたいのは、本事業を開始するに当たって、人員体制の強化を行ったと伺っています。","respondent":"伊東子育て応援課長","answer":"離婚の相談件数ということでいいますと、令和２年度に関しましては７９件という相談件数です。それと、体制ですけれども、元家庭裁判所の調査官だった方を雇いまして配置して、個別相談のほうに応じているところです。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"７９件ということで、私としてはかなり多い相談数かなと思いますが、先ほど西村委員の質問にもあったのですが、離婚講座ということについて伺いたいと思います。令和２年度、３年度で、先ほど府中市ですか、事例の紹介がありましたけれども、港区、豊島区、目黒区、文京区、世田谷区などで、同じ名前です。ぜひこういうことをオープンにやっていただきたいと思うのですが、改めてご答弁をお願いします。","respondent":"伊東子育て応援課長","answer":"具体的な講座の開設に関しましては、もう少しその様子を、相談件数の推移等々見ながら、考えていければと思っています。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問","question":"どうぞよろしくお願いいたします。ＡＤＲの活動についても質問しようと思ったのですが、時間がなくなってしまったので、しあわせ食卓事業についてです。最終的に、令和２年度においては何回、食糧の配達をされたのか、また、それぞれ配送された世帯数、また対象者はひとり親だけではないですけれど、対象者の何％ぐらいの世帯に届いたのか、教えてください。","respondent":"伊東子育て応援課長","answer":"しあわせ食卓事業です。令和２年度の実績といたしましては、令和２年５月、６月、令和３年２月、３月ということで４回実施しているところです。それぞれ順番に、世帯数では３２０世帯、３１０世帯、４３３世帯、４３３世帯です。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"４回行っていただいたということ、３０％ぐらいの方に届いたということです。私も議事録を読ませていただきましたけれども、同時期に私も同じご相談を受けて、実際に配送されたお宅というか、伺って、物を見てくれということで、中を見せていただきました。段ボール箱と品物を拝見しました。これは年度契約ということなのでしょうか。契約の形態も教えてください。","respondent":"伊東子育て応援課長","answer":"今年度に関しましては、現在まだ契約という段階には至っておりません。委託というか、配送に関しましては、その都度、その都度の契約となっています。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは数十年前からやっている、ＳＤＧｓなどという言葉がないときからやっている。私も２０代の頃、仕事がなかったからバイトをさせてもらっていたのですけれども。幸いなことに、品川区には社会福祉協議会のネットワークがありますから、そことよくお話をしていただいて、この事業、改めて見直していただいた上で、さらに前進させていただきたいと思うのですけれども、改めてご答弁を伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"その際、今、委員のご指摘にもございましたけれど、やはり現場を知っている方々の意見も当然参考にしながら、取り入れながら、進めていきたいと思っているところです。","id":"exchange-075"},{"speaker":"おくの委員","kind":"質問","question":"私からは、２４７ページ、奨学金貸付事業に関わって、大学生への給付型奨学金および大学生への臨時給付金について質問いたします。これは、国や都の制度で十分だということでしょうか。つまり、国や都の制度があるといっても、不十分な制度なので大学生が困っているということなのですけれども、それでも区は、国や都の制度で十分だと考えているのかということをお伺いしたいのですが、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"大学生向けの奨学金ですけれども、品川区では、高校生向けの奨学金ということで、昭和の時代から実施してきておるところです。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"確かにいろいろな制度はあります。ただ、既存の制度ではまだまだ足りない、だから区にもつくっていただきたいと、大学生の方も思っているし、私自身もそう思ったので、つくっていただきたいという質問をした次第です。これは臨時給付金のような、１回きりの給付だと思いますけれども、書いてありました。改めて、区独自の奨学金、臨時給付金、それぞれいかがでしょうか。お伺いいたします。","respondent":"伊東子育て応援課長","answer":"それと他区の状況ということで、今ご紹介がありましたけれども、さらに国のほうでは、コロナ禍において家計の急変等で厳しい状況に陥ったという方に関しても、臨時的な対応ということで、随時の奨学金受付を行うというようなこともやっております。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問","question":"ということは、今の国や都の制度で十分だと、品川区としては考えられていると、結局はそういうことですか。伺います。","respondent":"伊東子育て応援課長","answer":"十分云々ということよりも、様々な形で支援策はできているです。それを、それぞれの状況に応じて皆様に活用していただきたいです。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問","question":"不十分だからこそ、私は大学生の方々が困っているという実態が出てくるのだと思うのですが、それに加えて、そもそも日本の大学の学費が高いというのが、私は原因になっていると思うのですけれども、区としては、日本の大学の学費が非常に高いのだという認識はおありになるのでしょうか。日本の大学の学費が高いというふうに思っていらっしゃるのか、いないのか、そのことはどうでしょう。伺います。","respondent":"伊東子育て応援課長","answer":"学費が高いかどうかという判断は難しいところですけれども、日本が諸外国に比べて高いのかという観点で考えると、そうなのかもしれないとは思います。","id":"exchange-079"},{"speaker":"おくの委員","kind":"質問・要望","question":"認めていただけたのだと思いますけれども、それなら、それに対する対策ということで、奨学金なり、臨時給付金なりということを考えていただいてもいいのではないかと思うのです。改めて区独自の奨学金なり臨時給付金を考えていただくことを求めますが、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"一般的に言われているのは、諸外国を見たら高いのかなというふうに思っていると、言っただけです。ということで、様々な対策がとられている中で、独自の対策ということは考えていないです。","id":"exchange-080"},{"speaker":"おくの委員","kind":"質問","question":"認めつつ、認めないというような、なぜ認められないのですか。その点、お伺いいたします。日本の大学の学費が高いことを、なぜ認められないのか、もう一度お伺いいたします。","respondent":"伊東子育て応援課長","answer":"学費が高いかどうかということに関しては、この場で私が話すことではないのかなと思っているところです。","id":"exchange-081"},{"speaker":"おくの委員","kind":"質問・要望","question":"日本の学費は世界一高い、そして今の都や国の奨学金の制度では不十分で、困っている学生がいるというのは、一般に認められたことだと思います。これは様々な報道や論文などでも明らかにされていることだと、私は認識しております。区ももう一度考え直して、学生への強い支援、これを求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"子どもたちが大人になってから困ることが少なくなるように、子どもたちの未来につながる支援はとても重要ですので、指定管理者が変わっても予算はしっかりつけていただきたいです。通園も通いたい方が通えず、年に１回だけの方も多くいらっしゃいます。課題は多くありますが、新しい指定管理者にも、来年１０月からこの５つの事業内容を引き継いでいただくご予定でしょうか。","respondent":"築山障害者施策推進担当課長","answer":"次年度の引継ぎにつきましては、年度途中での引継ぎとなりますので、利用者が安心して施設を利用し続けられるよう、現在行っている事業については、そのまま引き継ぐ予定となっております。","id":"exchange-083"},{"speaker":"せお委員","kind":"質問・要望","question":"決してサービスが減ることのないよう、拡充していただきたいと要望いたします。続いては、細かいところですが、何度も取り上げています、その事業内容の中の保育所等訪問支援です。そうすることで、少し幅広く支援ができるのではないでしょうか。現在の対象のお子さんに関して、大まかで結構ですので教えていただくとともに、運営が変わることも含めて、保育所等訪問支援の方向性を教えてください。","respondent":"築山障害者施策推進担当課長","answer":"今後の方向性ですけれども、保育所等訪問支援の利用に当たりましては、相談の中で適切にご案内をしていきまして、必要な方に支援が届くよう、充実を図っていきたいと考えております。","id":"exchange-084"},{"speaker":"せお委員","kind":"意見","question":"午前中にもお話がありましたけれど、巡回訪問とかも大事です。取り扱う事業者が増えないことも課題ではありますが、さらに拡充されていくことを期待しています。次に、放課後等デイサービスですが、ゆうゆうのご説明だと、「知的発達に遅れのない発達特性のある小学校４年生までの学齢児に対し」とあります。なぜそのような対象になっているのか、経緯をお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"こちらにつきましては、これまで区内に民間の放課後等デイサービスの事業所が少なかったということがありまして、知的に遅れのない発達障害のある子に対する、専門的な支援があまりなかったということがありまして、品川児童学園で専門的に実施するために。","id":"exchange-085"},{"speaker":"せお委員","kind":"質問","question":"今は過渡期だと思っています。具体的に、例えばぐるっぽ内の品川児童学園は、ぐるっぽの全部がそうかもしれないですけれどキャパオーバーで、小山台住宅跡地の新施設建設がまだ先なのであれば、以前の戸越ルームのように、どこか少しでも場所を借りて、事業の１つ、２つを取り出してみてはいかがでしょうかと思っています。そのような検討はいかがでしょうか。見解をお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"そのため、現在設置している事業を切り出すということはちょっと難しい、直ちに変更するというのは難しいところがありますけれども、事業所につきましては誘致を図っているところですので、現状の障害児者総合支援施設内の事業に限らず。","id":"exchange-086"},{"speaker":"せお委員","kind":"提案","question":"民間の誘致も積極的に行っていただいて、連携しながら、そういったところの検討をお願いしたいと思っています。人工呼吸器使用者は、災害時には命に直結しますので、自宅に非常用電源を常備しておいたほうがよい、その購入の補助をという提案をいたしました。昨年は保健センターにお聞きしましたが、今回は日常生活用具給付でどうでしょうかという提案ですので、障害者福祉課に見解を伺います。","respondent":"松山障害者福祉課長","answer":"在宅人工呼吸器使用者の災害時非常用電源を、日常生活用具の品目に追加するか、あるいは災害時個別支援計画を作成することという要件をそこに付すかにつきましては、毎年、行っております日常生活用具給付等検討会というものがありますので。","id":"exchange-087"},{"speaker":"せお委員","kind":"質問・要望","question":"検討していただくということです。大事なことですので、ぜひ来年度予算に組み込んでいただきたいと要望いたします。つぎに、高齢者の住宅あっせん事業に関連して、障害者の住宅あっせん事業についてお聞きします。こちらはなぜ利用者がゼロなのか、理由を分析できているようでしたら教えてください。","respondent":"松山障害者福祉課長","answer":"入居可能な物件を紹介いたしますが、ご本人の希望や障害特性によって、物件とのマッチングが難しいということ、また、入居可能な物件の選択肢を広げるためには、物件のオーナーや不動産業者の障害者理解を進めることが、必要と認識しております。","id":"exchange-088"},{"speaker":"せお委員","kind":"質問・要望","question":"理解いたしました。第６期品川区障害福祉計画にも地域移行の目標を設定していますので、そのような課題は、今後１人で地域移行していく障害者へもつながります。この辺の課題に取り組んでいくことも、検討していただくことを要望します。そこで、先ほどの障害者住宅あっせん事業について、今後に向けて条件を見直すことを要望いたしますが、そちらの見解をお聞かせください。","respondent":"松山障害者福祉課長","answer":"住宅あっせんの課題解決についてですけれども、委員ご指摘の音や火事といった配慮事項、あるいはまた別の障害特性を含めた形での障害者理解や、具体的に住宅あっせんをどう進めるかにつきましては、住宅所管課と連携しながら検討してまいります。","id":"exchange-089"},{"speaker":"せお委員","kind":"質問","question":"こちらの住宅あっせん事業の利用者はいないですし、せっかく準備している事業ですので、今後改善をお願いしたいと思っています。一般質問でもお聞きしました、医療的ケア児のすまいるスクールでの受入れです。ですので、例えば各地域で１か所だったり、場所を比較的確保できるすまいるスクールを選んだりと、そのような検討も必要になると思いますが、そこら辺の検討状況があれば、お聞かせください。","respondent":"廣田子ども育成課長","answer":"今後どのぐらいのニーズがあるかというところを把握しながら、今後の方向性については、また研究していきたいと考えています。","id":"exchange-090"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは２２３ページ、福祉人材確保・定着事業、それと合わせて２５１ページ、しあわせ食卓事業についてお伺いします。福祉人材の品川介護福祉専門学校についてお伺いします。我々の会派からも、介護福祉専門学校の定員割れについて、人材確保という観点から毎年要望させていただいておりまして、改めて現状の人数、あと今のこの定員割れの状況に対して、区の評価をまずお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"ただ、そうは言いましても、委員ご指摘のとおり、入学定員に対する入学者数というところでは、やはり引き続きしっかりとＰＲ活動等をして、生徒確保に向けてやっていく必要があるというふうに認識しています。","id":"exchange-091"},{"speaker":"芹澤委員","kind":"提案","question":"例年いつも２０名程度だったのが、今回２４名と少し増えたということで、様々努力をされていらっしゃるのだと思います。品川介護福祉専門学校を卒業された方々に対しては、結構評価が高いと伺っています。我々の会派からも具体的に幾つか提案していまして、それぞれ今の進捗状況をお聞かせいただきたいです。１つ目が、品川介護福祉専門学校で営業職の採用をしてみたらどうかということです。","respondent":"宮尾高齢者福祉課長","answer":"実際には、コロナ禍でなかなか高校訪問が難しいですけれども、その中で、１校でも多くの学校に訪問ができるよう、努力を重ねているです。それから住居確保支援ですけれども、実は社会福祉協議会は、戸数は多くないですけれども、遺贈された物件を有しております。","id":"exchange-092"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ありがとうございました。外国人についても、恐らく外国人材を求めてこられた方ではなく、普通に募集して外国人が来ているのだろうと理解しているのですが、外国人にしっかりアプローチをして、語学のところも研修体制をとって、定員割れを防いでみてはどうかという思いもありますので、ぜひあわせてご検討ください。関連して、しあわせ食卓事業についてもお伺いします。","respondent":"伊東子育て応援課長","answer":"ＳＯＳといいますか、何か相談事があれば、こちらのほうに相談してくださいというようなアプローチはしているところです。職の支援というところも、同じように周知をしているところですけれども、自立支援ということでやっているところです。","id":"exchange-093"},{"speaker":"芹澤委員","kind":"質問","question":"答弁に思いやりが感じられなくて。周知はしている、あちらから来ればやるよというお話ではなくて、貧困家庭に関してはＳＯＳがなかなか出しづらいというのがもともとあって、食品の配送という、非常に易しいきっかけでＳＯＳを出していただいたので、今度はこちらから入っていかないといけないという思いで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは２２５ページ、高齢者社会参加促進事業、２５９ページ、保育従事職員宿舎借上支援事業、この２つをお伺いしたいと思います。高齢者社会参加促進事業ですけれども、この事業のうち、今年度から開始いたしました高齢者のスマホ教室について、お聞きしたいと思います。そこでお聞きいたします。高齢者のスマホの保有状況をお聞きしたいと思います。利用実態が分かれば教えてください。お願いします。","respondent":"菅野高齢者地域支援課長","answer":"課題といたしましては、先ほども申し上げましたが、コロナ禍で定員を６名にしているというところと、コースがまだ少なめということもありまして、倍率が大変高くなっているところが課題ではないかと認識しております。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問","question":"現状、分かりました。ご承知のとおり、昨日も総務費の質疑の中で申し上げましたが、国では９月１日からデジタル庁が発足しておりまして、今後デジタル技術による生活やビジネスの変革、いわゆるデジタルトランスフォーメーションを進めていくことになります。そこで、特に高齢者へのデジタルデバイド対策に関して、どのようなご見解をお持ちでしょうか。今後のスマホ教室の方向性についてもお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"このように、様々な手法で多くの区民の方が、スマホ教室を受講できる機会を図ってきているところです。そうは申し上げても、まだまだ、いろいろなスマホ教室に対する需要等が多いということは認識しているところですので、今後、教室の拡充を検討していきたいと考えています。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご認識、分かりました。そうした意味から、待機児童解消や保護者の就業支援、この一役を担っているのは、保育士も幼稚園教諭も同じだと考えています。先ほど、午前中には西村委員からのご質問もあって、答弁は私立幼稚園の給与水準、あるいは人材確保の困難実態を調べますというお答えでしたが、早急に調査をしていただいて、こうした対策を検討いただきたいと思いますが、いかがでしょうか。","respondent":"若生保育支援課長","answer":"午前中の質疑にもございましたとおり、区として実態のほうをこれから細かく調査させていただいて、どういったところで処遇の差が生じているのかですとか、あるいは幼稚園教諭のほうの人材確保がどの程度難しいのかというところは、今後、丁寧に調べていきたいと考えております。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２２６ページの障害者福祉費に関わって、聴覚障害者支援について伺います。今年、ついに品川区手話言語条例が制定され、当事者の皆さんから大変喜ばれています。本当によかったと思います。今後は、この条例を実効性あるものにしていくことが重要です。そうした思いで質問します。品川区は、手話の理解促進・普及をどのように進めていく考えなのでしょうか。伺います。","respondent":"松山障害者福祉課長","answer":"手話言語条例制定に当たりまして、４つの団体、品川区聴覚障害者協会、手話サークル、品川区登録手話通訳者の会、明晴学園、この４つの団体を中心にこれまでも進めてまいりました。現在ももちろん、その４つの団体と意見交換をしながら、丁寧に進めているところです。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ当事者の方々のお話を聞きながら、進めていっていただきたいと思います。今回、この手話言語条例が画期的だったのは、これまで手話が禁止された歴史があるということです。昔は日本語が身につかないという理由で、学校での手話の使用が禁止されました。こうした差別を繰り返さないために、何が必要だと区は考えているでしょうか。伺います。","respondent":"松山障害者福祉課長","answer":"実際、今は、その歴史的な部分というのは一切ございませんし、例えば、直近で区の職員向けに実施した手話体験講座の中でも、聴覚障害の当事者が講師となりまして、実体験をもとに歴史的な話も交えながら、講義をしていただいたです。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"聴覚障害者協会の方々と懇談をした際に、ろう文化についても理解してほしいという話がありました。こうしたろう文化やこれまでの歴史などを踏まえた、聴覚障害全体の理解を進めていくことが必要だと考えますが、いかがでしょうか。理解促進、差別克服へ、区内でどういう差別や文化があったのか。聞き取りや資料収集をして、冊子を作ることや、講演会の開催を求めますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"全体の中では何かしら、先ほど申しましたように区職員向けに実施した手話体験講座では、ろう文化の講義もあります。例えば時間認識ですね。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"環境整備について伺います。実際に当事者の方が窓口で相談した際に、質問に答えてもらえなかったということです。それとあわせて、障害者福祉課の窓口に手話通訳者が今、月曜日と水曜日の午後、金曜日の午前中にいらっしゃると思うのですが、行く日が限られてしまうということも言われておりますので、ぜひ手話通訳者は毎日いるようにしていただきたいと思うのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"委員ご提案の手話通訳者を毎日配置ということですが、本年度から配置日数を１日増やしまして、現在週３日としております。増やした手話通訳者の利用状況ですとか、区全体の手話通訳者派遣の状況を考えると、今のところすぐに日数を増やすのは難しいと考えております。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、毎日配置できるようにしていただきたいと思いますし、一般の方が手話をできるようにも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"２５３ページ、毎年聞いております、保育園給食放射性物質検査費ですが、これはいつまでやるのですかということ。もう当初の目的は果たされたのではないでしょうか。そして、２５７ページの公設民営化ですが、これの目的は何でしょう。改めてお聞きします。なので、長期休業のときはその思いにはせて、しっかりと親の役割を果たすため、これは親教育の一つではないでしょうか。私の考え方は古いのでしょうか。","respondent":"初貝保育教育運営担当課長、廣田子ども育成課長","answer":"今後に関しましては、また状況を鑑みまして、一旦休止という方向で検討しておりますが、社会情勢等々を鑑みまして検討してまいりたいと考えております。仕出し云々に対しましては、区がやりたい、やりたくないという以前の問題で、実施に関して現時点では課題が多いと考えているというお話です。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"民営化の話です。なぜ民営化するのですか。公立保育園の意味は何でしょうか、ということです。そういうときに保育行政はどう考えていくのですか。民間の活力を活用するのはいいけれども、品川区として、要は保育の質という形になりますけれど、保育行政は今後どう考えていくのですか。子どもが少ないのですから。それをどういうふうに運営していくのですかということをお聞きしています。教育ですから。","respondent":"立木保育課長、廣田子ども育成課長","answer":"そうした意味も含めまして、今後の品川の保育行政、量も含めまして、どういった形でやっていくのかという検討をしてまいりたいと考えています。すまいるスクールにつきましては、お食事の関係ですけれども、保護者のお気持ちも受け止めながら、子どもたちにとって何が望ましいかということを考えながら、努めてまいりたいと考えています。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれありがとうあります。児童センターは本当に私、期待しておりますし、これは大切なので、これからますます役割が大きくなってくると思いますので、お考えいただきたいと思います。お弁当については、教育というのもあります。大変だという気持ちも分かります。でも、親としての役割、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、西本委員の給食の放射性物質検査について、関連質問します。すみません、私のほうも毎回ですが。この不祥事の責任は全て、東京電力と国策として原発を推進してきた国にあります。子どもたちの給食の放射性物質検査はやめるべきではないと考えますが、見解を伺います。測定の継続と併せて、放射性物質を取り込みやすい食材に絞った単品検査への転換を求めますが、あわせて見解を伺います。","respondent":"初貝保育教育運営担当課長","answer":"ただいま委員からご指摘ございました、放射性物質の検査ですが、区では以前から、放射性物質検査を続けているところですけれども、今まで基準値を超える検査結果というのはございませんで、実施体制を見直しながら続けており、本年度も一部検査を続けてありますが。","id":"exchange-106"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、流通している食品は安全ということで、例えば福島などはすごく検査をしています。なので、福島の食材は本当に、今、一番安全だと言われているぐらいです。風評被害もあります。厄介なことに放射性物質は目に見えませんし、無味無臭のため、安全性は検査でしか確認できません。ぜひ、それを行うためにも、区としての検査の継続を求めますが、改めて見解を伺います。","respondent":"初貝保育教育運営担当課長","answer":"委員からご指摘いただきました放射性物質の検査に関しまして、繰り返しの答弁になってしまいますけれども、今まで区としましては、放射性物質の検査を継続してきております。","id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"一定の成果を果たしてきたことは認めます。ですので、今後も継続して、その責任を果たしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"松澤委員","kind":"質問","question":"私からは、成果報告書２８ページの認知症高齢者支援事業、そして時間がありましたらヤングケアラーの質問をしていきます。現在、品川区には約１万８,０００名のサポーターがいらっしゃいます。厚生労働省では２０２０年度に１,２００万人のサポーターを養成したいと数値目標を掲げておりますが、区として、現在の１万８,０００人、この人数をどのように捉えているでしょうか、教えてください。","respondent":"宮尾高齢者福祉課長","answer":"現在、区が実施する養成講座を受講していただいた方を、サポーターとして任命していますが、本年９月末現在で、延べ１万８,５６８人の方に、これまで受講していただいております。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"１万８,５６８人、私は他の区等もいろいろ見ましたけれども、サポーターの人数は着実に増えているのかなと感じております。前回の答弁で、サポーターの活用についてはレベルアップ事業として、認知症の養成講座の講師資格を持つキャラバン・メイトの講習につなげていくような取組みを進めておりますが、これからこのサポーターの皆様の方向性をどのようにしていくのか、教えてください。","respondent":"宮尾高齢者福祉課長","answer":"認知症の正しい理解の普及啓発というのは、国の認知症施策推進大綱でも一番最初に掲げられているように、とても大切なテーマだと認識しております。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"仮に、このキャラバン・メイトの講師をこれから普及させていこうという考えの中で、自治体独自の研修などを開催しているところも多くある中、例えば、品川区では、特に難しいとされる認知症のＢＰＳＤ対応を分かりやすく特化して教える、また、回想法というのですか、昔の経験、思い出を語る、そういう方法を学んでいると思いますが、そういったものに限らないで、コミュニケーション技法だったり。","respondent":"宮尾高齢者福祉課長","answer":"サポーターの大きな特徴として、気軽にこの講座を受けていただける内容であること、これも一方で重要な視点ですので、委員からいただいたご提案も含めて、受講しやすさとの兼ね合いといったことも考えていく必要があると考えています。","id":"exchange-111"},{"speaker":"松澤委員","kind":"意見","question":"講師研修というのは、私も学びの進化と捉えます。このような活動をしている団体も多くありますので、行政のほうでサポーターをはじめ、しっかりとこういった団体などを紹介していただいて、ボランティア活動のきっかけをつくる、知ってもらう、このような取組みから進めていければ、認知症の人との出会いがない、活動がない、そういった課題に対して進めていけると思いますが、ご見解をお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"それを踏まえた上で、一方で、やる気のある方といいますか、もっと学びたい、関わりたい、サポーターとしてしっかり活動していきたい、こういった方がより具体的なご自身の活動イメージを持てるようにというのも、しっかりと取り組んでいかなければいけないと認識しています。","id":"exchange-112"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２４５ページの児童相談所移管推進事業、２６８ページの生活保護費から伺いたいと思います。児童相談所移管のほうですけれども、児童虐待の報道が様々出ていまして、またこの間コロナ禍で増えているのではないかと思うのですけれども、その辺の令和２年度と、また令和３年度の現状の相談、また虐待の発生件数等の状況を教えていただきたいと思います。","respondent":"山下子ども家庭支援センター長、櫻木生活福祉課長","answer":"ご質問いただきました品川区の児童家庭相談、虐待を含めての実施状況です。令和２年度につきましては、相談総数として１,０５９件ございました。そのうち、虐待は６４７件ございました。支障ということですが、令和２年中の緊急事態宣言等が発令された間は、なかなか家庭訪問が緊急の場合を除いて実施しづらいという状況がございましたので、それに代わるものとして。","id":"exchange-113"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これについて、分かる範囲で結構ですけれども、なぜ守れなかったのか。それから、生活保護のほうです。これについてどうなのだという声も挙がっている。台東区ですとか板橋区、新宿区などは実際に会えるまでそれは数に入れないというところもあるそうですけれども、大変な中、件数も多い中で、実際どうすればいいのかというのもあるのですが、品川区の場合はどのように考えるかということを教えてください。","respondent":"山下子ども家庭支援センター長、櫻木生活福祉課長","answer":"これがまた（仮称）品川区立児童相談所ができた場合には、やはりその見守りでありましたり、連携という部分でより円滑に進むものと考えていますので、そのような体制を構築し。生活保護受給世帯については、定期的にケースワーカーが家庭訪問をさせていただいているところですが、原則として訪問回数につきましては。","id":"exchange-114"},{"speaker":"たけうち委員","kind":"意見","question":"江戸川区は１２年前にやはり小学１年生の児童虐待があって、それを区が救えなかったということで、いち早く児童相談所を立ち上げて、今取り組んでいる中でそのようなＡＩを活用した電話対応なども今日報道されていましたけれども、今後品川区もこういったものも含めてまた様々な対応で、そのときの江戸川区の反省としてはやはり救える命を救えなかったという。","respondent":"加島児童相談所移管担当課長","answer":"重篤化しやすいケースを過去の相談対応などの記録から統計・分析し、対応できるという点が一番の利点だと考えています。区立児童相談所は開設当初、年若い職員で支えていくことになりますので、そういったツールの活用についても区のほうで研究してまいりたいと考えております。","id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２５３ページの区立保育園運営費で、休日保育の申請手続きについて伺いたいと思います。２７１ページの生活保護費の扶養照会について伺いたいと思います。それから、２３７ページの児童発達支援センターについても伺いたいと思います。区立保育園の休日保育の手続きについて伺いたいと思います。いつ改善されたのか、また改善の中身はどういう改善になったのか、確認させていただきたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"今、委員にご指摘いただいた休日保育の受付方法の変更に関しましては、区のほうでも、平素からもこのコロナ禍でも利便性の向上を考えておりました。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうしましたら、いつ改善されたのか、その時期についても伺いたいと思います。それから、そうするとその申請書は、今までは自宅で書くようにということではもらえなかったのですけれども、もらって自宅で書いて、例えばこの方ですと６時とか７時とかに保育園に迎えに行くときに出しても大丈夫だということで確認させていただいてもよいでしょうか。そのことと、改善された時期について伺います。","respondent":"初貝保育教育運営担当課長","answer":"改善された時期ですけれども、保育園のほうには９月１８日以降周知をしておりますので、それ以降、そういった形で保育園のほうでは対応を変えているところです。１７時以降に出していただいても構わないというような形で対応を変更しています。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多くの保護者が大変な中で子育てをしているという状況の中で、できる限り保護者を応援するという思いで、保護者のこういった声にも耳を傾けていただいて、改善できるものは改善していただくということで、その姿勢で今後ともしていただきたいということをお願いしておきたいと思います。２つ目の生活保護の扶養照会について伺います。援助が得られることになったのは１年間で何件だったのか、伺います。","respondent":"櫻木生活福祉課長","answer":"扶養照会のお尋ねです。令和２年度につきましては、新規の生活保護の申請者数は４５７人となります。うち、扶養照会を行った人数はちょっと分からないですが、件数としましては９８２件です。うち、援助を得られましたのは３件です。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この扶養照会そのものも、前に比べたら大分減ったのかと思うのですけれども、１,０００件近くやって援助が得られたのは３件ですから、そもそもこの扶養照会そのものが必要なのかどうなのかということを改めて見直す時期ではないかと私は思います。これは改正されたわけです。これが現場で徹底されていないという思いがしているので、これをどう徹底されているのか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"この通知が来た段階で、課内の係長会を通じて相談員およびケースワーカーに定期的に周知を行っているところです。今後も適切な生活保護の実施に向けて、周知を図ってまいります。","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はかなり生活保護の相談が多くて、生活福祉課に一緒に相談に行く機会が多いのですけれども、私はこれが徹底されているようには思えないのです。私はそういう場合は、扶養義務の履行が期待できる人以外は照会しませんからということを徹底してほしいのです。大丈夫ですよと言っていただきたいのです。そこのところを改めて徹底していただきたいと思うのですが、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"区としましては国・都の通知に則って、それに沿って運用しているところですので、個々の現場の相談員等にもその旨周知して運用していきたいと考えています。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、そういう機会をしっかりと持って、ケースワーカーの経験の蓄積に組織的に取り組むということをしていただきたいと私は要望させていただきたいと思います。これだけはっきりと年度まで明記しているので、令和２年度決算ではこの総括が必要ではないかと思うのですが、なぜできなかったのか、計画実行にどのような努力をされたのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"ただ、引き続き第２期の計画に基づきまして、積極的に２か所目の児童発達支援センターに取り組んでいきたいと考えています。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"よろしくお願いします。それから時間があれば、区立保育園のネット環境をお尋ねしたいと思います。もちろんお子さん自身のためにも非常に意味のある事業であると、拡充していただきたいという思いで質問します。先ほども少しありましたが、回数増は必要、また増やすというのが成果報告書にそれぞれ出ていましたが、改めて回数増の見通しについて、お尋ねします。","respondent":"初貝保育教育運営担当課長、若生保育支援課長","answer":"一方で特別支援児も増加傾向ですので、各園のニーズを聞き取りながら、来年度も様子を確認しながら、需要を見ながら、適切な巡回をしていく形で考えております。私立保育園の巡回相談につきましても、毎年度新規園ができている、その都度新規園もプラスして回数を増加してきているところです。来年度以降につきましても、拡充してまいりたいと考えております。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。そういった成果のある非常に意義のある事業ですので、今のご答弁にありましたような形で、お子様のニーズに合わせて事業拡大していただきたいと思います。ただ、継続的で安定した事業とするために、この事業の制度的な担保がどうなっているのかというのを確認したいのですが、公立保育園、公立幼稚園、私立幼稚園では経常的経費という形になっています。","respondent":"黒田財政課長","answer":"経常化の考え方につきましては、回数の増減があるとか、今後増やしていくということであれば、一定程度経年推移を見るということもありますので、そういった編成の中で、必要な経費について、一部経常化しているものもあります。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校心理士の巡回相談ですが、保育園、幼稚園のうち、私立保育園だけが行われていません。これは特別支援教育において、保育園、幼稚園と小学校の円滑な接続のために、５歳児の相談体制を整備していただいています。この学校心理士による就学のこういった指導の適切な観点から、学校心理士による私立保育園への５歳児の巡回体制を求めたいのですが、いかがでしょうか。","respondent":"若生保育支援課長","answer":"小学校への接続といったところでの学校心理士の巡回相談の必要性も区としては認識していますので、今後その検討を進めてまいりたいと考えております。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"保育園は保護者の方が区と契約し、区が民間業者に保育委託をしております。それと、もう一つの先ほどあった臨床発達心理士のほうの巡回ですが、今度は逆に公私立の保育園だけですね。ほかの施設では臨床発達心理士の巡回相談が行われていないのですが、いろいろ人材の関係もあるのかもしれませんが、今後どのような見通しでしょうか。","respondent":"初貝保育教育運営担当課長、若生保育支援課長","answer":"臨床発達心理士のほうの巡回相談に関しましては、例えばぷりすくーる西五反田ですけれども、先ほどお話がありましたが、巡回相談は現在もやっておるところです。臨床発達心理士による巡回相談ですが、私立幼稚園のほうは現在行っていないところです。こちらについては、幼稚園の状況をよく注視して、今後考えてまいりたいと思います。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"臨床発達心理士の方の巡回相談が現在行われていない施設に関しては、今後巡回相談を行うような形で検討していっていただきたいと思います。ともに非常に重要で、意義のある事業だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-126"},{"speaker":"渡辺委員","kind":"確認","question":"２２９ページ、障害者理解・普及啓発事業ということで伺います。主に、先ほど出ました手話言語条例の制定と併せて伺います。その確認をまずさせてください。そんなところで、これはこれで学校教育のところですが、所管として、障害者福祉が理解されるにあたって、このパラリンピック等の影響などをどのように感じ取っているか、あるいはどのように期待しているかを教えてください。","respondent":"松山障害者福祉課長","answer":"私からは、障害者理解についてお答え申し上げます。障害者理解・普及啓発事業、この予算外でどの事業でも障害者理解というのを行っているのではないかという委員のご指摘、そのとおりです。特に障害者の方の場合は、施設に通っていらっしゃることがあります。","id":"exchange-127"},{"speaker":"渡辺委員","kind":"質問","question":"当事者の方、先ほど来答弁もあった４団体中心にという中でも、それぞれの方で共通しているのがこれからだと、スタートだと。より多くの方に理解してほしい、知ってほしいというメッセージが多分軸だと思います。これはまだまだこれからもいろいろな角度に広がっていくだろうタイミングという意味では、理解と普及事業、今日は決算ですから、この項目で言う大きなレベルアップのタイミングだろうと。","respondent":"松山障害者福祉課長","answer":"電話リレーサービスについてお答え申し上げます。委員ご指摘のとおり、電話リレーサービスが７月１日から、公共インフラとして開始されております。聴覚に障害がある方などからの電話リレーサービスを介した連絡についての対応ということで、区の職員に周知をしたところです。","id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"２１９ページの認知症高齢者支援事業と、２３７ページの障害児者総合支援施設の中の、特に子ども発達相談室について、時間の許す限り確認をします。それから、その講座の内容。内容については、どういう目的といいますか、講座を受講した人に何を身につけていただくのか、知識を得ていただくのか、どのような活動に携わっていただきたいのか、そこら辺の目的を確認させていただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"それから実際に予防の効果があると言われている例えば音楽療法ですとか、そういったものを在宅介護支援センターのほうに委託をして実施しています。","id":"exchange-129"},{"speaker":"若林委員","kind":"質問・要望","question":"それで、周知については、要するにいろはのいを学ぶ養成講座の方に対して周知をするということになると思うのですが、そうすると個別に何か郵送等でこういうのがありますけれどもどうですかというふうにやられているのかどうか、そこら辺を一つお聞きしておきたいと思います。すみません、何点か重なりましたけれども、よろしくお願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"ただこれですと、例えばその場にいる方に一回こっきりということにもなりかねないと思いますので、やはり委員のところに実際にご案内が届いていないということも含めまして、周知の在り方については検討してまいりたいと考えています。","id":"exchange-130"},{"speaker":"若林委員","kind":"質問・要望","question":"チームづくりについてもぜひ前向きにご検討いただきたいと思います。発達相談はちょっと間に合いませんので、引き続き最後の１問は認知症検診についてお尋ねしますが、１つだけ、これは国保医療年金課のほうにお聞きします。いわゆる介護と保険の一体的な事業の実施という部分で言うと、これは大変結びつきが強いのだろうと思いますけれども、今後の考え方だけ教えてください。","respondent":"池田国保医療年金課長、渡部委員長","answer":"こちらについては、来年度を見据えて活動を進めていきたいと思っているところです。次は、大倉委員ですが、本日欠席のため、次に進めします。質疑を続けます。次に、藤原委員。","id":"exchange-131"},{"speaker":"藤原委員","kind":"質問","question":"２２３ページ、福祉人材確保について。そして、７５歳以上の老老介護の割合も３３.１％になったというのですけれども、改めて、この傾向はこれから増えていくのでしょうか、減っていくのでしょうか。この辺について、品川区はあともう少し、２０２４年開設予定ですけれども、人材確保は一番大事なことだと私は思っているのですけれども、その辺についてはいかがでしょうか。","respondent":"宮尾高齢者福祉課長、築山障害者施策推進担当課長、加島児童相談所移管担当課長","answer":"ひとり暮らし高齢者の方、それから老老介護の方、これらにつきましても、やはりそもそもの高齢者の方の絶対数が増えてまいりますので。来年４月からは実際に次期指定管理者の職員が支援の中に入りまして、一緒に取り組んでいきますので。併せまして、来年度、児童相談行政に精通いたしました管理職の下、児童相談所の具体的な運営体制を検討していくために。","id":"exchange-132"},{"speaker":"藤原委員","kind":"質問・要望","question":"ここから私のいつもの質問に移っていきますが、介護士の給料面、私は何回も課長に質問させていただきましたが、何か給料面で変わったことはあるのでしょうか。児童相談所ですけれども、改めてもう一回伺いますが、人材に関して、本当にその人材確保をちゃんとできるようにしていただきたいと思っています。できませんでしたでは、それは大変だと思うので、ぜひその辺についてもう一言答弁をお願いします。","respondent":"宮尾高齢者福祉課長、加島児童相談所移管担当課長","answer":"直接お給料の面で、例えば区が何か賃金アップを図るとか一律にというようなところは、ちょっと委員のお考えには添えないかもしれませんが、そういったことを例えば今年度の予算で対応させていただいているかというと、しておりません。現在、人事課から５名の応募があったと承っておりまして、決して楽観視するわけではございませんが、きちんと選考を行いまして、必要な人材の確保に努めていきたいと考えております。","id":"exchange-133"},{"speaker":"藤原委員","kind":"質問","question":"安心しました。これを見守っていきたいと思います。それと、課長、いろいろな特別委員会で、ある意味しびれるような質問答弁をしてきましたが、大丈夫ですよ。介護士は大丈夫。なぜかというと、これは２６日の発表ですけれども、まだ自民党の総裁選挙前です。岸田さんはこう言った。そして私がもっとうれしかったのは、昨日２１時からＮＨＫを見ていました。課長、その辺についてはいかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"総理大臣のその発言は私も認識しておりまして、大変うれしいことでありますし、喜ばしいことだと考えています。","id":"exchange-134"},{"speaker":"藤原委員","kind":"質問","question":"しかし、受験料は幾らですか。どんどん上がって、今約１万８,３００円です。１万８,３００円と言ったらヘルパーの方の２日分の給料です。これはどう考えてもおかしいと思うのです。受験して資格を取って、もっと福祉のために誇りを持ってプロになっていこうと思う人の受験料が１万８,３００円も取られるのです。なぜならしっかり勉強して受験してくるのだから。いかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"介護福祉士の試験につきましては国家試験ということになりまして、一義的には国が実施しているものです。委員がおっしゃるとおり、受験費用は今年度若干値上がりいたしまして、１万８,３８０円ということで捉えております。","id":"exchange-135"},{"speaker":"安藤委員","kind":"質問","question":"２６８ページ、生活保護費について伺います。先ほどの質疑などでも、生活保護受給世帯数がコロナで増えていると答弁がありましたけれども、コロナ前と直近の、新規申請数や、あと世帯数の推移について改めて伺いたいと思います。お願いします。","respondent":"櫻木生活福祉課長","answer":"コロナ前の令和元年度につきましては、平均世帯数としては４,６４７世帯、令和２年度の平均世帯数は４,５４７世帯で、直近の令和３年８月の世帯数としては４,４７６世帯ということで、月によって増減はありますが、全体の世帯数としては減少しているという状況です。","id":"exchange-136"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問ですけれども、先進自治体を参考に、「ためらわずに相談してください」、「生活保護は国民の権利です」などの明記、また制度そのものの内容が分かるものにこのしおりを早急に改善して、それを来所せずとも見られるようにホームページに掲載するよう求めますが、いかがでしょうか。この利用を呼びかけるポスターなどを作成し掲示するということも有効だと思いますけれども、併せていかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"生活保護のしおりにつきましては、ここ数年、生活保護行政をめぐる状況は様々議論等が重ねられている状況でして、それを受けましてこちらのほうでもその状況を踏まえながら改訂の検討をしている状況ですので。","id":"exchange-137"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはすぐにやっていただきたいのですけれども、いかがでしょうか。もう一つ併せて、最後、ケースワーカーについて伺いたいのですが、職員の数は決算書に書いていますけれども、ケースワーカーの人数、あとそのうち有資格者の方の人数、あと正規職員と会計年度任用職員の内訳。","respondent":"櫻木生活福祉課長","answer":"周知方法について、メディア特性等も踏まえながらどのような形で周知すればいいのか、考えてまいります。","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２１９ページ、午前中もちょっと質疑があったと思うのですけれども、避難行動要支援者個別計画作成、２１９ページ、高齢者の熱中症予防対策事業、２３７ページ、ヘルプカード作製・配布についてお尋ねしていきたいと思います。これ、当初予算ですと９００万円となっていますが、決算は２１２万円ということで、昨年度どういう取組みをしたのかということをまず最初にお聞きしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"令和２年度の取組みですけれども、昨年度から防災課にも入っていただいて、部内で災害対応検討の組織化をいたしまして、様々な角度から高齢者、障害者の方たちに対する避難に関することもそこで議題として取り扱っているところです。","id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そうすると、特にお１人で暮らしている方に対して把握できていない町会・自治会もあると思います。所管が違ったらすみません。そういう登録を希望されない方に対してはやりようがないと思うのですが、どういう考えで区はこれから先、取り組んでいくのかということをお知らせいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"今年度、実際に町会・自治会のそういった防災面に対する取組みと、あるいは我々、福祉の関係者、具体的にはケアマネジャーになるのですが、ケアマネジャーと実際に意見交換をする場を設けたい、実際に設ける予定で今考えています。","id":"exchange-140","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よく分かりました。ぜひよろしくお願いいたします。これは予防への個別の支援ということで、熱中症予防の対策を講じることが困難な高齢者の方に、給水等を必要に応じて提供しているということで、これは夏季期間というのは、昨日も一昨日も暑い日が続いて、これも熱中症になるのかと思ったのですけれども、夏季というのは、今期に限って言うと令和３年度はもうこの予防事業は終了しているということですか。","respondent":"宮尾高齢者福祉課長","answer":"一義的には夏季ということで、もちろん熱中症が起きやすい時期ということで夏季と明記していますけれども、人によってもそうですし、年によってもそうですし、一概にいつからいつまでというふうに厳密に区切ってしまうというのは、もちろんある程度の目安として、例えば７月。","id":"exchange-141"},{"speaker":"高橋（伸）委員","kind":"質問","question":"どうもありがとうあります。分かりました。それと、冷却マットとか扇風機の貸し出しもしていますよということですけれども、令和２年度のそういう貸出というのは、大まかでいいのですが、数を教えていただければと思います。","respondent":"宮尾高齢者福祉課長","answer":"ちょっと今具体的に詳しい台数というのはわからないですけれども、必要に応じて在宅介護支援センターと、あと高齢者福祉課にも数台貸出用というのを備えてあります。","id":"exchange-142"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ継続的にやっていただきたいと思います。２３７ページ、ヘルプカード作製・配布についてお尋ねします。そこで２点質問します。今のこれが２点です。これも関連して、これは恐らく全庁的にやっていると思うのですけれども、職員に対してどの程度定期的にそういう研修、また別の所管になるともしかしたら認識されていない方もいると思うので、それを確認のためにお尋ねしたいと思います。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"私から、ヘルプカードについてお答え申し上げます。配布場所につきましては、先ほど委員ご指摘の保健センター、支え愛・ほっとステーションのほかに、区内の障害者の相談支援事業所が１８か所ありまして、合計３５か所で配布しています。職員への研修につきましては、毎年新入職員に実施しているほか、意識調査ということで、全職員に対しても毎年実施しています。","id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"私は、２３７ページ、障害児者福祉施設管理経費、これはインクルーシブひろばベルについてお伺いいたします。それから２４７ページ、子どもすこやか医療費助成事業、これについては高校生等入院医療費助成について伺います。もう一点、認知症高齢者支援事業、これについてはコロナ禍において、今どのような状況になっているのかということでの確認的な質問をさせていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"そしてもう一つ大きな目的が、インクルーシブに地域の子どもたちと交流する場というところで、医療的ケアが必要な障害のあるお子さんとその保護者の地域での暮らしを支援するという大きな目的があります。","id":"exchange-144"},{"speaker":"塚本委員","kind":"質問","question":"当事者でなければ分からない部分というのはやはり交流する中で、地域の人とか健常者の方がどういった方たちなのかという理解が深まるというところが、すごく有意義な価値のある施設なのかと思います。今回決算の結果では、４７件、３００万円余ということで、予算額と決算額の間に少し乖離があるのかなと思います。ここについてなぜかということをお伺いしたいと思います。","respondent":"伊東子育て応援課長","answer":"なぜ乖離があるのかというところですけれども、制度がスタートして間もないということもあるかと思いますが、ＰＲに関しては制度開始のときに様々な形でＰＲしたところですので、行き届いているのかなとは思いますが、令和２年度に関してはコロナ禍の関係もあって。","id":"exchange-145"},{"speaker":"塚本委員","kind":"質問・要望","question":"高額療養費などと比べるのは、向こうは全国の仕組みですからあれですけれども、高額な医療費を超えてくれば必ず病院のほうからそういう案内があるので、そういったような、せめて品川区内の病院においてこの制度についてしっかり周知等がなされているのかどうか。もしそういったことにまだ不十分なところがあるというのであれば、今後しっかりと取り組んでいただきたいと思いますけれども、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"周知のところですけれども、病院のほうに関しましては、制度開始のときにチラシの配布とかで制度が新しくできたという周知はしているところです。","id":"exchange-146"},{"speaker":"塚本委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。そういう中で、今、それから１年経ちましたけれども、この認知症高齢者支援事業等につきまして、今、実施状況というのはどのような状況になっているのか、現状を確認させていただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"いずれにしましても、そういったハイブリッドと言うのでしょうか、組み合わせをしていきながら、しっかりと目的達成のために推進をしていきたいと考えています。","id":"exchange-147"},{"speaker":"塚本委員","kind":"確認","question":"高齢者福祉部門でどこまでそこら辺を掌握しているか分からないですけれども、品川区全体の高齢者の接種などは９割を超えてきているというところで、こういったことの進捗が、認知症の方はなかなか本人の意思が確認できないというような課題はあると思うのですけれども、一方で家族の了解を得れば打てるというようなこともあるので、そういったことも含めて。","respondent":"宮尾高齢者福祉課長","answer":"高齢者の方々は確かにワクチン接種を一番最初に始めさせていただいたというところもありますので、かなり早く進んでいると認識しております。実際に、感染状況等もしっかりと見据えつつ、できるものをできる形でしっかりと進めていきたいと考えています。","id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、２５３ページ、保育園運営費からお伺いしたいと思います。併せて、２４１ページの児童センターのところをお伺いしたいと思います。なぜかと聞いたら、午前中はやはり家事をやったりしてどうしてもお昼、では午後一緒に出てこようかと。ここはこういうところに特化しているのだ、そういうところを私は作っていくべきではないかと思っておりまして、併せてそれもお伺いできればと思います。","respondent":"初貝保育教育運営担当課長、廣田子ども育成課長","answer":"今後長い目で見た保育需要のところも含めて、在り方等々を検討すべきではないかというのは考えているところです。委員ご指摘のとおり建物が老朽化してまいりまして、築４０年以上、築５０年以上というところが出てきておりますので、今後の再編。","id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の児童センターのほうですけれども、どうしてこのようなことを聞いたかというと、一本橋保育園が今度建替えをやるという話で、どのようにするのかなと思っていたら、前とほとんど同じ感じでいきますよというようなお話だったのです。そういう意味では、これからそういう場面も出てくると思うので、ぜひよろしくお願いしたいと思います。答弁があれば、後で伺います。予備があるから、１６教室使っている。","respondent":"立木保育課長","answer":"保育園の建替えの部分ですけれども、やはりここは施設敷地の有効活用等、それから数の供給のところを検討しながら、今後どのような形で建替えを進めていくのか、数の供給をどのようにしていくのか、そこら辺を総合的に在り方という形で検討していく必要があると考えております。","id":"exchange-150"},{"speaker":"石田（秀）委員","kind":"質問","question":"ありがとうございました。ぜひよろしくお願いします。最後に２１９ページ、あまりに認知症高齢者の話が多いので、少しだけ伺います。医者は、例えばもうお一人では生活できないですよと。これはもうこのままではあれだから、ショートステイに少し長く入れたらどうですかと。ある人にしたら、ショートステイに入れるともっと認知症が進んでしまうのではないですかと言う人もいる。そこら辺を教えてください。","respondent":"宮尾高齢者福祉課長","answer":"やはり認知症の進行具合、度合いによって、例えばある程度症状が進んだ方に対してサポーターの方がというのは、なかなかそれはちょっと難しいのかなと。そういうときは、適切に介護保険サービス等にご案内するなどして対応してまいりたいと思います。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/685794?Template=document&Id=1504#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":112261,"voices":349}}]);
